import React from 'react';

const MoreView = ({ onChangeView, installPrompt, isInstalled }) => {

  const handleInstall = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    await installPrompt.userChoice;
  };

  return (
    <div className="min-h-screen" style={{ background: '#f8f9fa', paddingBottom: '80px' }}>
      <div className="px-4 pt-5 pb-3">
        <h2 className="text-lg font-bold text-gray-800">อื่นๆ</h2>
      </div>

      <div className="px-4 space-y-3">
        <button
          onClick={() => onChangeView('login')}
          className="w-full bg-white rounded-2xl p-4 flex items-center gap-4 shadow-sm"
        >
          <div className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0"
            style={{ background: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)' }}>
            <i className="fas fa-user-shield text-white text-xl"></i>
          </div>
          <div className="text-left flex-1">
            <p className="font-bold text-gray-800">เจ้าหน้าที่</p>
            <p className="text-gray-500 text-sm">เข้าสู่ระบบจัดการข้อมูล</p>
          </div>
          <i className="fas fa-chevron-right text-gray-400"></i>
        </button>

        <button
          onClick={() => onChangeView('prevention-stats')}
          className="w-full bg-white rounded-2xl p-4 flex items-center gap-4 shadow-sm"
        >
          <div className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0"
            style={{ background: 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)' }}>
            <i className="fas fa-chart-bar text-white text-xl"></i>
          </div>
          <div className="text-left flex-1">
            <p className="font-bold text-gray-800">ข้อมูลสถิติ งานป้องกัน</p>
            <p className="text-gray-500 text-sm">สถิติการแจ้งเหตุและการปฏิบัติงาน</p>
          </div>
          <i className="fas fa-chevron-right text-gray-400"></i>
        </button>

        {/* ปุ่มติดตั้งแอป */}
        {isInstalled ? (
          <div className="w-full bg-white rounded-2xl p-4 flex items-center gap-4 shadow-sm opacity-60">
            <div className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0"
              style={{ background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)' }}>
              <i className="fas fa-check text-white text-xl"></i>
            </div>
            <div className="text-left flex-1">
              <p className="font-bold text-gray-800">ติดตั้งแอปแล้ว</p>
              <p className="text-gray-500 text-sm">แอปถูกติดตั้งในเครื่องของคุณแล้ว</p>
            </div>
          </div>
        ) : installPrompt ? (
          <button
            onClick={handleInstall}
            className="w-full bg-white rounded-2xl p-4 flex items-center gap-4 shadow-sm"
          >
            <div className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0"
              style={{ background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)' }}>
              <i className="fas fa-download text-white text-xl"></i>
            </div>
            <div className="text-left flex-1">
              <p className="font-bold text-gray-800">ติดตั้งแอป</p>
              <p className="text-gray-500 text-sm">เพิ่มลงหน้าจอหลักเพื่อใช้งานได้เลย</p>
            </div>
            <i className="fas fa-chevron-right text-gray-400"></i>
          </button>
        ) : (
          <div className="w-full bg-white rounded-2xl p-4 flex items-center gap-4 shadow-sm">
            <div className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0"
              style={{ background: 'linear-gradient(135deg, #6b7280 0%, #4b5563 100%)' }}>
              <i className="fas fa-mobile-alt text-white text-xl"></i>
            </div>
            <div className="text-left flex-1">
              <p className="font-bold text-gray-800">ติดตั้งแอป</p>
              <p className="text-gray-500 text-sm">กด ⋮ → "เพิ่มในหน้าจอหลัก" ใน Chrome</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default MoreView;
