import React, { useState } from 'react';
import MapView from './MapView';
import UsageView from './UsageView';
import ExtinguisherDetailView from './ExtinguisherDetailView';

const ExtinguisherMenuView = ({ onBack, allExtinguishers, stats, currentExtinguisher, onSearch, onShowHistory }) => {
  const [subView, setSubView] = useState(null);
  const [searchInput, setSearchInput] = useState('');
  const [showScanner, setShowScanner] = useState(false);

  React.useEffect(() => {
    if (showScanner) {
      import('html5-qrcode').then(({ Html5Qrcode }) => {
        const html5QrCode = new Html5Qrcode("qr-reader-ext");
        html5QrCode.start(
          { facingMode: "environment" },
          { fps: 10, qrbox: { width: 250, height: 250 } },
          (decodedText) => {
            html5QrCode.stop().then(() => {
              setSearchInput(decodedText);
              setShowScanner(false);
              onSearch(decodedText);
              setSubView('search');
            });
          },
          () => {}
        ).catch(() => {
          alert('ไม่สามารถเปิดกล้องได้');
          setShowScanner(false);
        });
        return () => html5QrCode.stop().catch(() => {});
      });
    }
  }, [showScanner]);

  if (subView === 'detail') {
    return <ExtinguisherDetailView extinguisher={currentExtinguisher} onBack={() => setSubView('search')} />;
  }

  if (subView === 'map') {
    return <MapView extinguishers={allExtinguishers} stats={stats} onChangeView={(v) => v === 'info' ? setSubView(null) : null} />;
  }
  if (subView === 'usage') {
    return <UsageView onChangeView={(v) => v === 'info' ? setSubView(null) : null} />;
  }

  const handleSearch = () => {
    if (searchInput.trim()) {
      onSearch(searchInput);
      setSubView('search');
    }
  };

  return (
    <div className="min-h-screen" style={{ background: '#f8f9fa' }}>

      {/* QR Scanner Modal */}
      {showScanner && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-gray-800">สแกน QR Code</h3>
              <button onClick={() => setShowScanner(false)}
                className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center">
                <i className="fas fa-times text-gray-600"></i>
              </button>
            </div>
            <div className="bg-gray-900 rounded-lg overflow-hidden mb-4">
              <div id="qr-reader-ext" style={{ width: '100%' }}></div>
            </div>
            <p className="text-sm text-gray-600 text-center">วางกล้องให้ตรงกับ QR Code</p>
          </div>
        </div>
      )}

      {/* Search section */}
      <div className="bg-white mx-4 mt-4 rounded-2xl p-6 shadow-sm">
        <div className="flex items-center justify-between mb-5">
          <button onClick={onBack} className="w-8 h-8 bg-gray-100 hover:bg-gray-200 rounded-full flex items-center justify-center text-gray-500">
            <i className="fas fa-arrow-left text-sm"></i>
          </button>
          <div className="text-center flex-1">
            <div className="w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-2"
              style={{ background: 'linear-gradient(135deg, #f97316 0%, #dc2626 100%)' }}>
              <i className="fas fa-fire-extinguisher text-white text-lg"></i>
            </div>
            <h2 className="text-base font-bold text-gray-900">ค้นหาข้อมูลถังดับเพลิง</h2>
            <p className="text-gray-500 text-sm mt-1">กรุณาใส่รหัสถังดับเพลิงที่ต้องการค้นหา</p>
          </div>
          <div className="w-8"></div>
        </div>

        <input
          type="text"
          value={searchInput}
          onChange={(e) => setSearchInput(e.target.value.toUpperCase())}
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          placeholder="ใส่รหัสถัง เช่น FE-001"
          className="w-full px-4 py-3 border border-gray-200 rounded-xl text-center font-mono text-gray-700 focus:border-blue-400 focus:outline-none mb-3"
          style={{ fontSize: '15px', background: '#f9fafb' }}
        />

        <div className="flex gap-2">
          <button onClick={handleSearch}
            className="flex-1 py-3 text-white rounded-xl font-bold text-base flex items-center justify-center gap-2"
            style={{ background: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)' }}>
            <i className="fas fa-search"></i> ค้นหา
          </button>

          <button onClick={() => setShowScanner(true)}
            className="flex-1 py-3 text-white rounded-xl font-medium text-sm flex items-center justify-center gap-2"
            style={{ background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)' }}>
            <i className="fas fa-qrcode text-white"></i> สแกน QR
          </button>
        </div>

        {/* ผลการค้นหา */}
        {currentExtinguisher && subView === 'search' && (
          <div className="mt-4 bg-gray-50 rounded-xl p-4 border border-gray-100">
            <div className="flex items-center gap-2 mb-3">
              <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center">
                <i className="fas fa-check text-green-600 text-sm"></i>
              </div>
              <h4 className="font-bold text-gray-800">พบข้อมูลถังดับเพลิง</h4>
            </div>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-gray-500">รหัสถัง</span><span className="font-mono font-bold">{currentExtinguisher.id}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">ตำแหน่ง</span><span className="font-semibold text-right">{currentExtinguisher.name}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">หมู่</span><span className="font-semibold">{currentExtinguisher.group || ('หมู่ ' + currentExtinguisher.village)}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">บ้านเลขที่</span><span className="font-semibold">{currentExtinguisher.houseNo || '-'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">ประเภท</span><span className="font-semibold text-red-600">{currentExtinguisher.type}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">ขนาด</span><span className="font-semibold">{currentExtinguisher.size || '-'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">สถานะ</span><span className="font-semibold">{currentExtinguisher.status}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">วันติดตั้ง</span><span className="font-semibold">{currentExtinguisher.installDate || '-'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">วันหมดอายุ</span><span className="font-semibold text-orange-600">{currentExtinguisher.expireDate || '-'}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">ตรวจสอบล่าสุด</span><span className="font-semibold">{currentExtinguisher.lastCheck || '-'}</span></div>
            </div>
            <div className="flex gap-2 mt-3">
              <button onClick={onShowHistory}
                className="flex-1 py-2 text-white rounded-lg text-sm font-semibold flex items-center justify-center gap-1"
                style={{ background: 'linear-gradient(135deg, #8b5cf6 0%, #3b82f6 100%)' }}>
                <i className="fas fa-history"></i> ดูประวัติ
              </button>
              <button onClick={() => setSubView('detail')}
                className="flex-1 py-2 text-white rounded-lg text-sm font-semibold flex items-center justify-center gap-1"
                style={{ background: 'linear-gradient(135deg, #f97316 0%, #dc2626 100%)' }}>
                <i className="fas fa-info-circle"></i> ข้อมูลเพิ่มเติม
              </button>
            </div>
          </div>
        )}
      </div>

      {/* วิธีการใช้งาน */}
      <button onClick={() => setSubView('usage')}
        className="mx-4 mt-4 w-[calc(100%-2rem)] rounded-2xl p-4 text-white flex items-center gap-4 shadow-sm"
        style={{ background: 'linear-gradient(135deg, #f97316 0%, #dc2626 100%)' }}>
        <div className="w-12 h-12 bg-white bg-opacity-20 rounded-xl flex items-center justify-center flex-shrink-0">
          <i className="fas fa-book-open text-xl"></i>
        </div>
        <div className="text-left">
          <p className="font-bold text-base">วิธีการใช้งาน</p>
          <p className="text-orange-100 text-sm">ขั้นตอนการใช้ถังดับเพลิง PASS</p>
        </div>
        <i className="fas fa-chevron-right ml-auto opacity-70"></i>
      </button>

      {/* ตำแหน่งถัง */}
      <button onClick={() => setSubView('map')}
        className="mx-4 mt-3 mb-6 w-[calc(100%-2rem)] rounded-2xl p-4 text-white flex items-center gap-4 shadow-sm"
        style={{ background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)' }}>
        <div className="w-12 h-12 bg-white bg-opacity-20 rounded-xl flex items-center justify-center flex-shrink-0">
          <i className="fas fa-map-marked-alt text-xl"></i>
        </div>
        <div className="text-left">
          <p className="font-bold text-base">ตำแหน่งถังดับเพลิง</p>
          <p className="text-green-100 text-sm">แผนที่ตำแหน่งติดตั้งทั้งหมด</p>
        </div>
        <i className="fas fa-chevron-right ml-auto opacity-70"></i>
      </button>

    </div>
  );
};

export default ExtinguisherMenuView;
