import React, { useState, useEffect } from 'react';
import './Header.css';

const Header = ({ user, installPrompt, isInstalled }) => {
  const [userName, setUserName] = useState('');
  const [userPhone, setUserPhone] = useState('');
  const [userVillage, setUserVillage] = useState('');
  const [userAddress, setUserAddress] = useState('');
  const [showSetup, setShowSetup] = useState(false);
  const [showInstallPrompt, setShowInstallPrompt] = useState(false);
  const [tempName, setTempName] = useState('');
  const [tempPhone, setTempPhone] = useState('');
  const [tempVillage, setTempVillage] = useState('');
  const [tempAddress, setTempAddress] = useState('');

  useEffect(() => {
    const name = localStorage.getItem('userName');
    const phone = localStorage.getItem('userPhone');
    const village = localStorage.getItem('userVillage');
    const address = localStorage.getItem('userAddress');
    if (name) setUserName(name);
    if (phone) setUserPhone(phone);
    if (village) setUserVillage(village);
    if (address) setUserAddress(address);

    const isFirstVisit = !phone || !name;
    if (isFirstVisit) {
      setTimeout(() => {
        const ua = navigator.userAgent || '';
        const inApp = /Line|FBAN|FBAV|Instagram|Twitter|MicroMessenger/i.test(ua);
        const hasPrompt = window.__installPromptEvent;
        const alreadyInstalled = window.matchMedia('(display-mode: standalone)').matches;

        if (!alreadyInstalled && (hasPrompt || inApp)) {
          // แสดง popup ติดตั้ง (ทั้ง Chrome และ Line)
          setShowInstallPrompt(true);
        } else {
          // ไม่มี prompt และไม่ใช่ in-app → ไปลงทะเบียนเลย
          setShowSetup(true);
        }
      }, 800);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // รับ installPrompt จาก App.js เมื่อพร้อม
  useEffect(() => {
    if (installPrompt) {
      window.__installPromptEvent = installPrompt;
    }
  }, [installPrompt]);

  const handleInstallClick = async () => {
    const prompt = window.__installPromptEvent || installPrompt;
    if (prompt) {
      prompt.prompt();
      await prompt.userChoice;
    }
    setShowInstallPrompt(false);
    setShowSetup(true);
  };

  const handleSkipInstall = () => {
    setShowInstallPrompt(false);
    setShowSetup(true);
  };

  // ตรวจจับ in-app browser (Line, Facebook, etc.)
  const isInAppBrowser = () => {
    const ua = navigator.userAgent || '';
    return /Line|FBAN|FBAV|Instagram|Twitter|MicroMessenger/i.test(ua);
  };

  const handleOpenInChrome = () => {
    const url = window.location.href;
    // Android: intent URL เพื่อเปิดใน Chrome
    window.location.href = `intent://${url.replace(/^https?:\/\//, '')}#Intent;scheme=https;package=com.android.chrome;end`;
  };

  const handleOpenSetup = () => {
    setTempName(userName);
    setTempPhone(userPhone);
    setTempVillage(userVillage);
    setTempAddress(userAddress);
    setShowSetup(true);
  };

  const handleSave = () => {
    if (!tempPhone || tempPhone.length < 9) { alert('กรุณากรอกเบอร์โทรศัพท์ให้ถูกต้อง'); return; }
    if (!tempName.trim()) { alert('กรุณากรอกชื่อ-นามสกุล'); return; }
    if (!tempVillage) { alert('กรุณาเลือกหมู่ที่'); return; }
    localStorage.setItem('userName', tempName.trim());
    localStorage.setItem('userPhone', tempPhone);
    localStorage.setItem('userVillage', tempVillage);
    localStorage.setItem('userAddress', tempAddress.trim());
    setUserName(tempName.trim());
    setUserPhone(tempPhone);
    setUserVillage(tempVillage);
    setUserAddress(tempAddress.trim());

    // บันทึกไป GAS (เฉพาะครั้งแรก ถ้ายังไม่เคยลงทะเบียน)
    const isFirstTime = !userPhone;
    if (isFirstTime) {
      const GAS_URL = process.env.REACT_APP_GAS_USER_REGISTER_URL;
      if (GAS_URL) {
        const cbName = 'regCallback_' + Date.now();
        const script = document.createElement('script');
        window[cbName] = () => { delete window[cbName]; if (script.parentNode) document.head.removeChild(script); };
        const u = new URL(GAS_URL);
        u.searchParams.append('action', 'registerUser');
        u.searchParams.append('callback', cbName);
        u.searchParams.append('name', tempName.trim());
        u.searchParams.append('phone', tempPhone);
        u.searchParams.append('village', tempVillage);
        u.searchParams.append('address', tempAddress.trim());
        script.src = u.toString();
        document.head.appendChild(script);
      }
    }

    setShowSetup(false);
  };

  return (
    <>
      {/* Install App Modal */}
      {showInstallPrompt && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-sm w-full p-6 text-center">
            <div className="w-20 h-20 bg-blue-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <img src="/sosapp/images/logo1.png" alt="logo"
                className="w-16 h-16 object-contain rounded-xl"
                onError={(e) => { e.target.style.display='none'; e.target.parentNode.innerHTML='<i class="fas fa-mobile-alt text-4xl text-blue-600"></i>'; }} />
            </div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">ติดตั้งแอปลงเครื่อง</h3>
            <p className="text-sm text-gray-600 mb-1">SOS แจ้งเหตุฉุกเฉิน งานป้องกัน</p>
            <p className="text-xs text-gray-400 mb-5">องค์การบริหารส่วนตำบลสระกระโจม</p>

            {isInAppBrowser() ? (
              /* กรณีเปิดจาก Line/Facebook → แนะนำให้เปิดใน Chrome */
              <>
                <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-3 mb-5 text-left">
                  <p className="text-xs text-yellow-800 font-semibold mb-1">
                    <i className="fas fa-exclamation-triangle mr-1"></i>
                    กำลังเปิดใน Line Browser
                  </p>
                  <p className="text-xs text-yellow-700">
                    ต้องเปิดใน Chrome เพื่อติดตั้งแอปลงเครื่อง
                  </p>
                </div>
                <div className="space-y-3">
                  <button onClick={handleOpenInChrome}
                    className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold flex items-center justify-center gap-2 transition-colors">
                    <i className="fab fa-chrome"></i> เปิดใน Chrome
                  </button>
                  <button onClick={handleSkipInstall}
                    className="w-full py-3 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-xl font-medium transition-colors">
                    ใช้งานในแอป Line ต่อ
                  </button>
                </div>
              </>
            ) : (
              /* กรณีเปิดใน Chrome → แสดงปุ่มติดตั้งปกติ */
              <div className="space-y-3">
                <button onClick={handleInstallClick}
                  className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold flex items-center justify-center gap-2 transition-colors">
                  <i className="fas fa-download"></i> ติดตั้งแอป
                </button>
                <button onClick={handleSkipInstall}
                  className="w-full py-3 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-xl font-medium transition-colors">
                  ไม่ติดตั้ง
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Register Modal */}
      {showSetup && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <i className="fas fa-user text-3xl text-blue-600"></i>
              </div>
              <h3 className="text-xl font-bold text-gray-800 mb-2">กรอกข้อมูลผู้แจ้ง</h3>
              <p className="text-sm text-gray-600">เพื่อให้เจ้าหน้าที่สามารถติดต่อกลับได้</p>
            </div>
            <div className="space-y-4 mb-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">ชื่อ-นามสกุล <span className="text-red-500">*</span></label>
                <input type="text" value={tempName} onChange={(e) => setTempName(e.target.value)} placeholder="ชื่อ นามสกุล"
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">บ้านเลขที่</label>
                <input type="text" value={tempAddress} onChange={(e) => setTempAddress(e.target.value)}
                  placeholder="เช่น 123/4"
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">หมู่ที่</label>
                <select value={tempVillage} onChange={(e) => setTempVillage(e.target.value)}
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none">
                  <option value="">เลือกหมู่</option>
                  {[1,2,3,4,5,6,7,8,9].map(n => <option key={n} value={n}>หมู่ {n}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">เบอร์โทรศัพท์ <span className="text-red-500">*</span></label>
                <input type="tel" value={tempPhone} onChange={(e) => setTempPhone(e.target.value.replace(/[^0-9]/g, ''))}
                  placeholder="08XXXXXXXX" maxLength="10"
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none text-center text-lg font-mono" />
                <p className="text-xs text-gray-500 mt-1 text-center"><i className="fas fa-lock mr-1"></i>เก็บไว้ในเครื่องของคุณเท่านั้น</p>
              </div>
            </div>
            <div className="flex gap-3">
              <button onClick={() => { if (userPhone && userName) setShowSetup(false); }} className="flex-1 px-4 py-3 bg-gray-200 hover:bg-gray-300 text-gray-700 rounded-lg font-medium">
                {userPhone && userName ? 'ยกเลิก' : 'ต้องลงทะเบียนก่อน'}
              </button>
              <button onClick={handleSave} className="flex-1 px-4 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium">
                <i className="fas fa-save mr-2"></i>บันทึก
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Main Header */}
      <header className="app-header">
        <div className="header-content">
          <div className="logo-container">
            <img src="/images/logo1.png" alt="องค์การบริหารส่วนตำบลสระกระโจม" className="municipality-logo"
              onError={(e) => { e.target.style.display = 'none'; }} />
          </div>
          <div className="header-text">
            <h1 className="municipality-name">องค์การบริหารส่วนตำบลสระกระโจม</h1>
            <p className="system-title">งานป้องกันและบรรเทาสาธารณภัย</p>
            <p className="system-title">สำนักปลัด อบต.</p>
          </div>
          {user && (
            <div className="header-admin">
              <i className="fas fa-user-shield"></i>
              <span>{user.name}</span>
            </div>
          )}
        </div>
      </header>

      {/* Reporter Card - ซ่อนเมื่อ login เป็นเจ้าหน้าที่ */}
      {!user && <div className="reporter-card">
        {userPhone ? (
          <>
            <div className="reporter-info">
              <i className="fas fa-user-circle reporter-icon"></i>
              <div>
                <span className="reporter-label">ผู้แจ้งเหตุ</span>
                <span className="reporter-name">{userName || userPhone}</span>
                {(userAddress || userVillage) && <span className="reporter-sub">{userAddress && `${userAddress} `}หมู่ {userVillage} &nbsp;|&nbsp; {userPhone}</span>}
              </div>
            </div>
            <button onClick={handleOpenSetup} className="reporter-edit-btn">
              <i className="fas fa-edit"></i> แก้ไข
            </button>
          </>
        ) : (
          <>
            <div className="reporter-info">
              <i className="fas fa-user-circle reporter-icon reporter-icon-empty"></i>
              <span className="reporter-empty-text">ยังไม่ได้ลงทะเบียนผู้แจ้งเหตุ</span>
            </div>
            <button onClick={handleOpenSetup} className="reporter-register-btn">
              <i className="fas fa-user-plus mr-1"></i> ลงทะเบียน
            </button>
          </>
        )}
      </div>}
    </>
  );
};

export default Header;
