import React, { useState } from 'react';

const GAS_USER_URL = process.env.REACT_APP_GAS_USER_URL;

const callGASJSONP = (url, params) => {
  return new Promise((resolve, reject) => {
    const cbName = 'gasCallback_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
    const script = document.createElement('script');
    const timer = setTimeout(() => {
      delete window[cbName];
      if (script.parentNode) document.head.removeChild(script);
      reject(new Error('timeout'));
    }, 15000);
    window[cbName] = (data) => {
      clearTimeout(timer);
      delete window[cbName];
      if (script.parentNode) document.head.removeChild(script);
      resolve(data);
    };
    const u = new URL(url);
    u.searchParams.append('callback', cbName);
    Object.keys(params).forEach(k => u.searchParams.append(k, params[k]));
    script.src = u.toString();
    script.onerror = () => { clearTimeout(timer); delete window[cbName]; reject(new Error('script error')); };
    document.head.appendChild(script);
  });
};

const LoginView = ({ onLogin, onBack }) => {
  const [mode, setMode] = useState('login'); // 'login' | 'register'
  const [phone, setPhone] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [name, setName] = useState('');
  const [inviteCode, setInviteCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  React.useEffect(() => {
    const savedPhone = localStorage.getItem('adminPhone');
    const savedPassword = localStorage.getItem('adminPassword');
    if (savedPhone && savedPassword) {
      setPhone(savedPhone);
      setPassword(savedPassword);
      setRememberMe(true);
    }
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!phone.trim() || !password.trim()) { setError('กรุณากรอกเบอร์โทรและรหัสผ่าน'); return; }
    setLoading(true); setError('');
    try {
      const result = await callGASJSONP(GAS_USER_URL, { action: 'login', phone, password });
      if (result.success) {
        if (rememberMe) {
          localStorage.setItem('adminPhone', phone);
          localStorage.setItem('adminPassword', password);
        } else {
          localStorage.removeItem('adminPhone');
          localStorage.removeItem('adminPassword');
        }
        onLogin({ id: result.user.id, name: result.user.name, phone: result.user.phone, role: 'admin' });
      } else {
        setError(result.message || 'เบอร์โทรหรือรหัสผ่านไม่ถูกต้อง');
      }
    } catch {
      setError('ไม่สามารถเชื่อมต่อได้ กรุณาลองใหม่');
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    if (!name.trim() || !phone.trim() || !password.trim() || !inviteCode.trim()) {
      setError('กรุณากรอกข้อมูลให้ครบ'); return;
    }
    if (password !== confirmPassword) {
      setError('รหัสผ่านไม่ตรงกัน กรุณากรอกใหม่'); return;
    }
    setLoading(true); setError('');
    try {
      const result = await callGASJSONP(GAS_USER_URL, { action: 'register', name, phone, password, inviteCode });
      if (result.success) {
        alert(`✅ สมัครสมาชิกสำเร็จ\nรหัสผู้ใช้: ${result.userId}`);
        setMode('login');
        setPhone(phone);
        setPassword('');
        setName('');
        setInviteCode('');
      } else {
        setError(result.message || 'สมัครไม่สำเร็จ');
      }
    } catch {
      setError('ไม่สามารถเชื่อมต่อได้ กรุณาลองใหม่');
    } finally {
      setLoading(false);
    }
  };

  const inputClass = "w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:outline-none transition-all";

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-50 to-indigo-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="w-20 h-20 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-full flex items-center justify-center mx-auto mb-4 shadow-lg">
            <i className="fas fa-user-shield text-3xl text-white"></i>
          </div>
          <h1 className="text-2xl font-bold text-gray-800 mb-2">
            {mode === 'login' ? 'เข้าสู่ระบบเจ้าหน้าที่' : 'สมัครสมาชิกเจ้าหน้าที่'}
          </h1>
          <p className="text-gray-600">ระบบจัดการถังดับเพลิงชุมชน</p>
        </div>

        {/* Tab */}
        <div className="flex bg-gray-100 rounded-xl p-1 mb-4">
          <button onClick={() => { setMode('login'); setError(''); }}
            className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${mode === 'login' ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>
            เข้าสู่ระบบ
          </button>
          <button onClick={() => { setMode('register'); setError(''); }}
            className={`flex-1 py-2 rounded-lg text-sm font-semibold transition-all ${mode === 'register' ? 'bg-white shadow text-blue-600' : 'text-gray-500'}`}>
            สมัครสมาชิก
          </button>
        </div>

        <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-red-700 text-sm mb-4">
              <i className="fas fa-exclamation-circle mr-2"></i>{error}
            </div>
          )}

          {mode === 'login' ? (
            <form onSubmit={handleLogin} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-phone mr-2"></i>เบอร์โทรศัพท์</label>
                <input type="tel" value={phone} onChange={e => setPhone(e.target.value.replace(/[^0-9]/g, ''))}
                  className={inputClass} placeholder="08XXXXXXXX" maxLength="10" disabled={loading} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-lock mr-2"></i>รหัสผ่าน</label>
                <div className="relative">
                  <input type={showPassword ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)}
                    className={inputClass + ' pr-12'} placeholder="รหัสผ่าน" disabled={loading} />
                  <button type="button" onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                    <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                  </button>
                </div>
              </div>
              <label className="flex items-center gap-3 cursor-pointer">
                <div className={`w-5 h-5 border-2 rounded flex items-center justify-center flex-shrink-0 transition-all ${rememberMe ? 'bg-blue-600 border-blue-600' : 'bg-white border-gray-300'}`}>
                  {rememberMe && <i className="fas fa-check text-white text-xs"></i>}
                </div>
                <input type="checkbox" checked={rememberMe} onChange={e => setRememberMe(e.target.checked)} className="sr-only" />
                <span className="text-sm text-gray-600">จดจำรหัสผ่าน</span>
              </label>
              <button type="submit" disabled={loading}
                className="w-full bg-gradient-to-r from-blue-500 to-indigo-600 text-white py-3 rounded-lg font-semibold disabled:opacity-50">
                {loading ? <><i className="fas fa-spinner fa-spin mr-2"></i>กำลังตรวจสอบ...</> : <><i className="fas fa-sign-in-alt mr-2"></i>เข้าสู่ระบบ</>}
              </button>
            </form>
          ) : (
            <form onSubmit={handleRegister} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-user mr-2"></i>ชื่อ-นามสกุล</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)}
                  className={inputClass} placeholder="ชื่อ นามสกุล" disabled={loading} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-phone mr-2"></i>เบอร์โทรศัพท์</label>
                <input type="tel" value={phone} onChange={e => setPhone(e.target.value.replace(/[^0-9]/g, ''))}
                  className={inputClass} placeholder="08XXXXXXXX" maxLength="10" disabled={loading} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-lock mr-2"></i>ตั้งรหัสผ่าน</label>
                <div className="relative">
                  <input type={showPassword ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)}
                    className={inputClass + ' pr-12'} placeholder="รหัสผ่าน" disabled={loading} />
                  <button type="button" onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                    <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                  </button>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-lock mr-2"></i>ยืนยันรหัสผ่าน</label>
                <div className="relative">
                  <input type={showConfirmPassword ? 'text' : 'password'} value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)}
                    className={inputClass + ' pr-12'} placeholder="กรอกรหัสผ่านอีกครั้ง" disabled={loading} />
                  <button type="button" onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                    <i className={`fas ${showConfirmPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                  </button>
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2"><i className="fas fa-key mr-2"></i>รหัสเชิญ</label>
                <input type="text" value={inviteCode} onChange={e => setInviteCode(e.target.value)}
                  className={inputClass} placeholder="รหัสเชิญ" disabled={loading} />
              </div>
              <button type="submit" disabled={loading}
                className="w-full bg-gradient-to-r from-green-500 to-emerald-600 text-white py-3 rounded-lg font-semibold disabled:opacity-50">
                {loading ? <><i className="fas fa-spinner fa-spin mr-2"></i>กำลังสมัคร...</> : <><i className="fas fa-user-plus mr-2"></i>สมัครสมาชิก</>}
              </button>
            </form>
          )}
        </div>

        <div className="text-center mt-6">
          <button onClick={onBack} className="text-gray-600 hover:text-gray-800 font-medium">
            <i className="fas fa-arrow-left mr-2"></i>กลับหน้าหลัก
          </button>
        </div>
      </div>
    </div>
  );
};

export default LoginView;
