import React, { useState, useEffect } from 'react';

const GoogleMapView = ({ extinguishers, selectedGroup, focusLocation }) => {
  const [mapLoaded, setMapLoaded] = useState(false);
  const [userLocation, setUserLocation] = useState(null);
  const [map, setMap] = useState(null);

  // กรองถังดับเพลิงตามหมู่ — รองรับทั้ง group "หมู่ X" และ village เป็นตัวเลข
  const filteredExtinguishers = selectedGroup === 'ทั้งหมด'
    ? extinguishers
    : extinguishers.filter(ext => {
        const g = ext.group || ('หมู่ ' + ext.village);
        return g === selectedGroup;
      });

  // Pan map เมื่อ focusLocation เปลี่ยน
  useEffect(() => {
    if (map && focusLocation && focusLocation.lat && focusLocation.lng) {
      map.panTo({ lat: focusLocation.lat, lng: focusLocation.lng });
      map.setZoom(17);
    }
  }, [focusLocation, map]);

  // โหลด Google Maps API (ลบ script เก่าก่อน)
  useEffect(() => {
    // ลบ script เก่าทั้งหมด
    const existingScripts = document.querySelectorAll('script[src*="maps.googleapis.com"]');
    existingScripts.forEach(script => {
      if (script.parentNode) {
        script.parentNode.removeChild(script);
      }
    });
    
    // ลบ callback เก่า
    delete window.initGoogleMaps;
    delete window.google;

    const apiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
    
    if (!apiKey) {
      console.warn('Google Maps API Key not found');
      return;
    }

    // สร้าง script ใหม่
    const script = document.createElement('script');
    script.src = `https://maps.googleapis.com/maps/api/js?key=${apiKey}&libraries=geometry`;
    script.async = true;
    script.defer = true;
    
    script.onload = () => {
      console.log('✅ Google Maps loaded successfully');
      setMapLoaded(true);
    };
    
    script.onerror = () => {
      console.error('❌ Failed to load Google Maps');
      setMapLoaded(false);
    };
    
    document.head.appendChild(script);

    return () => {
      // Cleanup
      if (script.parentNode) {
        script.parentNode.removeChild(script);
      }
    };
  }, []);

  const getStatusColor = (status) => {
    const colors = {
      'ready': '#10b981',
      'normal': '#10b981',
      'ปกติ': '#10b981',
      'check': '#ef4444',
      'abnormal': '#ef4444',
      'ผิดปกติ': '#ef4444',
      'expired': '#f59e0b',
      'หมดอายุ': '#f59e0b',
      'maintenance': '#3b82f6'
    };
    return colors[status] || '#10b981';
  };

  const getStatusText = (status) => {
    const statuses = {
      'ready': 'พร้อมใช้',
      'normal': 'พร้อมใช้',
      'ปกติ': 'พร้อมใช้',
      'check': 'ผิดปกติ',
      'abnormal': 'ผิดปกติ',
      'ผิดปกติ': 'ผิดปกติ',
      'expired': 'หมดอายุ',
      'หมดอายุ': 'หมดอายุ',
      'maintenance': 'ซ่อมบำรุง'
    };
    return statuses[status] || 'พร้อมใช้';
  };

  // สร้างแผนที่เมื่อ Google Maps โหลดเสร็จ หรือเมื่อ filteredExtinguishers เปลี่ยน
  useEffect(() => {
    if (!mapLoaded || !window.google || !window.google.maps) return;

    const mapContainer = document.getElementById('google-map');
    if (!mapContainer) return;

    const validExtinguishers = filteredExtinguishers.filter(ext => ext.lat && ext.lng);
    if (validExtinguishers.length === 0) return;

    const centerLat = validExtinguishers.reduce((sum, ext) => sum + ext.lat, 0) / validExtinguishers.length;
    const centerLng = validExtinguishers.reduce((sum, ext) => sum + ext.lng, 0) / validExtinguishers.length;

    const mapInstance = new window.google.maps.Map(mapContainer, {
      center: { lat: centerLat, lng: centerLng },
      zoom: 15,
      mapTypeId: 'roadmap',
      streetViewControl: true,
      fullscreenControl: true,
      mapTypeControl: true,
      zoomControl: true
    });

    setMap(mapInstance);

    // เพิ่มหมุดสำหรับแต่ละถังดับเพลิง
    validExtinguishers.forEach((ext) => {
      const marker = new window.google.maps.Marker({
        position: { lat: ext.lat, lng: ext.lng },
        map: mapInstance,
        title: `${ext.id} - ${ext.name}`,
        icon: {
          path: window.google.maps.SymbolPath.CIRCLE,
          scale: 10,
          fillColor: getStatusColor(ext.status),
          fillOpacity: 1,
          strokeColor: '#ffffff',
          strokeWeight: 2
        }
      });

      // สร้าง InfoWindow
      const infoWindow = new window.google.maps.InfoWindow({
        content: `
          <div style="padding: 10px; max-width: 250px;">
            <h3 style="margin: 0 0 8px 0; color: #1f2937; font-size: 16px; font-weight: bold;">${ext.id}</h3>
            <p style="margin: 4px 0; color: #4b5563; font-size: 13px;"><strong>ชื่อ:</strong> ${ext.name}</p>
            <p style="margin: 4px 0; color: #4b5563; font-size: 13px;"><strong>หมู่:</strong> ${ext.village || ext.group}</p>
            <p style="margin: 4px 0; color: #4b5563; font-size: 13px;">
              <strong>สถานะ:</strong> 
              <span style="color: ${getStatusColor(ext.status)}; font-weight: bold;">${getStatusText(ext.status)}</span>
            </p>
          </div>
        `
      });

      marker.addListener('click', () => {
        if (window.currentInfoWindow) {
          window.currentInfoWindow.close();
        }
        infoWindow.open(mapInstance, marker);
        window.currentInfoWindow = infoWindow;
      });
    });

  }, [mapLoaded, filteredExtinguishers]);

  // ฟังก์ชันหาตำแหน่งปัจจุบัน
  const getCurrentLocation = () => {
    if (!navigator.geolocation) {
      alert('เบราว์เซอร์ของคุณไม่รองรับการหาตำแหน่ง');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const userLat = position.coords.latitude;
        const userLng = position.coords.longitude;
        const userPos = { lat: userLat, lng: userLng };
        
        setUserLocation(userPos);
        
        if (map) {
          map.setCenter(userPos);
          map.setZoom(16);
          
          if (window.userLocationMarker) {
            window.userLocationMarker.setMap(null);
          }
          
          window.userLocationMarker = new window.google.maps.Marker({
            position: userPos,
            map: map,
            title: 'ตำแหน่งของคุณ',
            icon: {
              path: window.google.maps.SymbolPath.CIRCLE,
              scale: 12,
              fillColor: '#4285f4',
              fillOpacity: 1,
              strokeColor: '#ffffff',
              strokeWeight: 3
            }
          });
        }
      },
      (error) => {
        alert('ไม่สามารถหาตำแหน่งได้');
      }
    );
  };

  if (!mapLoaded) {
    return (
      <div className="bg-gradient-to-br from-blue-50 to-green-50 rounded-lg p-8 text-center min-h-[400px] flex flex-col justify-center">
        <div className="animate-spin w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full mx-auto mb-4"></div>
        <p className="text-gray-600">กำลังโหลดแผนที่...</p>
      </div>
    );
  }

  const validExtinguishers = filteredExtinguishers.filter(ext => ext.lat && ext.lng);
  
  if (validExtinguishers.length === 0) {
    return (
      <div className="bg-gradient-to-br from-blue-50 to-green-50 rounded-lg p-8 text-center min-h-[400px] flex flex-col justify-center">
        <div className="w-16 h-16 bg-gray-400 rounded-full flex items-center justify-center mx-auto mb-4">
          <i className="fas fa-map-marker-alt text-2xl text-white"></i>
        </div>
        <h4 className="text-lg font-semibold text-gray-700 mb-2">ไม่มีข้อมูลพิกัด</h4>
        <p className="text-gray-600">ไม่พบข้อมูลพิกัดสำหรับหมู่ที่เลือก</p>
      </div>
    );
  }

  return (
    <div className="relative">
      <div 
        id="google-map" 
        className="w-full h-[400px] rounded-lg shadow-lg"
        style={{ minHeight: '400px' }}
      ></div>
      
      {/* ปุ่มตำแหน่งปัจจุบัน */}
      <div className="absolute top-4 left-4">
        <button
          onClick={getCurrentLocation}
          className="bg-white hover:bg-gray-50 rounded-lg p-3 shadow-lg transition-colors"
          title="หาตำแหน่งปัจจุบัน"
        >
          <i className="fas fa-location-arrow text-blue-500 text-lg"></i>
        </button>
      </div>
      
      {/* คำอธิบายสี */}
      <div className="absolute bottom-4 left-4 bg-white bg-opacity-95 rounded-lg p-3 shadow-lg">
        <div className="text-sm font-semibold text-gray-700 mb-2">สถานะถังดับเพลิง:</div>
        <div className="space-y-1 text-xs">
          <div className="flex items-center">
            <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: '#10b981' }}></div>
            <span>พร้อมใช้</span>
          </div>
          <div className="flex items-center">
            <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: '#ef4444' }}></div>
            <span>ผิดปกติ</span>
          </div>
          <div className="flex items-center">
            <div className="w-3 h-3 rounded-full mr-2" style={{ backgroundColor: '#f59e0b' }}></div>
            <span>หมดอายุ</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GoogleMapView;
