import React, { useState } from 'react';
import gasService from '../services/gasServiceSimple';

const TestConnection = () => {
  const [testResult, setTestResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const runTest = async () => {
    setLoading(true);
    setTestResult(null);

    try {
      console.log('Testing GAS connection...');
      console.log('GAS URL:', gasService?.GAS_WEB_APP_URL);
      console.log('Is Development:', gasService?.isDevelopment);

      const result = await gasService.testConnection();
      console.log('Test result:', result);
      setTestResult(result);
    } catch (error) {
      console.error('Test failed:', error);
      setTestResult({
        success: false,
        message: 'Connection failed: ' + error.message,
        error: error.toString()
      });
    } finally {
      setLoading(false);
    }
  };

  const testGetAllData = async () => {
    setLoading(true);
    try {
      const result = await gasService.getAllExtinguishers();
      console.log('Get all data result:', result);
      setTestResult(result);
    } catch (error) {
      console.error('Get all data failed:', error);
      setTestResult({
        success: false,
        message: 'Get all data failed: ' + error.message
      });
    } finally {
      setLoading(false);
    }
  };

  const testSearchById = async () => {
    setLoading(true);
    try {
      const result = await gasService.getExtinguisherById('1/FE68');
      console.log('Search by ID result:', result);
      setTestResult(result);
    } catch (error) {
      console.error('Search by ID failed:', error);
      setTestResult({
        success: false,
        message: 'Search by ID failed: ' + error.message
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-lg shadow-lg p-6">
          <h1 className="text-2xl font-bold text-gray-800 mb-6">
            <i className="fas fa-flask mr-2 text-blue-600"></i>
            ทดสอบการเชื่อมต่อ Google Apps Script
          </h1>

          {/* Configuration Info */}
          <div className="bg-blue-50 rounded-lg p-4 mb-6">
            <h3 className="text-lg font-semibold text-blue-800 mb-2">ข้อมูลการตั้งค่า</h3>
            <div className="space-y-2 text-sm">
              <div><strong>GAS URL:</strong> {gasService?.GAS_WEB_APP_URL || 'Loading...'}</div>
              <div><strong>Development Mode:</strong> {gasService?.isDevelopment ? 'Yes' : 'No'}</div>
              <div><strong>Environment:</strong> {process.env.NODE_ENV}</div>
            </div>
          </div>

          {/* Test Buttons */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <button
              onClick={runTest}
              disabled={loading}
              className="bg-blue-600 text-white px-4 py-3 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition"
            >
              <i className="fas fa-plug mr-2"></i>
              ทดสอบการเชื่อมต่อ
            </button>

            <button
              onClick={testGetAllData}
              disabled={loading}
              className="bg-green-600 text-white px-4 py-3 rounded-lg hover:bg-green-700 disabled:opacity-50 transition"
            >
              <i className="fas fa-database mr-2"></i>
              ดึงข้อมูลทั้งหมด
            </button>

            <button
              onClick={testSearchById}
              disabled={loading}
              className="bg-purple-600 text-white px-4 py-3 rounded-lg hover:bg-purple-700 disabled:opacity-50 transition"
            >
              <i className="fas fa-search mr-2"></i>
              ค้นหา 1/FE68
            </button>
          </div>

          {/* Loading */}
          {loading && (
            <div className="text-center py-8">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
              <p className="mt-2 text-gray-600">กำลังทดสอบ...</p>
            </div>
          )}

          {/* Test Results */}
          {testResult && !loading && (
            <div className="mt-6">
              <h3 className="text-lg font-semibold text-gray-800 mb-3">ผลการทดสอบ</h3>
              <div className={`rounded-lg p-4 ${testResult.success ? 'bg-green-50 border border-green-200' : 'bg-red-50 border border-red-200'}`}>
                <div className="flex items-center mb-2">
                  <i className={`fas ${testResult.success ? 'fa-check-circle text-green-600' : 'fa-times-circle text-red-600'} mr-2`}></i>
                  <span className={`font-semibold ${testResult.success ? 'text-green-800' : 'text-red-800'}`}>
                    {testResult.success ? 'สำเร็จ' : 'ล้มเหลว'}
                  </span>
                </div>
                
                {testResult.message && (
                  <p className={`text-sm mb-3 ${testResult.success ? 'text-green-700' : 'text-red-700'}`}>
                    {testResult.message}
                  </p>
                )}

                {/* Detailed Results */}
                <div className="bg-white rounded border p-3">
                  <h4 className="font-semibold text-gray-700 mb-2">รายละเอียด:</h4>
                  <pre className="text-xs text-gray-600 overflow-auto max-h-96">
                    {JSON.stringify(testResult, null, 2)}
                  </pre>
                </div>
              </div>
            </div>
          )}

          {/* Instructions */}
          <div className="mt-8 bg-yellow-50 rounded-lg p-4">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">
              <i className="fas fa-info-circle mr-2"></i>
              คำแนะนำ
            </h3>
            <div className="text-sm text-yellow-700 space-y-2">
              <p><strong>หากทดสอบล้มเหลว:</strong></p>
              <ul className="list-disc list-inside ml-4 space-y-1">
                <li>ตรวจสอบ GAS URL ใน .env file</li>
                <li>ตรวจสอบ GAS deployment permissions</li>
                <li>ตรวจสอบ Google Sheets ID ใน GAS code</li>
                <li>ตรวจสอบ CORS headers ใน GAS doGet() function</li>
              </ul>
              <p><strong>หาก Development Mode:</strong> จะใช้ mock data แทน</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TestConnection;