import React, { useState } from 'react';

const CheckStatusView = ({ extinguisher, user, onBack, onSave }) => {
  const [checkItems, setCheckItems] = useState({
    pressure: { status: '', comment: '' },
    safetyPin: { status: '', comment: '' },
    hoseAndNozzle: { status: '', comment: '' },
    bodyAndLabel: { status: '', comment: '' },
    accessibility: { status: '', comment: '' },
    standAndMount: { status: '', comment: '' }
  });

  const [isSaving, setIsSaving] = useState(false);

  const checkItemLabels = {
    pressure: 'ความดันในถัง',
    safetyPin: 'สลักนิรภัย',
    hoseAndNozzle: 'สายและหัวฉีด',
    bodyAndLabel: 'ตัวถังและฉลาก',
    accessibility: 'ตำแหน่งการเข้าถึง',
    standAndMount: 'ขาตั้งการยึด'
  };

  // Calculate checked items count
  const totalItems = Object.keys(checkItems).length;
  const checkedItems = Object.values(checkItems).filter(
    item => item.status !== '' // นับเฉพาะรายการที่เลือกสถานะแล้ว
  ).length;

  const handleStatusChange = (itemKey, status) => {
    setCheckItems(prev => ({
      ...prev,
      [itemKey]: {
        ...prev[itemKey],
        status: status,
        // Clear comment if changing to normal
        comment: status === 'ปกติ' ? '' : prev[itemKey].comment
      }
    }));
  };

  const handleCommentChange = (itemKey, comment) => {
    setCheckItems(prev => ({
      ...prev,
      [itemKey]: {
        ...prev[itemKey],
        comment: comment
      }
    }));
  };

  const handleSubmit = async () => {
    // Validate: must check all items
    const uncheckedItems = Object.entries(checkItems).filter(
      ([key, item]) => item.status === ''
    );

    if (uncheckedItems.length > 0) {
      alert('กรุณาตรวจสอบให้ครบทุกรายการ\n\nยังไม่ได้ตรวจสอบ: ' + 
        uncheckedItems.map(([key]) => checkItemLabels[key]).join(', '));
      return;
    }

    // Validate: if any item is abnormal, must have comment
    const hasInvalidItems = Object.entries(checkItems).some(
      ([key, item]) => item.status === 'ผิดปกติ' && !item.comment.trim()
    );

    if (hasInvalidItems) {
      alert('กรุณาใส่หมายเหตุสำหรับรายการที่ผิดปกติ');
      return;
    }

    setIsSaving(true);

    try {
      // Count passed and failed items
      const passedItems = Object.values(checkItems).filter(item => item.status === 'ปกติ').length;
      const failedItems = Object.values(checkItems).filter(item => item.status === 'ผิดปกติ').length;
      
      // Prepare data for saving
      const checkData = {
        extinguisherId: extinguisher.id,
        qrCodeId: extinguisher.qrCode || extinguisher.id,
        fullName: extinguisher.name,
        village: extinguisher.village,
        houseNo: extinguisher.houseNo,
        checkerName: user?.name || 'Admin',
        checkerId: user?.id || '',
        checkDate: new Date().toISOString(),
        checkItems: checkItems,
        overallStatus: failedItems > 0 ? 'ผิดปกติ' : 'ปกติ',
        totalItems: totalItems,
        passedItems: passedItems,
        failedItems: failedItems
      };

      // Call save function
      if (onSave) {
        await onSave(checkData);
      }

      alert('✅ บันทึกการตรวจสอบสำเร็จ!');
      onBack();
    } catch (error) {
      console.error('Error saving check status:', error);
      alert('❌ เกิดข้อผิดพลาด: ' + error.message);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-blue-50">
      {/* Header */}
      <div className="bg-white shadow-sm border-b sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center">
            <button
              onClick={onBack}
              className="mr-4 p-2 hover:bg-gray-100 rounded-lg transition-colors"
            >
              <i className="fas fa-arrow-left text-gray-600"></i>
            </button>
            <div className="flex-1">
              <h1 className="text-xl font-bold text-gray-800">เช็คสถานะถังดับเพลิง</h1>
              <p className="text-sm text-gray-600">รหัส: {extinguisher.id}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto px-4 py-6">
        {/* Extinguisher Info Card - Sticky */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-4 sticky top-16 z-10">
          <div className="flex items-center justify-between">
            <div className="flex items-center flex-1">
              <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center mr-4">
                <i className="fas fa-fire-extinguisher text-red-600 text-xl"></i>
              </div>
              <div className="flex-1">
                <h3 className="font-semibold text-gray-800">{extinguisher.name}</h3>
                <p className="text-sm text-gray-600">
                  {extinguisher.group} • {extinguisher.size}
                </p>
              </div>
            </div>
            {/* Check Progress */}
            <div className="ml-4 text-right">
              <div className={`text-2xl font-bold ${
                checkedItems === totalItems ? 'text-green-600' : 'text-blue-600'
              }`}>
                {checkedItems}/{totalItems}
              </div>
              <p className="text-xs text-gray-500">รายการ</p>
            </div>
          </div>
        </div>

        {/* Check Items */}
        <div className="space-y-4">
          {Object.entries(checkItemLabels).map(([key, label]) => (
            <div key={key} className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
              <h4 className="font-semibold text-gray-800 mb-3">{label}</h4>
              
              {/* Status Selection */}
              <div className="flex gap-3 mb-3">
                <button
                  onClick={() => handleStatusChange(key, 'ปกติ')}
                  className={`flex-1 py-3 px-4 rounded-lg border-2 transition-all ${
                    checkItems[key].status === 'ปกติ'
                      ? 'border-green-500 bg-green-50 text-green-700'
                      : 'border-gray-200 bg-white text-gray-600 hover:border-green-300'
                  }`}
                >
                  <i className="fas fa-check-circle mr-2"></i>
                  ปกติ
                </button>
                <button
                  onClick={() => handleStatusChange(key, 'ผิดปกติ')}
                  className={`flex-1 py-3 px-4 rounded-lg border-2 transition-all ${
                    checkItems[key].status === 'ผิดปกติ'
                      ? 'border-red-500 bg-red-50 text-red-700'
                      : 'border-gray-200 bg-white text-gray-600 hover:border-red-300'
                  }`}
                >
                  <i className="fas fa-times-circle mr-2"></i>
                  ผิดปกติ
                </button>
              </div>

              {/* Comment Field (shown only when abnormal) */}
              {checkItems[key].status === 'ผิดปกติ' && (
                <div className="mt-3">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    หมายเหตุ <span className="text-red-500">*</span>
                  </label>
                  <textarea
                    value={checkItems[key].comment}
                    onChange={(e) => handleCommentChange(key, e.target.value)}
                    placeholder="ระบุรายละเอียดปัญหา..."
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 resize-none"
                    rows="3"
                  />
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Summary */}
        <div className="mt-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
          <div className="flex items-center justify-between">
            <div className="flex-1">
              <p className="text-sm text-gray-600">สรุปผลการตรวจสอบ</p>
              <p className="text-lg font-semibold text-gray-800">
                {checkedItems < totalItems ? (
                  <span className="text-orange-600">
                    <i className="fas fa-clock mr-2"></i>
                    ตรวจสอบแล้ว {checkedItems}/{totalItems} รายการ
                  </span>
                ) : Object.values(checkItems).every(item => item.status === 'ปกติ') ? (
                  <span className="text-green-600">
                    <i className="fas fa-check-circle mr-2"></i>
                    ปกติทุกรายการ
                  </span>
                ) : (
                  <span className="text-red-600">
                    <i className="fas fa-exclamation-triangle mr-2"></i>
                    พบรายการผิดปกติ {Object.values(checkItems).filter(item => item.status === 'ผิดปกติ').length} รายการ
                  </span>
                )}
              </p>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="mt-6 flex gap-3">
          <button
            onClick={onBack}
            className="flex-1 py-3 px-4 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors font-medium"
            disabled={isSaving}
          >
            <i className="fas fa-times mr-2"></i>
            ยกเลิก
          </button>
          <button
            onClick={handleSubmit}
            className="flex-1 py-3 px-4 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium disabled:bg-gray-400"
            disabled={isSaving}
          >
            {isSaving ? (
              <>
                <i className="fas fa-spinner fa-spin mr-2"></i>
                กำลังบันทึก...
              </>
            ) : (
              <>
                <i className="fas fa-save mr-2"></i>
                บันทึกผลการตรวจสอบ
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default CheckStatusView;
