import React, { useState, useRef, useEffect } from 'react';

const GeneralRequestView = ({ onBack }) => {
  const today = new Date().toLocaleDateString('th-TH');

  const [writtenAt, setWrittenAt] = useState('');
  const [subject, setSubject] = useState('');
  const [prefix, setPrefix] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [age, setAge] = useState('');
  const [houseNo, setHouseNo] = useState('');
  const [village, setVillage] = useState('');
  const [community, setCommunity] = useState('');
  const [phone, setPhone] = useState('');
  const [problem, setProblem] = useState('');
  const [solution, setSolution] = useState('');
  const [idCardPhoto, setIdCardPhoto] = useState(null);
  const [photos, setPhotos] = useState([]);
  const [sending, setSending] = useState(false);

  // Signature canvas
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const initCanvas = () => {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = 160;
    };
    initCanvas();

    const getPos = (e) => {
      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width;
      const scaleY = canvas.height / rect.height;
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      const clientY = e.touches ? e.touches[0].clientY : e.clientY;
      return {
        x: (clientX - rect.left) * scaleX,
        y: (clientY - rect.top) * scaleY,
      };
    };

    let drawing = false;
    const onStart = (e) => {
      e.preventDefault();
      drawing = true;
      const p = getPos(e);
      const ctx = canvas.getContext('2d');
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
    };
    const onMove = (e) => {
      e.preventDefault();
      if (!drawing) return;
      const p = getPos(e);
      const ctx = canvas.getContext('2d');
      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeStyle = '#000';
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
    };
    const onEnd = () => { drawing = false; };

    canvas.addEventListener('mousedown', onStart);
    canvas.addEventListener('mousemove', onMove);
    canvas.addEventListener('mouseup', onEnd);
    canvas.addEventListener('mouseleave', onEnd);
    canvas.addEventListener('touchstart', onStart, { passive: false });
    canvas.addEventListener('touchmove', onMove, { passive: false });
    canvas.addEventListener('touchend', onEnd);
    return () => {
      canvas.removeEventListener('mousedown', onStart);
      canvas.removeEventListener('mousemove', onMove);
      canvas.removeEventListener('mouseup', onEnd);
      canvas.removeEventListener('mouseleave', onEnd);
      canvas.removeEventListener('touchstart', onStart);
      canvas.removeEventListener('touchmove', onMove);
      canvas.removeEventListener('touchend', onEnd);
    };
  }, []);
  const idCardRef = useRef(null);
  const idCardCameraRef = useRef(null);
  const photoRef = useRef(null);
  const cameraRef = useRef(null);
  const [photoPickerTarget, setPhotoPickerTarget] = useState(null); // 'idcard' | 'photo'

  // Load from localStorage
  useEffect(() => {
    const n = localStorage.getItem('userName') || '';
    const p = localStorage.getItem('userPhone') || '';
    const v = localStorage.getItem('userVillage') || '';
    const a = localStorage.getItem('userAddress') || '';
    const parts = n.split(' ');
    setFirstName(parts[0] || '');
    setLastName(parts[1] || '');
    setPhone(p);
    setVillage(v);
    setHouseNo(a);
  }, []);

  const clearSignature = () => {
    const canvas = canvasRef.current;
    canvas.getContext('2d').clearRect(0, 0, canvas.width, canvas.height);
  };

  const handleIdCard = (e) => {
    const file = e.target.files[0];
    if (file) setIdCardPhoto(file);
  };

  const handlePhotos = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (photos.length >= 4) { alert('แนบรูปได้สูงสุด 4 รูป'); return; }
    setPhotos(prev => [...prev, file]);
    e.target.value = '';
  };

  const handleSubmit = async () => {
    if (!subject.trim()) { alert('กรุณากรอกหัวข้อเรื่อง'); return; }
    if (!prefix) { alert('กรุณาเลือกคำนำหน้า'); return; }
    if (!firstName.trim()) { alert('กรุณากรอกชื่อ'); return; }
    if (!phone.trim()) { alert('กรุณากรอกเบอร์โทรศัพท์'); return; }

    setSending(true);
    try {
      // แปลง signature เป็น base64
      const signatureData = canvasRef.current.toDataURL('image/png');

      // บีบอัดรูปก่อนแปลง base64
      const toBase64Compressed = (file, maxSize = 800, quality = 0.6) => new Promise((res, rej) => {
        const img = new Image();
        const url = URL.createObjectURL(file);
        img.onload = () => {
          let w = img.width, h = img.height;
          if (w > maxSize || h > maxSize) {
            if (w > h) { h = Math.round(h * maxSize / w); w = maxSize; }
            else { w = Math.round(w * maxSize / h); h = maxSize; }
          }
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          URL.revokeObjectURL(url);
          // ส่ง full data URL (data:image/jpeg;base64,xxx) เพื่อให้ GAS แปลงได้
          res(canvas.toDataURL('image/jpeg', quality));
        };
        img.onerror = rej;
        img.src = url;
      });

      const idCardBase64 = idCardPhoto ? await toBase64Compressed(idCardPhoto, 1000, 0.7) : '';
      const photosBase64 = photos.length > 0
        ? await Promise.all(photos.map(f => toBase64Compressed(f, 800, 0.6)))
        : [];

      const today = new Date().toISOString();

      const payload = {
        "เขียนที่": writtenAt || 'องค์การบริหารส่วนตำบลสระกระโจม',
        "วันที่เขียนคำร้อง": today,
        "หัวข้อเรื่อง": subject,
        "คำนำหน้า": prefix,
        "ชื่อ": firstName,
        "นามสกุล": lastName,
        "อายุ": age,
        "บ้านเลขที่": houseNo,
        "หมู่ที่": village,
        "ชื่อชุมชน": community,
        "เบอร์โทรศัพท์": phone,
        "ปัญหาที่ต้องการแจ้ง": problem,
        "แนวทางที่ขอรับการแก้ไข": solution,
        "ลายเซ็น": signatureData,
        "ภาพบัตรประชาชน": idCardBase64,
        "ภาพแนบคำร้อง": photosBase64,
      };

      const GAS_URL = process.env.REACT_APP_GAS_PETITION_URL;
      console.log('GAS URL:', GAS_URL);
      if (!GAS_URL) {
        alert('ไม่พบ URL ของ GAS กรุณา restart npm start');
        setSending(false);
        return;
      }
      const res = await fetch(GAS_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload),
      });

      // no-cors จะไม่ได้ response กลับมา ถือว่าส่งสำเร็จ
      const tgChatId = process.env.REACT_APP_TELEGRAM_PETITION_CHAT_ID;
      const tgToken = process.env.REACT_APP_TELEGRAM_BOT_TOKEN;
      if (tgToken && tgChatId) {
        const msg = `📋 คำร้องทั่วไปใหม่\n\n` +
          `📌 เรื่อง: ${subject}\n` +
          `👤 ผู้ยื่น: ${prefix}${firstName} ${lastName}\n` +
          `🏠 บ้านเลขที่ ${houseNo} หมู่ ${village}\n` +
          `📞 โทร: ${phone}\n` +
          `📝 ปัญหา: ${problem}\n` +
          `⏰ เวลา: ${new Date().toLocaleString('th-TH')}`;
        fetch(`https://api.telegram.org/bot${tgToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: tgChatId, text: msg }),
        }).catch(() => {});
      }
      alert('✅ ส่งคำร้องเรียบร้อยแล้ว');
      onBack();
    } catch (e) {
      console.error(e);
      alert('เกิดข้อผิดพลาดในการส่งข้อมูล กรุณาลองใหม่');
    } finally {
      setSending(false);
    }
  };

  const inputClass = "w-full px-4 py-3 border border-gray-300 rounded-lg focus:border-purple-500 focus:outline-none text-gray-700";
  const sectionIcon = (icon) => (
    <div className="w-9 h-9 bg-gray-200 rounded-full flex items-center justify-center flex-shrink-0">
      <i className={`fas ${icon} text-gray-500`}></i>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-50 pb-24">

      {/* Hidden inputs - ต้องอยู่ก่อน modal */}
      <input ref={idCardRef} type="file" accept="image/*" onChange={e => { if(e.target.files[0]) setIdCardPhoto(e.target.files[0]); }} className="hidden" />
      <input ref={idCardCameraRef} type="file" accept="image/*" capture="environment" onChange={e => { if(e.target.files[0]) setIdCardPhoto(e.target.files[0]); }} className="hidden" />
      <input ref={photoRef} type="file" accept="image/*" onChange={handlePhotos} className="hidden" />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" onChange={handlePhotos} className="hidden" />

      {/* Photo Picker Modal */}
      {photoPickerTarget && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-sm p-4">
            <p className="text-center font-bold text-gray-800 mb-4">เลือกรูปภาพ</p>
            <div className="space-y-3">
              <button onClick={() => {
                if (photoPickerTarget === 'idcard') idCardCameraRef.current.click();
                else cameraRef.current.click();
                setPhotoPickerTarget(null);
              }} className="w-full py-3 bg-purple-600 text-white rounded-xl font-medium flex items-center justify-center gap-2">
                <i className="fas fa-camera"></i> ถ่ายรูป
              </button>
              <button onClick={() => {
                if (photoPickerTarget === 'idcard') idCardRef.current.click();
                else photoRef.current.click();
                setPhotoPickerTarget(null);
              }} className="w-full py-3 bg-gray-100 text-gray-700 rounded-xl font-medium flex items-center justify-center gap-2">
                <i className="fas fa-images"></i> เลือกรูปจากเครื่อง
              </button>
              <button onClick={() => setPhotoPickerTarget(null)}
                className="w-full py-2 text-gray-400 text-sm">ยกเลิก</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div style={{ background: 'linear-gradient(135deg, #9333ea 0%, #7c3aed 100%)' }} className="p-5 text-white">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 bg-white bg-opacity-20 rounded-full flex items-center justify-center flex-shrink-0 mt-1">
            <i className="fas fa-file-pen text-lg"></i>
          </div>
          <div>
            <h1 className="text-xl font-bold">ฟอร์มคำร้องทั่วไป</h1>
            <p className="text-purple-200 text-sm mt-1">กรุณากรอกข้อมูลให้ครบถ้วน</p>
            <p className="text-purple-200 text-sm">งานป้องกันและบรรเทาสาธารณภัย</p>
            <p className="text-purple-200 text-sm">องค์การบริหารส่วนตำบลสระกระโจม</p>
            <p className="text-purple-200 text-sm">โทร.0-3544-0568</p>
          </div>
        </div>
      </div>

      <div className="p-4 space-y-4">

        {/* ข้อมูลทั่วไป */}
        <div className="bg-white rounded-2xl p-4 shadow-sm">
          <div className="flex items-center gap-3 mb-4">
            {sectionIcon('fa-file-alt')}
            <h2 className="font-bold text-gray-800 text-base">ข้อมูลทั่วไป</h2>
          </div>
          <div className="space-y-3">
            <div className="relative">
              <label className="text-xs text-gray-500 mb-1 block">เขียนที่ *</label>
              <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
                <i className="fas fa-map-marker-alt text-gray-400"></i>
                <input type="text" value={writtenAt} onChange={e => setWrittenAt(e.target.value)}
                  placeholder="เช่น องค์การบริหารส่วนตำบลสระกระโจม"
                  className="flex-1 focus:outline-none text-gray-700" />
              </div>
            </div>
            <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
              <i className="fas fa-calendar text-gray-400"></i>
              <div>
                <p className="text-xs text-gray-500">วันที่เขียนคำร้อง</p>
                <p className="text-gray-700">{today}</p>
              </div>
            </div>
            <div className="relative">
              <label className="text-xs text-gray-500 mb-1 block">หัวข้อเรื่อง *</label>
              <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
                <i className="fas fa-align-left text-gray-400"></i>
                <input type="text" value={subject} onChange={e => setSubject(e.target.value)}
                  placeholder="เช่น ขอซ่อมถนนในหมู่บ้าน"
                  className="flex-1 focus:outline-none text-gray-700" />
              </div>
            </div>
          </div>
        </div>

        {/* ข้อมูลผู้ยื่นคำร้อง */}
        <div className="bg-white rounded-2xl p-4 shadow-sm">
          <div className="flex items-center gap-3 mb-4">
            {sectionIcon('fa-user')}
            <h2 className="font-bold text-gray-800 text-base">ข้อมูลผู้ยื่นคำร้อง</h2>
          </div>
          <div className="space-y-3">
            <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
              <i className="fas fa-id-badge text-gray-400"></i>
              <select value={prefix} onChange={e => setPrefix(e.target.value)}
                className="flex-1 focus:outline-none text-gray-700 bg-transparent">
                <option value="">คำนำหน้า *</option>
                <option>นาย</option><option>นาง</option><option>นางสาว</option>
              </select>
              <i className="fas fa-chevron-down text-gray-400 text-xs"></i>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)}
                placeholder="ชื่อ *" className={inputClass} />
              <input type="text" value={lastName} onChange={e => setLastName(e.target.value)}
                placeholder="นามสกุล *" className={inputClass} />
            </div>
            <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
              <i className="fas fa-birthday-cake text-gray-400"></i>
              <input type="number" value={age} onChange={e => setAge(e.target.value)}
                placeholder="อายุ เช่น 35"
                className="flex-1 focus:outline-none text-gray-700" />
            </div>
          </div>
        </div>

        {/* ที่อยู่ */}
        <div className="bg-white rounded-2xl p-4 shadow-sm">
          <div className="flex items-center gap-3 mb-4">
            {sectionIcon('fa-home')}
            <h2 className="font-bold text-gray-800 text-base">ที่อยู่</h2>
          </div>
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <input type="text" value={houseNo} onChange={e => setHouseNo(e.target.value)}
                placeholder="บ้านเลขที่" className={inputClass} />
              <select value={village} onChange={e => setVillage(e.target.value)} className={inputClass}>
                <option value="">หมู่ที่</option>
                {[1,2,3,4,5,6,7,8,9].map(n => <option key={n} value={n}>หมู่ {n}</option>)}
              </select>
            </div>
            <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
              <i className="fas fa-building text-gray-400"></i>
              <select value={community} onChange={e => setCommunity(e.target.value)}
                className="flex-1 focus:outline-none text-gray-700 bg-transparent">
                <option value="">-- เลือกชื่อชุมชน --</option>
                <option>วังยางเจริญ</option>
                <option>สัประเทศ</option>
                <option>ศาลเจ้าพ่อเขาสามยอด</option>
                <option>ทุ่งชนะพัฒนา</option>
                <option>ทุ่งชนะรวมใจ</option>
                <option>ไก่เตี้ยรวมใจพัฒนา</option>
                <option>ดอนโป่ง-ดงนางเจ็กร่วมใจพัฒนา</option>
                <option>ดอนกระเบื้องพัฒนา</option>
                <option>บรรไดทอง-คันคลองพัฒนา</option>
                <option>สามโอ่รวมใจพัฒนา</option>
                <option>ดงตาลร่วมใจพัฒนา</option>
                <option>ดงตาลเจริญร่วมใจ</option>
                <option>ลาดปลาเค้า-ห้วยอำพัวร่วมใจพัฒนา</option>
                <option>ลาดปลาเค้า-ดอนเจริญร่วมใจพัฒนาสามัคคี</option>
                <option>หนองจิกพัฒนา</option>
                <option>สามนาครวมใจพัฒนา</option>
                <option>อยู่เจริญ 1</option>
                <option>อยู่เจริญ 2</option>
                <option>อยู่เจริญ 3</option>
                <option>วังยางรวมใจพัฒนา</option>
              </select>
            </div>
            <div className="flex items-center border border-gray-300 rounded-lg px-3 py-3 gap-2">
              <i className="fas fa-phone text-gray-400"></i>
              <input type="tel" value={phone} onChange={e => setPhone(e.target.value)}
                placeholder="เบอร์โทรศัพท์ เช่น 0812345678"
                className="flex-1 focus:outline-none text-gray-700" />
            </div>
          </div>
        </div>

        {/* รายละเอียดคำร้อง */}
        <div className="bg-white rounded-2xl p-4 shadow-sm">
          <div className="flex items-center gap-3 mb-4">
            {sectionIcon('fa-list-alt')}
            <h2 className="font-bold text-gray-800 text-base">รายละเอียดคำร้อง</h2>
          </div>
          <div className="space-y-3">
            <textarea value={problem} onChange={e => setProblem(e.target.value)}
              placeholder="ปัญหาที่ต้องการแจ้ง"
              rows={4} className={inputClass + ' resize-none'} />
            <textarea value={solution} onChange={e => setSolution(e.target.value)}
              placeholder="แนวทางที่ขอรับการแก้ไข"
              rows={4} className={inputClass + ' resize-none'} />
          </div>
        </div>

        {/* เอกสารแนบ */}
        <div className="bg-white rounded-2xl p-4 shadow-sm">
          <div className="flex items-center gap-3 mb-4">
            {sectionIcon('fa-paperclip')}
            <h2 className="font-bold text-gray-800 text-base">เอกสารแนบ</h2>
          </div>
          <div className="space-y-3">
            <button onClick={() => setPhotoPickerTarget('idcard')}
              className="w-full py-3 text-white rounded-lg font-medium flex items-center justify-center gap-2"
              style={{ background: 'linear-gradient(135deg, #9333ea 0%, #7c3aed 100%)' }}>
              <i className="fas fa-id-card"></i>
              {idCardPhoto ? '✅ เปลี่ยนบัตรประชาชน' : 'ถ่าย/เลือกบัตรประชาชน'}
            </button>
            {idCardPhoto && (
              <div className="flex items-center gap-2 mt-1">
                <img src={URL.createObjectURL(idCardPhoto)} alt="บัตรประชาชน"
                  className="w-20 h-14 object-cover rounded-lg border border-gray-200" />
                <span className="text-xs text-gray-500 truncate">{idCardPhoto.name}</span>
              </div>
            )}

            {photos.length === 0 ? (
              <button onClick={() => setPhotoPickerTarget('photo')}
                className="w-full py-3 text-white rounded-lg font-medium flex items-center justify-center gap-2"
                style={{ background: 'linear-gradient(135deg, #9333ea 0%, #7c3aed 100%)' }}>
                <i className="fas fa-camera"></i>
                แนบรูปภาพประกอบคำร้อง
              </button>
            ) : (
              <div className="flex flex-wrap gap-2 mt-1">
                {photos.map((p, i) => (
                  <div key={i} className="relative">
                    <img src={URL.createObjectURL(p)} alt={`รูป ${i+1}`}
                      className="w-16 h-16 object-cover rounded-lg border border-gray-200" />
                    <button onClick={() => setPhotos(prev => prev.filter((_, idx) => idx !== i))}
                      className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white rounded-full text-xs flex items-center justify-center">
                      ×
                    </button>
                  </div>
                ))}
                {photos.length < 4 && (
                  <button onClick={() => setPhotoPickerTarget('photo')}
                    className="w-16 h-16 border-2 border-dashed border-purple-400 rounded-lg flex flex-col items-center justify-center text-purple-500 hover:bg-purple-50">
                    <i className="fas fa-plus text-lg"></i>
                    <span className="text-xs mt-1">{photos.length}/4</span>
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        {/* ลายเซ็น */}
        <div className="bg-white rounded-2xl p-4 shadow-sm">
          <div className="flex items-center gap-3 mb-4">
            {sectionIcon('fa-signature')}
            <h2 className="font-bold text-gray-800 text-base">ลายเซ็นผู้ยื่นคำร้อง</h2>
          </div>
          <canvas ref={canvasRef}
            className="w-full border-2 border-gray-300 rounded-lg"
            style={{ cursor: 'crosshair', touchAction: 'none', display: 'block', height: '160px' }}
          />
          <button onClick={clearSignature}
            className="mt-2 px-4 py-2 border border-red-400 text-red-500 rounded-lg text-sm flex items-center gap-2">
            <i className="fas fa-redo"></i> ล้างลายเซ็น
          </button>
        </div>

        {/* ส่งคำร้อง */}
        <button onClick={handleSubmit} disabled={sending}
          className="w-full py-4 text-white rounded-xl font-bold text-lg flex items-center justify-center gap-2"
          style={{ background: sending ? '#9ca3af' : 'linear-gradient(135deg, #9333ea 0%, #7c3aed 100%)' }}>
          {sending ? <><i className="fas fa-spinner fa-spin"></i> กำลังส่ง...</> : <><i className="fas fa-paper-plane"></i> ส่งคำร้อง</>}
        </button>

        <button onClick={onBack} className="w-full py-3 text-gray-500 text-sm">
          ← ย้อนกลับ
        </button>
      </div>
    </div>
  );
};

export default GeneralRequestView;
