import React, { useState, useMemo, useEffect } from 'react';
import GoogleMapView from './GoogleMapView';
import ExtinguisherDetailView from './ExtinguisherDetailView';
import CheckHistoryView from './CheckHistoryView';
import gasService from '../services/gasServiceSimple';

const MapView = ({ extinguishers: propExtinguishers, stats: propStats, onChangeView }) => {
  const [selectedGroup, setSelectedGroup] = useState('ทั้งหมด');
  const [extinguishers, setExtinguishers] = useState(propExtinguishers || []);
  // eslint-disable-next-line no-unused-vars
  const [stats, setStats] = useState(propStats || { total: 0, ready: 0, check: 0, expired: 0 });
  // eslint-disable-next-line no-unused-vars
  const [loading, setLoading] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const [selectedExtinguisher, setSelectedExtinguisher] = useState(null);
  const [focusLocation, setFocusLocation] = useState(null);
  const [historyExtinguisher, setHistoryExtinguisher] = useState(null);
  
  // โหลดข้อมูลใหม่หากไม่มีข้อมูลจาก props
  useEffect(() => {
    if (!propExtinguishers || propExtinguishers.length === 0) {
      loadMapData();
    } else {
      setExtinguishers(propExtinguishers);
      setStats(propStats || { total: 0, ready: 0, check: 0, expired: 0 });
    }
  }, [propExtinguishers, propStats]);

  // ปิด dropdown เมื่อคลิกข้างนอก
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownOpen && !event.target.closest('.custom-dropdown')) {
        setDropdownOpen(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [dropdownOpen]);

  // บังคับ refresh component เมื่อ mount
  useEffect(() => {
    console.log('🔄 MapView mounted, forcing refresh...');
    // บังคับให้ component re-render
    const timer = setTimeout(() => {
      setSelectedGroup(prev => prev);
    }, 100);
    return () => clearTimeout(timer);
  }, []);

  // ตรวจสอบ Service Worker Update
  useEffect(() => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.addEventListener('message', (event) => {
        if (event.data && event.data.type === 'UPDATE_AVAILABLE') {
          setUpdateAvailable(true);
        }
      });
    }
  }, []);

  const loadMapData = async () => {
    setLoading(true);
    try {
      console.log('🗺️ Loading map data...');
      const result = await gasService.getAllExtinguishers();
      if (result && result.success) {
        console.log('🗺️ Map data loaded:', result.extinguishers?.length, 'items');
        setExtinguishers(result.extinguishers || []);
        setStats(result.stats || { total: 0, ready: 0, check: 0, expired: 0 });
      } else {
        console.error('🗺️ Failed to load map data:', result?.message);
      }
    } catch (error) {
      console.error('🗺️ Error loading map data:', error);
    } finally {
      setLoading(false);
    }
  };
  const getTypeText = (type) => {
    const types = {
      'water': 'น้ำ',
      'foam': 'โฟม',
      'powder': 'ผงเคมีแห้ง',
      'co2': 'คาร์บอนไดออกไซด์'
    };
    return types[type] || 'ผงเคมีแห้ง';
  };

  const getStatusText = (status) => {
    const statuses = {
      'ready': 'พร้อมใช้',
      'check': 'ต้องตรวจสอบ',
      'expired': 'หมดอายุ',
      'maintenance': 'ซ่อมบำรุง'
    };
    return statuses[status] || 'พร้อมใช้';
  };

  const getStatusColor = (status) => {
    const colors = {
      'ready': 'bg-green-100 text-green-800',
      'check': 'bg-yellow-100 text-yellow-800',
      'expired': 'bg-red-100 text-red-800',
      'maintenance': 'bg-blue-100 text-blue-800'
    };
    return colors[status] || 'bg-green-100 text-green-800';
  };

  // สร้างรายการหมู่จากข้อมูลจริงใน Google Sheets
  const groups = useMemo(() => {
    console.log('🏘️ Creating groups from extinguishers:', extinguishers?.length);
    
    if (!extinguishers || extinguishers.length === 0) {
      console.log('🏘️ No extinguishers, using default groups');
      return ['ทั้งหมด', 'หมู่ 1', 'หมู่ 2', 'หมู่ 3']; // fallback groups
    }
    
    // ดึงรายการหมู่ที่ไม่ซ้ำจากข้อมูลจริง
    const uniqueGroups = [...new Set(extinguishers.map(ext => {
      const group = ext.group || ('หมู่ ' + ext.village) || ext.location;
      console.log('🏘️ Found group:', group, 'from ext:', ext.id);
      return group;
    }))].filter(Boolean).sort((a, b) => {
      const na = parseInt(a.replace('หมู่ ', '')) || 0;
      const nb = parseInt(b.replace('หมู่ ', '')) || 0;
      return na - nb;
    });
    
    console.log('🏘️ Unique groups found:', uniqueGroups);
    
    const result = ['ทั้งหมด', ...uniqueGroups];
    console.log('🏘️ Final groups:', result);
    return result;
  }, [extinguishers]);

  // กรองถังดับเพลิงตามหมู่ที่เลือก (ใช้ village หรือ group)
  const filteredExtinguishers = useMemo(() => {
    if (!extinguishers) return [];
    if (selectedGroup === 'ทั้งหมด') return extinguishers;
    return extinguishers.filter(ext => (ext.group || ('หมู่ ' + ext.village)) === selectedGroup);
  }, [extinguishers, selectedGroup]);

  if (historyExtinguisher) {
    return (
      <CheckHistoryView
        extinguisher={historyExtinguisher}
        onBack={() => setHistoryExtinguisher(null)}
      />
    );
  }

  if (selectedExtinguisher) {
    return (
      <ExtinguisherDetailView
        extinguisher={selectedExtinguisher}
        onBack={() => setSelectedExtinguisher(null)}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-green-50 to-emerald-50">

      <div className="mobile-card card-modern fade-in-up" style={{ marginTop: 0, borderRadius: '0 0 1rem 1rem' }}>
        <div className="text-center mb-6 pt-8 pb-4">
          <div className="w-16 h-16 bg-gradient-to-br from-green-500 to-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4 shadow-lg">
            <i className="fas fa-map-marked-alt text-2xl text-white"></i>
          </div>
          <h1 className="text-2xl md:text-3xl font-bold text-gray-800 mb-2">ตำแหน่งถังดับเพลิงทั้งหมด</h1>
          <p className="text-gray-600 text-sm md:text-base">แผนที่แสดงตำแหน่งติดตั้งถังดับเพลิงในชุมชน</p>
        </div>
      </div>
      <div className="mobile-card card-modern mb-6">
        <div className="p-4">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-gray-800">แผนที่ตำแหน่งถังดับเพลิง</h3>
            <div className="flex items-center text-sm text-gray-600">
              <i className="fas fa-map mr-2 text-green-500"></i>
              Google Maps
            </div>
          </div>
          
          <GoogleMapView 
            extinguishers={extinguishers || []} 
            selectedGroup={selectedGroup}
            focusLocation={focusLocation}
          />
        </div>
      </div>

      {/* Update Available Notification */}
      {updateAvailable && (
        <div style={{
          background: '#fef3c7',
          margin: '0 1rem 1rem 1rem',
          borderRadius: '1rem',
          border: '1px solid #f59e0b',
          padding: '1rem'
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div>
              <h4 style={{ fontSize: '0.875rem', fontWeight: 'bold', color: '#92400e', marginBottom: '0.25rem' }}>
                🔄 มีการอัพเดทใหม่
              </h4>
              <p style={{ fontSize: '0.75rem', color: '#92400e', margin: 0 }}>
                กดปุ่มด้านล่างเพื่อรีเฟรชและใช้งานเวอร์ชันล่าสุด
              </p>
            </div>
            <button
              onClick={() => window.location.reload(true)}
              style={{
                background: '#f59e0b',
                color: 'white',
                border: 'none',
                padding: '8px 12px',
                borderRadius: '6px',
                fontSize: '0.75rem',
                cursor: 'pointer'
              }}
            >
              รีเฟรช
            </button>
          </div>
        </div>
      )}



      {/* Group Filter Dropdown - Custom Implementation */}
      <div style={{
        background: 'white',
        margin: '0 1rem 1rem 1rem',
        borderRadius: '1rem',
        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.08)',
        border: '1px solid rgba(0, 0, 0, 0.05)'
      }}>
        <div style={{ padding: '1rem' }}>
          <h3 style={{
            fontSize: '1.125rem',
            fontWeight: 'bold',
            color: '#1f2937',
            marginBottom: '1rem',
            display: 'flex',
            alignItems: 'center'
          }}>
            <i className="fas fa-filter" style={{ marginRight: '0.5rem', color: '#10b981' }}></i>
            กรองตามหมู่บ้าน
          </h3>
          
          {/* Custom Dropdown */}
          <div className="custom-dropdown" style={{ position: 'relative', width: '100%' }}>
            {/* Dropdown Button */}
            <div
              onClick={() => setDropdownOpen(!dropdownOpen)}
              style={{
                width: '100%',
                padding: '16px',
                background: 'white',
                border: '2px solid #d1d5db',
                borderRadius: '8px',
                fontSize: '16px',
                color: '#374151',
                cursor: 'pointer',
                minHeight: '56px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                userSelect: 'none'
              }}
            >
              <span>
                {selectedGroup} ({
                  selectedGroup === 'ทั้งหมด' 
                    ? extinguishers?.length || 0
                    : extinguishers?.filter(ext => (ext.group || ('หมู่ ' + ext.village)) === selectedGroup).length || 0
                } รายการ)
              </span>
              <i className={`fas fa-chevron-${dropdownOpen ? 'up' : 'down'}`} style={{ color: '#6b7280' }}></i>
            </div>
            
            {/* Dropdown Menu */}
            {dropdownOpen && (
              <div style={{
                position: 'absolute',
                top: '100%',
                left: '0',
                right: '0',
                background: 'white',
                border: '2px solid #d1d5db',
                borderTop: 'none',
                borderRadius: '0 0 8px 8px',
                maxHeight: '200px',
                overflowY: 'auto',
                zIndex: '1000',
                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)'
              }}>
                {groups.map((group) => {
                  const count = group === 'ทั้งหมด' 
                    ? extinguishers?.length || 0
                    : extinguishers?.filter(ext => (ext.group || ('หมู่ ' + ext.village)) === group).length || 0;
                  
                  return (
                    <div
                      key={group}
                      onClick={() => {
                        console.log('🔄 Group selected:', group);
                        setSelectedGroup(group);
                        setDropdownOpen(false);
                      }}
                      style={{
                        padding: '12px 16px',
                        cursor: 'pointer',
                        borderBottom: '1px solid #f3f4f6',
                        backgroundColor: selectedGroup === group ? '#f0fdf4' : 'white',
                        color: selectedGroup === group ? '#166534' : '#374151',
                        fontSize: '16px'
                      }}
                      onMouseEnter={(e) => {
                        if (selectedGroup !== group) {
                          e.target.style.backgroundColor = '#f9fafb';
                        }
                      }}
                      onMouseLeave={(e) => {
                        if (selectedGroup !== group) {
                          e.target.style.backgroundColor = 'white';
                        }
                      }}
                    >
                      {group} ({count} รายการ)
                    </div>
                  );
                })}
              </div>
            )}
          </div>
          <div className="mt-3 text-sm text-gray-600 flex items-center justify-between">
            <div className="flex items-center">
              <i className="fas fa-filter mr-2 text-green-500"></i>
              แสดง {filteredExtinguishers.length} จาก {extinguishers?.length || 0} รายการ
            </div>
            {selectedGroup !== 'ทั้งหมด' && (
              <div className="text-xs text-blue-600 font-medium">
                {selectedGroup}
              </div>
            )}
          </div>
          
          {/* สถิติแยกตามหมู่ที่เลือก */}
          {filteredExtinguishers.length > 0 && (
            <div className="mt-4 grid grid-cols-4 gap-2">
              <div className="bg-green-50 rounded-lg p-2 text-center">
                <div className="text-lg font-bold text-green-600">
                  {filteredExtinguishers.filter(ext => ext.status === 'ready').length}
                </div>
                <div className="text-xs text-green-700">พร้อมใช้</div>
              </div>
              <div className="bg-yellow-50 rounded-lg p-2 text-center">
                <div className="text-lg font-bold text-yellow-600">
                  {filteredExtinguishers.filter(ext => ext.status === 'check').length}
                </div>
                <div className="text-xs text-yellow-700">ตรวจสอบ</div>
              </div>
              <div className="bg-red-50 rounded-lg p-2 text-center">
                <div className="text-lg font-bold text-red-600">
                  {filteredExtinguishers.filter(ext => ext.status === 'expired').length}
                </div>
                <div className="text-xs text-red-700">หมดอายุ</div>
              </div>
              <div className="bg-blue-50 rounded-lg p-2 text-center">
                <div className="text-lg font-bold text-blue-600">
                  {filteredExtinguishers.filter(ext => ext.status === 'maintenance').length}
                </div>
                <div className="text-xs text-blue-700">ซ่อมบำรุง</div>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Location List */}
      <div className="mobile-card card-modern">
        <div className="p-4">
          <h3 className="text-lg font-bold text-gray-800 mb-4">รายการถังดับเพลิง</h3>
          <div className="space-y-3 max-h-96 overflow-y-auto">
            {filteredExtinguishers && filteredExtinguishers.length > 0 ? (
              filteredExtinguishers.map((ext) => (
                <div key={ext.id} onClick={() => {
                  setSelectedExtinguisher(ext);
                  if (ext.lat && ext.lng) setFocusLocation({ lat: ext.lat, lng: ext.lng, id: ext.id });
                }} className="bg-gray-50 rounded-lg p-3 hover:bg-gray-100 transition-colors cursor-pointer">
                  <div className="flex justify-between items-start mb-2">
                    <div className="font-semibold text-gray-800">{ext.id}</div>
                    <div className="flex items-center gap-2">
                      <span className={`text-xs px-2 py-1 rounded-full ${getStatusColor(ext.status)}`}>
                        {getStatusText(ext.status)}
                      </span>
                      <button
                        onClick={e => { e.stopPropagation(); setHistoryExtinguisher(ext); }}
                        className="text-xs px-2 py-1 bg-blue-100 text-blue-700 rounded-full hover:bg-blue-200"
                      >
                        ประวัติ
                      </button>
                    </div>
                  </div>
                  <div className="text-sm text-gray-600 mb-1">{ext.name}</div>
                  <div className="text-xs text-gray-500">
                    {getTypeText(ext.type)} - {ext.size} - {ext.village || ext.group}
                  </div>
                </div>
              ))
            ) : (
              <p className="text-gray-500 text-center">
                {selectedGroup === 'ทั้งหมด' 
                  ? 'ไม่มีข้อมูลถังดับเพลิง' 
                  : `ไม่มีถังดับเพลิงใน${selectedGroup}`
                }
              </p>
            )}
          </div>
        </div>
      </div>

      {/* Back Button */}
      <div className="text-center p-4">
        <button onClick={() => onChangeView('info')} className="mobile-btn" style={{ background: '#6b7280', color: 'white', width: 'auto', padding: '0.75rem 2rem' }}>
          <i className="fas fa-arrow-left mr-2"></i>กลับ
        </button>
      </div>
    </div>
  );
};

export default MapView;