import React, { useState, useEffect } from 'react';

const QRScannerView = ({ onBack, allExtinguishers, onCheckStatus }) => {
  const [scanning, setScanning] = useState(true);
  const [scannedData, setScannedData] = useState(null);
  const [extinguisherInfo, setExtinguisherInfo] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    let html5QrCode = null;
    let isScanning = false;

    const startScanner = async () => {
      try {
        // Dynamically import html5-qrcode
        const { Html5Qrcode } = await import('html5-qrcode');
        html5QrCode = new Html5Qrcode("qr-reader-admin");
        
        await html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 10,
            qrbox: { width: 250, height: 250 }
          },
          (decodedText) => {
            // Stop scanner and handle result
            if (isScanning && html5QrCode) {
              isScanning = false;
              html5QrCode.stop().then(() => {
                handleScanSuccess(decodedText);
              }).catch(() => {
                handleScanSuccess(decodedText);
              });
            }
          },
          () => {
            // Ignore scan errors
          }
        );
        isScanning = true;
      } catch (err) {
        console.error('Error starting QR scanner:', err);
        alert('ไม่สามารถเปิดกล้องได้\nกรุณาอนุญาตการเข้าถึงกล้อง');
        onBack();
      }
    };

    if (scanning) {
      startScanner();
    }

    // Cleanup
    return () => {
      if (html5QrCode && isScanning) {
        isScanning = false;
        html5QrCode.stop().catch(() => {
          // Ignore errors on cleanup
        });
      }
    };
  }, [scanning, onBack]);

  const handleScanSuccess = (decodedText) => {
    console.log('QR Code scanned:', decodedText);
    setScannedData(decodedText);
    setScanning(false);
    
    // Find extinguisher info
    findExtinguisher(decodedText);
  };

  const findExtinguisher = (qrCode) => {
    console.log('Searching for QR Code:', qrCode);
    console.log('All extinguishers:', allExtinguishers);
    
    // Search in allExtinguishers - try multiple fields
    const found = allExtinguishers.find(ext => {
      const match = ext.id === qrCode || 
                    ext.qrCode === qrCode ||
                    ext.assetNo === qrCode ||
                    ext.assetNumber === qrCode ||
                    ext.ID === qrCode;
      
      if (match) {
        console.log('Found extinguisher:', ext);
      }
      return match;
    });

    if (found) {
      setExtinguisherInfo(found);
      setError(null);
    } else {
      console.log('Extinguisher not found for QR Code:', qrCode);
      setError('ไม่พบข้อมูลถังดับเพลิงรหัส: ' + qrCode);
      setExtinguisherInfo(null);
    }
  };

  const handleScanAgain = () => {
    setScanning(true);
    setScannedData(null);
    setExtinguisherInfo(null);
    setError(null);
  };

  const getStatusColor = (status) => {
    if (status === 'ready' || status === 'normal' || status === 'ปกติ') {
      return 'bg-green-100 text-green-800 border-green-200';
    } else if (status === 'check' || status === 'abnormal' || status === 'ผิดปกติ' || status === 'needs_check') {
      return 'bg-red-100 text-red-800 border-red-200';
    } else if (status === 'expired' || status === 'หมดอายุ') {
      return 'bg-yellow-100 text-yellow-800 border-yellow-200';
    }
    return 'bg-gray-100 text-gray-800 border-gray-200';
  };

  const getStatusText = (status) => {
    if (status === 'ready' || status === 'normal') return 'ปกติ';
    if (status === 'check' || status === 'abnormal' || status === 'needs_check') return 'ผิดปกติ';
    if (status === 'expired') return 'หมดอายุ';
    return status;
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-blue-50">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-500 to-indigo-600 text-white p-4 shadow-lg">
        <div className="flex items-center">
          <button
            onClick={onBack}
            className="w-10 h-10 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full flex items-center justify-center mr-3 transition-colors"
          >
            <i className="fas fa-arrow-left"></i>
          </button>
          <div>
            <h2 className="text-xl font-bold">สแกน QR Code</h2>
            <p className="text-sm text-blue-100">วางกล้องให้ตรงกับ QR Code</p>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-2xl mx-auto px-4 py-6">
        {scanning ? (
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="text-center mb-4">
              <i className="fas fa-qrcode text-blue-600 text-4xl mb-3"></i>
              <h2 className="text-lg font-semibold text-gray-800 mb-2">
                สแกน QR Code ถังดับเพลิง
              </h2>
              <p className="text-sm text-gray-600">
                วางกล้องให้ตรงกับ QR Code
              </p>
            </div>

            {/* QR Scanner */}
            <div className="bg-gray-900 rounded-lg overflow-hidden">
              <div id="qr-reader-admin" style={{ width: '100%' }}></div>
            </div>

            <div className="mt-4 text-center">
              <button
                onClick={onBack}
                className="px-6 py-2 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition-colors"
              >
                ยกเลิก
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            {/* Scanned Result */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-semibold text-gray-800">
                  ผลการสแกน
                </h2>
                <span className="px-3 py-1 bg-green-100 text-green-800 rounded-full text-sm font-medium">
                  <i className="fas fa-check-circle mr-1"></i>
                  สแกนสำเร็จ
                </span>
              </div>
              
              <div className="bg-gray-50 rounded-lg p-4 mb-4">
                <p className="text-sm text-gray-600 mb-1">รหัส QR Code:</p>
                <p className="text-xl font-bold text-gray-800">{scannedData}</p>
              </div>

              {error && (
                <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-4">
                  <div className="flex items-start">
                    <i className="fas fa-exclamation-circle text-red-600 mt-1 mr-3"></i>
                    <div>
                      <p className="font-medium text-red-800">ไม่พบข้อมูล</p>
                      <p className="text-sm text-red-600 mt-1">{error}</p>
                    </div>
                  </div>
                </div>
              )}

              {extinguisherInfo && (
                <div className="border-t pt-4">
                  <h3 className="font-semibold text-gray-800 mb-3 flex items-center">
                    <i className="fas fa-fire-extinguisher text-red-600 mr-2"></i>
                    ข้อมูลถังดับเพลิง
                  </h3>

                  <div className="space-y-3">
                    {/* Status Badge */}
                    <div>
                      <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium border ${getStatusColor(extinguisherInfo.status)}`}>
                        {getStatusText(extinguisherInfo.status)}
                      </span>
                    </div>

                    {/* Info Grid */}
                    <div className="grid grid-cols-2 gap-3">
                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">รหัสถัง</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.id}</p>
                      </div>
                      
                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">หมู่บ้าน</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.village || extinguisherInfo.group || 'ไม่ระบุ'}</p>
                      </div>

                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">ประเภท</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.type || 'ไม่ระบุ'}</p>
                      </div>

                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">ขนาด</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.size || 'ไม่ระบุ'}</p>
                      </div>
                    </div>

                    {/* Owner Info */}
                    <div className="bg-blue-50 rounded-lg p-3">
                      <p className="text-xs text-blue-600 mb-1">เจ้าของ</p>
                      <p className="font-semibold text-blue-900">{extinguisherInfo.name || 'ไม่ระบุ'}</p>
                    </div>

                    {/* Dates */}
                    {(extinguisherInfo.installDate || extinguisherInfo.manufactureDate) && (
                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">วันที่ผลิต/ติดตั้ง</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.manufactureDate || extinguisherInfo.installDate}</p>
                      </div>
                    )}

                    {extinguisherInfo.expireDate && (
                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">วันหมดอายุ</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.expireDate}</p>
                      </div>
                    )}

                    {extinguisherInfo.lastCheck && (
                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">ตรวจสอบล่าสุด</p>
                        <p className="font-semibold text-gray-800">{extinguisherInfo.lastCheck}</p>
                      </div>
                    )}

                    {/* Location */}
                    {extinguisherInfo.lat && extinguisherInfo.lng && (
                      <div className="bg-gray-50 rounded-lg p-3">
                        <p className="text-xs text-gray-600 mb-1">พิกัด</p>
                        <p className="text-sm text-gray-800">
                          {extinguisherInfo.lat.toFixed(6)}, {extinguisherInfo.lng.toFixed(6)}
                        </p>
                        <button
                          onClick={() => window.open(`https://www.google.com/maps?q=${extinguisherInfo.lat},${extinguisherInfo.lng}`, '_blank')}
                          className="mt-2 text-sm text-blue-600 hover:text-blue-800 flex items-center"
                        >
                          <i className="fas fa-map-marker-alt mr-1"></i>
                          เปิดใน Google Maps
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className="grid grid-cols-2 gap-3 mt-6">
                {onCheckStatus && extinguisherInfo && (
                  <button
                    onClick={() => onCheckStatus(extinguisherInfo)}
                    className="col-span-2 px-4 py-3 bg-gradient-to-r from-green-500 to-emerald-600 text-white rounded-lg hover:from-green-600 hover:to-emerald-700 transition-all font-medium shadow-lg"
                  >
                    <i className="fas fa-clipboard-check mr-2"></i>
                    เช็คสถานะถังนี้
                  </button>
                )}
                <button
                  onClick={handleScanAgain}
                  className="px-4 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
                >
                  <i className="fas fa-qrcode mr-2"></i>
                  สแกนอีกครั้ง
                </button>
                <button
                  onClick={onBack}
                  className="px-4 py-3 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition-colors font-medium"
                >
                  <i className="fas fa-times mr-2"></i>
                  ปิด
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default QRScannerView;