import React, { useState, useEffect } from 'react';
import gasService from '../services/gasServiceSimple';

const CheckHistoryView = ({ extinguisher, onBack }) => {
  const [history, setHistory] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedRecord, setSelectedRecord] = useState(null);

  useEffect(() => {
    loadHistory();
  }, []);

  const loadHistory = async () => {
    setIsLoading(true);
    try {
      const result = await gasService.getCheckHistory(extinguisher.id);
      if (result && result.success) {
        setHistory(result.history || []);
      } else {
        console.error('Failed to load history:', result?.message);
        setHistory([]);
      }
    } catch (error) {
      console.error('Error loading history:', error);
      setHistory([]);
    } finally {
      setIsLoading(false);
    }
  };

  const checkItemLabels = {
    pressure: 'ความดันในถัง',
    pin: 'สลักนิรภัย',
    hose: 'สายและหัวฉีด',
    body: 'ตัวถังและฉลาก',
    location: 'ตำแหน่งการเข้าถึง',
    mount: 'ขาตั้งการยึด'
  };

  const isNormal = (status) => status === 'normal' || status === 'ปกติ';

  const getStatusBadge = (status) => {
    if (isNormal(status)) {
      return (
        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
          <i className="fas fa-check-circle mr-1"></i>
          ปกติ
        </span>
      );
    } else if (status === 'abnormal' || status === 'ผิดปกติ') {
      return (
        <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
          <i className="fas fa-times-circle mr-1"></i>
          ผิดปกติ
        </span>
      );
    }
    return null;
  };

  if (selectedRecord) {
    // Show detail of selected record
    return (
      <div className="min-h-screen bg-gradient-to-b from-gray-50 to-blue-50">
        {/* Header */}
        <div className="bg-white shadow-sm border-b sticky top-0 z-10">
          <div className="max-w-7xl mx-auto px-4 py-4">
            <div className="flex items-center">
              <button
                onClick={() => setSelectedRecord(null)}
                className="mr-4 p-2 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <i className="fas fa-arrow-left text-gray-600"></i>
              </button>
              <div className="flex-1">
                <h1 className="text-xl font-bold text-gray-800">รายละเอียดการตรวจสอบ</h1>
                <p className="text-sm text-gray-600">{selectedRecord.timestamp}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Content */}
        <div className="max-w-7xl mx-auto px-4 py-6">
          {/* Summary Card */}
          <div className={`rounded-lg shadow-sm border p-4 mb-4 ${
            isNormal(selectedRecord.overallStatus)
              ? 'bg-green-50 border-green-200' 
              : 'bg-red-50 border-red-200'
          }`}>
            <div className="flex items-center justify-between mb-3">
              <div>
                <h3 className="font-semibold text-gray-800">สรุปผลการตรวจสอบ</h3>
                <p className="text-sm text-gray-600">ผู้ตรวจสอบ: {selectedRecord.checkerName}</p>
              </div>
              <div className="text-right">
                {isNormal(selectedRecord.overallStatus) ? (
                  <span className="text-2xl text-green-600">
                    <i className="fas fa-check-circle"></i>
                  </span>
                ) : (
                  <span className="text-2xl text-red-600">
                    <i className="fas fa-exclamation-triangle"></i>
                  </span>
                )}
              </div>
            </div>
            <div className="grid grid-cols-3 gap-4 text-center">
              <div>
                <p className="text-2xl font-bold text-gray-800">{selectedRecord.totalItems}</p>
                <p className="text-xs text-gray-600">รายการทั้งหมด</p>
              </div>
              <div>
                <p className="text-2xl font-bold text-green-600">{selectedRecord.passedItems}</p>
                <p className="text-xs text-gray-600">ปกติ</p>
              </div>
              <div>
                <p className="text-2xl font-bold text-red-600">{selectedRecord.failedItems}</p>
                <p className="text-xs text-gray-600">ผิดปกติ</p>
              </div>
            </div>
          </div>

          {/* Check Items Detail */}
          <div className="space-y-3">
            {Object.entries(checkItemLabels).map(([key, label]) => {
              const status = selectedRecord[`${key}Status`];
              const note = selectedRecord[`${key}Note`];
              
              return (
                <div key={key} className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
                  <div className="flex items-start justify-between mb-2">
                    <h4 className="font-semibold text-gray-800">{label}</h4>
                    {getStatusBadge(status)}
                  </div>
                  {note && (
                    <div className="mt-2 p-3 bg-gray-50 rounded-lg">
                      <p className="text-sm text-gray-700">
                        <i className="fas fa-comment-alt text-gray-400 mr-2"></i>
                        {note}
                      </p>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  // Show history list
  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-blue-50">
      {/* Header */}
      <div className="bg-white shadow-sm border-b sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center">
            <button
              onClick={onBack}
              className="mr-4 p-2 hover:bg-gray-100 rounded-lg transition-colors"
            >
              <i className="fas fa-arrow-left text-gray-600"></i>
            </button>
            <div className="flex-1">
              <h1 className="text-xl font-bold text-gray-800">ประวัติการตรวจสอบ</h1>
              <p className="text-sm text-gray-600">รหัส: {extinguisher.id}</p>
            </div>
            <button
              onClick={loadHistory}
              className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
              disabled={isLoading}
            >
              <i className={`fas fa-sync ${isLoading ? 'fa-spin' : ''}`}></i>
            </button>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto px-4 py-6">
        {/* Extinguisher Info Card */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-4">
          <div className="flex items-center">
            <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center mr-4">
              <i className="fas fa-fire-extinguisher text-red-600 text-xl"></i>
            </div>
            <div>
              <h3 className="font-semibold text-gray-800">{extinguisher.name}</h3>
              <p className="text-sm text-gray-600">
                {extinguisher.group} • {extinguisher.size}
              </p>
            </div>
          </div>
        </div>

        {/* History Count */}
        <div className="mb-4">
          <h3 className="text-lg font-semibold text-gray-800">
            ประวัติการตรวจสอบ ({history.length} ครั้ง)
          </h3>
        </div>

        {/* Loading State */}
        {isLoading && (
          <div className="text-center py-12">
            <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent mb-4"></div>
            <p className="text-gray-600">กำลังโหลดข้อมูล...</p>
          </div>
        )}

        {/* Empty State */}
        {!isLoading && history.length === 0 && (
          <div className="text-center py-12">
            <i className="fas fa-history text-6xl text-gray-300 mb-4"></i>
            <p className="text-gray-600">ยังไม่มีประวัติการตรวจสอบ</p>
          </div>
        )}

        {/* History List */}
        {!isLoading && history.length > 0 && (
          <div className="space-y-3">
            {history.map((record, index) => (
              <div
                key={index}
                className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow cursor-pointer"
                onClick={() => setSelectedRecord(record)}
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex-1">
                    <div className="flex items-center mb-1">
                      <i className="fas fa-calendar-alt text-gray-400 mr-2 text-sm"></i>
                      <span className="font-semibold text-gray-800">{record.timestamp}</span>
                    </div>
                    <div className="flex items-center text-sm text-gray-600">
                      <i className="fas fa-user text-gray-400 mr-2"></i>
                      <span>ผู้ตรวจสอบ: {record.checkerName}</span>
                    </div>
                  </div>
                  <div>
                    {isNormal(record.overallStatus) ? (
                      <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-green-100 text-green-800">
                        <i className="fas fa-check-circle mr-1"></i>
                        ปกติ
                      </span>
                    ) : (
                      <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-red-100 text-red-800">
                        <i className="fas fa-exclamation-triangle mr-1"></i>
                        ผิดปกติ
                      </span>
                    )}
                  </div>
                </div>

                {/* Quick Summary */}
                <div className="flex items-center justify-between pt-3 border-t border-gray-100">
                  <div className="flex gap-4 text-sm">
                    <span className="text-green-600">
                      <i className="fas fa-check mr-1"></i>
                      ปกติ {record.passedItems}
                    </span>
                    <span className="text-red-600">
                      <i className="fas fa-times mr-1"></i>
                      ผิดปกติ {record.failedItems}
                    </span>
                  </div>
                  <i className="fas fa-chevron-right text-gray-400"></i>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default CheckHistoryView;
