import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LoadingOverlay from './components/LoadingOverlay';
import InfoView from './components/InfoView';
import UsageView from './components/UsageView';
import MapView from './components/MapView';
import LoginView from './components/LoginView';
import AdminView from './components/AdminView';
import FireReportView from './components/FireReportView';
import HistoryModal from './components/HistoryModal';
import Notification from './components/Notification';
import TestConnection from './components/TestConnection';
import ExtinguisherMenuView from './components/ExtinguisherMenuView';
import GeneralRequestView from './components/GeneralRequestView';
import MoreView from './components/MoreView';
import BottomNav from './components/BottomNav';
import gasService from './services/gasServiceSimple';
import './App.css';

function App() {
  const [currentView, setCurrentView] = useState('info');
  const [loading, setLoading] = useState(false);
  const [notification, setNotification] = useState(null);
  const [currentExtinguisher, setCurrentExtinguisher] = useState(null);
  const [allExtinguishers, setAllExtinguishers] = useState([]);
  const [stats, setStats] = useState({ total: 0, ready: 0, check: 0, expired: 0 });
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [historyData, setHistoryData] = useState([]);
  const [user, setUser] = useState(null); // For admin login
  const [emergencyMenuTrigger, setEmergencyMenuTrigger] = useState(0);
  const [backToast, setBackToast] = useState(false); // toast "กดอีกครั้งเพื่อออก"
  const backPressedOnce = React.useRef(false);
  const [installPrompt, setInstallPrompt] = useState(null); // PWA install prompt
  const [isInstalled, setIsInstalled] = useState(false);

  // ดัก beforeinstallprompt event
  useEffect(() => {
    const handler = (e) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handler);
    // เช็คว่าติดตั้งแล้วหรือยัง
    if (window.matchMedia('(display-mode: standalone)').matches) {
      setIsInstalled(true);
    }
    window.addEventListener('appinstalled', () => setIsInstalled(true));
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // โหลดข้อมูลเริ่มต้น
  useEffect(() => {
    loadExtinguishers();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // จัดการปุ่ม Back ของเครื่อง (Android / Line in-app browser)
  useEffect(() => {
    // push state ตั้งต้นเพื่อให้มี history entry อยู่เสมอ
    window.history.pushState({ view: 'info' }, '');

    const handlePopState = (e) => {
      const view = currentView;
      if (view !== 'info') {
        // ยังอยู่ในแอป → กลับไปหน้าก่อนหน้า
        goBack();
        // push state ใหม่เพื่อให้ยังมี entry ค้างไว้
        window.history.pushState({ view: currentView }, '');
      } else {
        // อยู่หน้าหลักแล้ว → กด 2 ครั้งถึงจะออก
        window.history.pushState({ view: 'info' }, '');
        if (backPressedOnce.current) {
          // กดครั้งที่ 2 ภายใน 2 วิ → ออกจากแอป
          window.history.go(-2);
        } else {
          // กดครั้งแรก → แสดง toast แล้วรอ 2 วิ
          backPressedOnce.current = true;
          setBackToast(true);
          setTimeout(() => {
            backPressedOnce.current = false;
            setBackToast(false);
          }, 2000);
        }
      }
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentView]);

  // โหลดข้อมูลถังดับเพลิงทั้งหมด
  // ถังดับเพลิง — ปิดไว้ก่อน ยังไม่ใช้งาน
  const loadExtinguishers = async () => {
    setLoading(false);
    setAllExtinguishers([]);
    setStats({ total: 0, ready: 0, check: 0, expired: 0 });
  };

  // ค้นหาถังดับเพลิง
  const searchExtinguisher = async (extinguisherId) => {
    if (!extinguisherId.trim()) {
      showNotification('กรุณาใส่รหัสถังดับเพลิง', 'error');
      return;
    }

    setLoading(true);
    try {
      const result = await gasService.getExtinguisherById(extinguisherId.toUpperCase());
      if (result && result.success) {
        setCurrentExtinguisher(result.data);
        showNotification('พบข้อมูลถังดับเพลิง', 'success');
      } else {
        setCurrentExtinguisher(null);
        showNotification(result.message || 'ไม่พบถังดับเพลิงรหัสนี้', 'error');
      }
    } catch (error) {
      console.error('Search error:', error);
      setCurrentExtinguisher(null);
      showNotification('เกิดข้อผิดพลาดในการค้นหา', 'error');
    } finally {
      setLoading(false);
    }
  };

  // แสดงประวัติถังดับเพลิง
  const showExtinguisherHistory = async () => {
    if (!currentExtinguisher) {
      showNotification('ไม่พบข้อมูลถังดับเพลิง', 'error');
      return;
    }

    setLoading(true);
    try {
      const result = await gasService.getCheckHistory(currentExtinguisher.id);
      if (result && result.success) {
        setHistoryData(result.history || []);
        setShowHistoryModal(true);
      } else {
        showNotification('ไม่สามารถโหลดประวัติได้', 'error');
      }
    } catch (error) {
      console.error('History error:', error);
      showNotification('เกิดข้อผิดพลาดในการโหลดประวัติ', 'error');
    } finally {
      setLoading(false);
    }
  };

  // แสดง notification
  const showNotification = (message, type = 'success') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  // เปลี่ยน view พร้อม push browser history
  const changeView = (viewName) => {
    setCurrentView(viewName);
    window.history.pushState({ view: viewName }, '');
  };

  // กลับหน้าก่อนหน้า (ใช้กับปุ่ม Back ของเครื่อง)
  const goBack = () => {
    const backMap = {
      'login':          'info',
      'admin':          'info',
      'extinguisher':   'info',
      'usage':          'info',
      'map':            'info',
      'more':           'info',
      'general-request':'info',
      'test':           'info',
      'fire-report':    'info',
      'electric-report':'info',
      'crane-report':   'info',
      'flood-report':   'info',
      'storm-report':   'info',
      'status':         'info',
    };
    const target = backMap[currentView] || 'info';
    setCurrentView(target);
  };

  // Handle admin login
  const handleLogin = (userData) => {
    setUser(userData);
    setCurrentView('admin');
    showNotification(`ยินดีต้อนรับ ${userData.name}`, 'success');
  };

  // Handle admin logout
  const handleLogout = () => {
    setUser(null);
    setCurrentView('info');
    showNotification('ออกจากระบบเรียบร้อย', 'success');
  };

  return (
    <div className="App">
      {/* Toast: กดย้อนกลับอีกครั้งเพื่อออก */}
      {backToast && (
        <div style={{
          position: 'fixed', bottom: '90px', left: '50%', transform: 'translateX(-50%)',
          background: 'rgba(0,0,0,0.75)', color: 'white',
          padding: '10px 24px', borderRadius: '24px',
          fontSize: '14px', fontWeight: '500',
          zIndex: 9999, whiteSpace: 'nowrap',
          animation: 'fadeIn 0.2s ease',
        }}>
          กดย้อนกลับอีกครั้งเพื่อออกจากแอป
        </div>
      )}
      {/* Header - Hide on login and admin pages */}
      {currentView !== 'login' && currentView !== 'admin' && currentView !== 'fire-report' && currentView !== 'electric-report' && currentView !== 'crane-report' && currentView !== 'flood-report' && currentView !== 'storm-report' && <Header user={user} installPrompt={installPrompt} isInstalled={isInstalled} />}

      {/* Loading Overlay */}
      {loading && <LoadingOverlay />}

      {/* Notification */}
      {notification && (
        <Notification
          message={notification.message}
          type={notification.type}
          onClose={() => setNotification(null)}
        />
      )}

      {/* Views */}
      <div className="app-content" style={{ paddingBottom: '80px' }}>
        {currentView === 'info' && (
          <InfoView
            currentExtinguisher={currentExtinguisher}
            onSearch={searchExtinguisher}
            onShowHistory={showExtinguisherHistory}
            onChangeView={changeView}
            triggerEmergencyMenu={emergencyMenuTrigger}
          />
        )}

        {currentView === 'extinguisher' && (
          <ExtinguisherMenuView
            onBack={() => changeView('info')}
            allExtinguishers={allExtinguishers}
            stats={stats}
            currentExtinguisher={currentExtinguisher}
            onSearch={searchExtinguisher}
            onShowHistory={showExtinguisherHistory}
          />
        )}

        {currentView === 'usage' && (
          <UsageView onChangeView={changeView} />
        )}

        {currentView === 'map' && (
          <MapView
            extinguishers={allExtinguishers}
            stats={stats}
            onChangeView={changeView}
          />
        )}

        {currentView === 'login' && (
          <LoginView
            onLogin={handleLogin}
            onBack={() => changeView('info')}
          />
        )}

        {currentView === 'admin' && user && (
          <AdminView
            user={user}
            onLogout={handleLogout}
            onChangeView={changeView}
            allExtinguishers={allExtinguishers}
            onRefreshData={loadExtinguishers}
          />
        )}

        {currentView === 'general-request' && (
          <GeneralRequestView onBack={() => changeView('info')} />
        )}

        {currentView === 'more' && (
          <MoreView onChangeView={changeView} installPrompt={installPrompt} isInstalled={isInstalled} />
        )}

        {currentView === 'prevention-stats' && (
          <div className="fixed inset-0 flex flex-col bg-white" style={{ zIndex: 9999 }}>
            <div className="flex items-center gap-3 px-4 py-3 text-white flex-shrink-0"
              style={{ background: 'linear-gradient(135deg, #1d4ed8 0%, #0ea5e9 100%)' }}>
              <button onClick={() => changeView('more')} className="p-1">
                <i className="fas fa-arrow-left text-xl"></i>
              </button>
              <div>
                <p className="font-bold text-sm">ข้อมูลสถิติ งานป้องกัน</p>
                <p className="text-xs text-yellow-100">องค์การบริหารส่วนตำบลสระกระโจม</p>
              </div>
            </div>
            <iframe
              src="https://bankbabead15.github.io/dashboardstaticsrakrajom/"
              title="ข้อมูลสถิติ งานป้องกัน"
              className="flex-1 w-full border-0"
              allow="fullscreen"
            />
          </div>
        )}

        {currentView === 'test' && (
          <TestConnection />
        )}

        {(currentView === 'fire-report' || currentView === 'electric-report' || currentView === 'crane-report' || currentView === 'flood-report' || currentView === 'storm-report') && (
          <FireReportView
            user={user}
            onBack={() => changeView('info')}
            reportType={currentView === 'electric-report' ? 'electric' : currentView === 'crane-report' ? 'crane' : currentView === 'flood-report' ? 'flood' : currentView === 'storm-report' ? 'storm' : 'fire'}
          />
        )}
      </div>

      {/* Bottom Nav */}
      {currentView !== 'login' && currentView !== 'admin' && currentView !== 'prevention-stats' && (
        <BottomNav
          currentView={currentView}
          emergencyMenuTrigger={emergencyMenuTrigger}
          onChangeView={(view) => {
            changeView(view);
          }}
          onShowEmergencyMenu={() => {
            if (currentView !== 'info') changeView('info');
            setEmergencyMenuTrigger(t => t + 1);
          }}
          onHome={() => {
            changeView('info');
            setEmergencyMenuTrigger(0);
          }}
        />
      )}

      {/* History Modal */}
      {showHistoryModal && (
        <HistoryModal
          extinguisher={currentExtinguisher}
          history={historyData}
          onClose={() => setShowHistoryModal(false)}
        />
      )}

    </div>
  );
}

export default App;