import React, { useState } from 'react';

const HistoryModal = ({ extinguisher, history, onClose }) => {
  const [expandedRecord, setExpandedRecord] = useState(null);
  const getStatusText = (status) => {
    const statuses = {
      'ready': 'พร้อมใช้',
      'check': 'ต้องตรวจสอบ',
      'expired': 'หมดอายุ',
      'maintenance': 'ซ่อมบำรุง'
    };
    return statuses[status] || 'พร้อมใช้';
  };

  const getStatusColor = (status) => {
    const colors = {
      'ready': 'bg-green-100 text-green-800',
      'check': 'bg-yellow-100 text-yellow-800',
      'expired': 'bg-red-100 text-red-800',
      'maintenance': 'bg-blue-100 text-blue-800'
    };
    return colors[status] || 'bg-green-100 text-green-800';
  };

  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  const toggleExpanded = (index) => {
    setExpandedRecord(expandedRecord === index ? null : index);
  };

  const getNotesColor = (notes) => {
    if (!notes || notes.trim() === '' || notes.toLowerCase().includes('ปกติ')) {
      return 'text-green-600';
    }
    return 'text-red-600';
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4" onClick={handleBackdropClick}>
      <div className="bg-white rounded-2xl shadow-xl max-w-lg w-full max-h-[85vh] md:max-h-[80vh] overflow-hidden">
        <div className="p-4 md:p-6 border-b flex-shrink-0">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-bold text-gray-800">ประวัติการตรวจสอบ</h3>
            <button onClick={onClose} className="text-gray-500 hover:text-gray-700">
              <i className="fas fa-times text-xl"></i>
            </button>
          </div>
          {extinguisher && (
            <p className="text-sm text-gray-600 mt-1">ถัง {extinguisher.id}</p>
          )}
        </div>
        <div className="p-4 md:p-6 overflow-y-auto" style={{ maxHeight: 'calc(85vh - 120px)' }}>
          {history && history.length > 0 ? (
            <div className="space-y-4">
              {history.map((record, index) => (
                <div key={index} className="border border-gray-200 rounded-lg p-3">
                  <div className="flex justify-between items-start mb-2">
                    <span className="font-semibold text-gray-800">{record.checkDate}</span>
                    <span className={`text-xs px-2 py-1 rounded-full ${getStatusColor(record.status)}`}>
                      {getStatusText(record.status)}
                    </span>
                  </div>
                  <div className="text-sm text-gray-600 mb-1">ประเภท: {record.checkType}</div>
                  <div className="text-sm text-gray-600 mb-1">ผู้ตรวจสอบ: {record.inspector}</div>
                  <div className="text-sm mb-2">
                    <span className="text-gray-600">หมายเหตุ: </span>
                    <span className={`font-medium ${getNotesColor(record.notes)}`}>
                      {record.notes || 'ปกติ'}
                    </span>
                  </div>
                  
                  {/* ปุ่มขยายรายละเอียด */}
                  {record.details && (
                    <div>
                      <button 
                        onClick={() => toggleExpanded(index)}
                        className="flex items-center text-sm text-blue-600 hover:text-blue-800 font-medium"
                      >
                        <i className={`fas fa-chevron-${expandedRecord === index ? 'up' : 'down'} mr-2`}></i>
                        รายละเอียดการตรวจสอบ
                      </button>
                      
                      {/* รายละเอียดที่ขยายได้ */}
                      {expandedRecord === index && (
                        <div className="mt-3 bg-gray-50 rounded-lg p-3 space-y-2">
                          <div className="grid grid-cols-1 gap-2 text-sm">
                            <div className="flex justify-between">
                              <span className="text-gray-600">สถานะแรงดัน:</span>
                              <span className={`font-medium ${record.details.pressure === 'ปกติ' ? 'text-green-600' : 'text-red-600'}`}>
                                {record.details.pressure}
                              </span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">สถานะสลัก:</span>
                              <span className={`font-medium ${record.details.pin === 'ปกติ' ? 'text-green-600' : 'text-red-600'}`}>
                                {record.details.pin}
                              </span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">สถานะสายและหัวฉีด:</span>
                              <span className={`font-medium ${record.details.hose === 'ปกติ' ? 'text-green-600' : 'text-red-600'}`}>
                                {record.details.hose}
                              </span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">สถานะตัวถังและฉลาก:</span>
                              <span className={`font-medium ${record.details.body === 'ปกติ' ? 'text-green-600' : 'text-red-600'}`}>
                                {record.details.body}
                              </span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">สถานะตำแหน่งการเข้าถึง:</span>
                              <span className={`font-medium ${record.details.access === 'ปกติ' ? 'text-green-600' : 'text-red-600'}`}>
                                {record.details.access}
                              </span>
                            </div>
                            <div className="flex justify-between">
                              <span className="text-gray-600">สถานะขาตั้งและการยึด:</span>
                              <span className={`font-medium ${record.details.mount === 'ปกติ' ? 'text-green-600' : 'text-red-600'}`}>
                                {record.details.mount}
                              </span>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p className="text-gray-500 text-center">ไม่มีประวัติการตรวจสอบ</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default HistoryModal;