import React, { useEffect, useState } from 'react';

const Notification = ({ message, type = 'success', onClose }) => {
  const [show, setShow] = useState(false);

  useEffect(() => {
    setShow(true);
    const timer = setTimeout(() => {
      setShow(false);
      setTimeout(onClose, 300);
    }, 3000);

    return () => clearTimeout(timer);
  }, [onClose]);

  const bgColor = type === 'success' 
    ? 'bg-gradient-to-r from-green-500 to-emerald-500' 
    : 'bg-gradient-to-r from-red-500 to-red-600';

  return (
    <div 
      className={`fixed top-5 right-5 z-50 px-6 py-4 rounded-lg text-white font-medium shadow-lg transition-transform duration-300 ${bgColor} ${
        show ? 'transform translate-x-0' : 'transform translate-x-full'
      }`}
    >
      <div className="flex items-center">
        <i className={`fas ${type === 'success' ? 'fa-check-circle' : 'fa-exclamation-circle'} mr-2`}></i>
        {message}
      </div>
    </div>
  );
};

export default Notification;