import React, { useState } from 'react';

const AddExtinguisherView = ({ user, onBack, onSave, isLoading }) => {
  // Form State
  const [formData, setFormData] = useState({
    // 1. ข้อมูลผู้ดูแล
    ownerName: '',
    ownerSurname: '',
    houseNumber: '',
    village: '',
    assetNumber: '',
    phoneNumber: '',
    
    // 2. ตำแหน่งที่ตั้ง
    latitude: '',
    longitude: '',
    
    // 3. ข้อมูลจำเพาะถังดับเพลิง
    extinguisherType: 'powder', // ชนิดผงเคมีแห้ง
    size: '10', // ปอนด์
    installDate: '',
    expireDate: '',
    notes: '',
    
    // 4. รูปถ่าย
    photos: [],
    photoPreviews: []
  });

  const [isLoadingLocation, setIsLoadingLocation] = useState(false);
  const [showMapPicker, setShowMapPicker] = useState(false);

  // Handle input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  // Get current location
  const getCurrentLocation = () => {
    if (navigator.geolocation) {
      setIsLoadingLocation(true);
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setFormData(prev => ({
            ...prev,
            latitude: position.coords.latitude.toFixed(6),
            longitude: position.coords.longitude.toFixed(6)
          }));
          setIsLoadingLocation(false);
          alert(`พบตำแหน่งปัจจุบัน!\nละติจูด: ${position.coords.latitude.toFixed(6)}\nลองจิจูด: ${position.coords.longitude.toFixed(6)}`);
        },
        (error) => {
          setIsLoadingLocation(false);
          alert('ไม่สามารถหาตำแหน่งได้\nกรุณาตรวจสอบการอนุญาตและ GPS');
        },
        { enableHighAccuracy: true, timeout: 10000 }
      );
    } else {
      alert('เบราว์เซอร์ไม่รองรับการหาตำแหน่ง');
    }
  };

  // Handle photo selection
  const handlePhotoChange = (e) => {
    const files = Array.from(e.target.files);
    
    if (formData.photos.length + files.length > 4) {
      alert('สามารถเพิ่มรูปได้สูงสุด 4 รูปเท่านั้น');
      return;
    }
    
    const newPhotos = [...formData.photos];
    const newPreviews = [...formData.photoPreviews];
    
    files.forEach(file => {
      if (newPhotos.length < 4) {
        newPhotos.push(file);
        newPreviews.push(URL.createObjectURL(file));
      }
    });
    
    setFormData(prev => ({
      ...prev,
      photos: newPhotos,
      photoPreviews: newPreviews
    }));
  };

  // Handle camera capture
  const handleCameraCapture = () => {
    if (formData.photos.length >= 4) {
      alert('สามารถเพิ่มรูปได้สูงสุด 4 รูปเท่านั้น');
      return;
    }
    document.getElementById('cameraInput').click();
  };

  // Remove photo
  const removePhoto = (index) => {
    const newPhotos = formData.photos.filter((_, i) => i !== index);
    const newPreviews = formData.photoPreviews.filter((_, i) => i !== index);
    
    setFormData(prev => ({
      ...prev,
      photos: newPhotos,
      photoPreviews: newPreviews
    }));
  };

  // Handle form submit
  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Validation
    if (!formData.ownerName || !formData.houseNumber || !formData.village) {
      alert('กรุณากรอกข้อมูลผู้ดูแลให้ครบถ้วน');
      return;
    }
    
    if (!formData.latitude || !formData.longitude) {
      alert('กรุณาระบุตำแหน่งที่ตั้ง');
      return;
    }
    
    if (!formData.installDate || !formData.expireDate) {
      alert('กรุณาระบุวันที่ติดตั้งและวันหมดอายุ');
      return;
    }
    
    // Format dates to DD/MM/YYYY (Thai format)
    const formatDate = (dateString) => {
      if (!dateString) return '';
      const date = new Date(dateString);
      const day = date.getDate();
      const month = date.getMonth() + 1;
      const year = date.getFullYear() + 543; // Convert to Buddhist year
      return `${day.toString().padStart(2, '0')}/${month.toString().padStart(2, '0')}/${year}`;
    };
    
    // Create formatted data
    const formattedData = {
      ...formData,
      installDate: formatDate(formData.installDate),
      expireDate: formatDate(formData.expireDate),
      adminId: user?.id || '',
      adminName: user?.name || ''
    };
    
    // Call onSave callback
    onSave(formattedData);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Loading Overlay */}
      {isLoading && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center">
          <div className="bg-white rounded-lg p-8 max-w-sm mx-4 text-center shadow-2xl">
            <div className="mb-4">
              <div className="inline-block animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent"></div>
            </div>
            <h3 className="text-lg font-semibold text-gray-800 mb-2">กำลังบันทึกข้อมูล...</h3>
            <p className="text-sm text-gray-600">กรุณารอสักครู่</p>
            <div className="mt-4 space-y-1 text-xs text-gray-500">
              <p>• บันทึกข้อมูลถังดับเพลิง</p>
              <p>• สร้าง QR Code</p>
              <p>• อัปโหลดรูปภาพ</p>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="bg-gradient-to-r from-blue-500 to-indigo-600 text-white p-4 shadow-md">
        <div className="max-w-4xl mx-auto flex items-center">
          <button
            onClick={onBack}
            className="mr-4 p-2 hover:bg-white hover:bg-opacity-20 rounded-lg transition-colors"
          >
            <i className="fas fa-arrow-left text-xl"></i>
          </button>
          <h1 className="text-xl font-bold">เพิ่มถังดับเพลิง</h1>
        </div>
      </div>

      {/* Form */}
      <div className="max-w-4xl mx-auto p-4">
        <form onSubmit={handleSubmit} className="space-y-6">
          
          {/* 1. ข้อมูลผู้ดูแล */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
              <i className="fas fa-user text-blue-600 mr-2"></i>
              ข้อมูลผู้ดูแล
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  ชื่อ <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="ownerName"
                  value={formData.ownerName}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="ชื่อผู้ดูแล"
                  required
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  นามสกุล
                </label>
                <input
                  type="text"
                  name="ownerSurname"
                  value={formData.ownerSurname}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="นามสกุลผู้ดูแล"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  บ้านเลขที่ <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  name="houseNumber"
                  value={formData.houseNumber}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="เลขที่บ้าน"
                  required
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  หมู่ที่ <span className="text-red-500">*</span>
                </label>
                <select
                  name="village"
                  value={formData.village}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                >
                  <option value="">เลือกหมู่</option>
                  {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                    <option key={num} value={num}>หมู่ {num}</option>
                  ))}
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  เลขครุภัณฑ์
                </label>
                <input
                  type="text"
                  name="assetNumber"
                  value={formData.assetNumber}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="เลขครุภัณฑ์"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  เบอร์โทร
                </label>
                <input
                  type="tel"
                  name="phoneNumber"
                  value={formData.phoneNumber}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="0xx-xxx-xxxx"
                />
              </div>
            </div>
          </div>

          {/* 2. ตำแหน่งที่ตั้ง */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
              <i className="fas fa-map-marker-alt text-red-600 mr-2"></i>
              ตำแหน่งที่ตั้ง
            </h2>
            
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    ละติจูด (Latitude) <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    step="0.000001"
                    name="latitude"
                    value={formData.latitude}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="14.570741"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    ลองจิจูด (Longitude) <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="number"
                    step="0.000001"
                    name="longitude"
                    value={formData.longitude}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                    placeholder="100.145119"
                    required
                  />
                </div>
              </div>
              
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={getCurrentLocation}
                  disabled={isLoadingLocation}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors disabled:bg-gray-400 flex items-center justify-center"
                >
                  {isLoadingLocation ? (
                    <>
                      <div className="animate-spin mr-2">⟳</div>
                      กำลังค้นหา...
                    </>
                  ) : (
                    <>
                      <i className="fas fa-crosshairs mr-2"></i>
                      ใช้ตำแหน่งปัจจุบัน
                    </>
                  )}
                </button>
                
                <button
                  type="button"
                  onClick={() => setShowMapPicker(true)}
                  className="flex-1 px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors flex items-center justify-center"
                >
                  <i className="fas fa-map mr-2"></i>
                  เลือกจากแผนที่
                </button>
              </div>
            </div>
          </div>

          {/* 3. ข้อมูลจำเพาะถังดับเพลิง */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
              <i className="fas fa-fire-extinguisher text-red-600 mr-2"></i>
              ข้อมูลจำเพาะถังดับเพลิง
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  ประเภทถังดับเพลิง
                </label>
                <select
                  name="extinguisherType"
                  value={formData.extinguisherType}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="powder">ชนิดผงเคมีแห้ง</option>
                  <option value="co2">ชนิดคาร์บอนไดออกไซด์</option>
                  <option value="foam">ชนิดโฟม</option>
                  <option value="water">ชนิดน้ำ</option>
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  ขนาด (ปอนด์)
                </label>
                <select
                  name="size"
                  value={formData.size}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="5">5 ปอนด์</option>
                  <option value="10">10 ปอนด์</option>
                  <option value="15">15 ปอนด์</option>
                  <option value="20">20 ปอนด์</option>
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  วันที่ติดตั้ง <span className="text-red-500">*</span>
                </label>
                <input
                  type="date"
                  name="installDate"
                  value={formData.installDate}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  วันหมดอายุ <span className="text-red-500">*</span>
                </label>
                <input
                  type="date"
                  name="expireDate"
                  value={formData.expireDate}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>
              
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  หมายเหตุเพิ่มเติม
                </label>
                <textarea
                  name="notes"
                  value={formData.notes}
                  onChange={handleChange}
                  rows="3"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="ระบุข้อมูลเพิ่มเติม..."
                ></textarea>
              </div>
            </div>
          </div>

          {/* 4. รูปถ่ายถังดับเพลิง */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold text-gray-800 mb-4 flex items-center">
              <i className="fas fa-camera text-purple-600 mr-2"></i>
              รูปถ่ายถังดับเพลิง
              <span className="ml-2 text-sm font-normal text-gray-500">
                ({formData.photos.length}/4)
              </span>
            </h2>
            
            <div className="space-y-4">
              {/* Photo Previews Grid */}
              {formData.photoPreviews.length > 0 && (
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {formData.photoPreviews.map((preview, index) => (
                    <div key={index} className="relative aspect-square bg-gray-100 rounded-lg overflow-hidden group">
                      <img
                        src={preview}
                        alt={`Preview ${index + 1}`}
                        className="w-full h-full object-cover"
                      />
                      <button
                        type="button"
                        onClick={() => removePhoto(index)}
                        className="absolute top-1 right-1 p-1.5 bg-red-600 text-white rounded-full hover:bg-red-700 opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <i className="fas fa-times text-xs"></i>
                      </button>
                      <div className="absolute bottom-1 left-1 px-2 py-0.5 bg-black bg-opacity-60 text-white text-xs rounded">
                        รูปที่ {index + 1}
                      </div>
                    </div>
                  ))}
                  
                  {/* Add More Button */}
                  {formData.photos.length < 4 && (
                    <div className="aspect-square bg-gray-100 rounded-lg border-2 border-dashed border-gray-300 flex items-center justify-center">
                      <label className="cursor-pointer flex flex-col items-center text-gray-500 hover:text-gray-700">
                        <i className="fas fa-plus text-2xl mb-1"></i>
                        <span className="text-xs">เพิ่มรูป</span>
                        <input
                          type="file"
                          accept="image/*"
                          onChange={handlePhotoChange}
                          className="hidden"
                          multiple
                        />
                      </label>
                    </div>
                  )}
                </div>
              )}
              
              {/* Action Buttons */}
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={handleCameraCapture}
                  disabled={formData.photos.length >= 4}
                  className="flex-1 px-4 py-3 bg-purple-600 text-white rounded-md hover:bg-purple-700 transition-colors flex items-center justify-center disabled:bg-gray-400 disabled:cursor-not-allowed"
                >
                  <i className="fas fa-camera mr-2"></i>
                  ถ่ายรูป
                </button>
                
                <label className={`flex-1 px-4 py-3 rounded-md transition-colors flex items-center justify-center cursor-pointer ${
                  formData.photos.length >= 4 
                    ? 'bg-gray-400 cursor-not-allowed' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700'
                }`}>
                  <i className="fas fa-image mr-2"></i>
                  เลือกรูป
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handlePhotoChange}
                    className="hidden"
                    multiple
                    disabled={formData.photos.length >= 4}
                  />
                </label>
              </div>
              
              {formData.photos.length === 0 && (
                <div className="text-center py-8 text-gray-400">
                  <i className="fas fa-images text-4xl mb-2"></i>
                  <p className="text-sm">ยังไม่มีรูปภาพ</p>
                  <p className="text-xs">สามารถเพิ่มได้สูงสุด 4 รูป</p>
                </div>
              )}
              
              {/* Hidden camera input */}
              <input
                id="cameraInput"
                type="file"
                accept="image/*"
                capture="environment"
                onChange={handlePhotoChange}
                className="hidden"
              />
            </div>
          </div>

          {/* Submit Buttons */}
          <div className="flex gap-4">
            <button
              type="button"
              onClick={onBack}
              className="flex-1 px-6 py-3 bg-gray-500 text-white rounded-md hover:bg-gray-600 transition-colors"
            >
              ยกเลิก
            </button>
            <button
              type="submit"
              className="flex-1 px-6 py-3 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors flex items-center justify-center"
            >
              <i className="fas fa-save mr-2"></i>
              บันทึกถังดับเพลิง
            </button>
          </div>
        </form>
      </div>

      {/* Map Picker Modal (Placeholder) */}
      {showMapPicker && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-auto">
            <div className="p-4 border-b flex items-center justify-between">
              <h3 className="text-lg font-semibold">เลือกตำแหน่งบนแผนที่</h3>
              <button
                onClick={() => setShowMapPicker(false)}
                className="p-2 hover:bg-gray-100 rounded-full"
              >
                <i className="fas fa-times"></i>
              </button>
            </div>
            <div className="p-4">
              <div className="h-96 bg-gray-200 rounded-lg flex items-center justify-center">
                <p className="text-gray-600">Map Picker จะพัฒนาในขั้นตอนถัดไป</p>
              </div>
              <div className="mt-4 flex gap-2">
                <button
                  onClick={() => setShowMapPicker(false)}
                  className="flex-1 px-4 py-2 bg-gray-500 text-white rounded-md hover:bg-gray-600"
                >
                  ยกเลิก
                </button>
                <button
                  onClick={() => {
                    alert('ฟีเจอร์นี้จะพัฒนาในขั้นตอนถัดไป');
                    setShowMapPicker(false);
                  }}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
                >
                  ยืนยันตำแหน่ง
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AddExtinguisherView;
