// บีบอัดรูปและแปลง base64 (max 800px, quality 0.6)
function compressAndBase64(file, maxSize = 800, quality = 0.6) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      let w = img.width, h = img.height;
      if (w > maxSize || h > maxSize) {
        if (w > h) { h = Math.round(h * maxSize / w); w = maxSize; }
        else { w = Math.round(w * maxSize / h); h = maxSize; }
      }
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      URL.revokeObjectURL(url);
      resolve(canvas.toDataURL('image/jpeg', quality).split(',')[1]);
    };
    img.onerror = reject;
    img.src = url;
  });
}

// ทำความสะอาด callbacks เก่า
function cleanupOldCallbacks() {
  let cleaned = 0;
  for (const key in window) {
    if (key.startsWith('gasCallback_')) {
      delete window[key];
      cleaned++;
    }
  }
  // Cleanup completed silently
  return cleaned;
}

// JSONP call function
function callGASWithJSONP(functionName, parameters = {}) {
  return new Promise((resolve, reject) => {
    // Validate URL first
    if (!GAS_WEB_APP_URL || GAS_WEB_APP_URL === '') {
      reject(new Error('GAS_WEB_APP_URL is not configured'));
      return;
    }

    const callbackName = 'gasCallback_' + Date.now() + '_' + Math.random().toString(36).substring(2, 11);
    
    let script;
    let timeoutId;
    
    // สร้าง callback ก่อน (สำคัญมาก!)
    window[callbackName] = function(data) {
      // ทำความสะอาด
      delete window[callbackName];
      if (script && script.parentNode) {
        document.head.removeChild(script);
      }
      clearTimeout(timeoutId);
      resolve(data);
    };
    
    try {
      // สร้าง URL
      const url = new URL(GAS_WEB_APP_URL);
      url.searchParams.append('action', functionName);
      url.searchParams.append('callback', callbackName);
      
      Object.keys(parameters).forEach(key => {
        if (parameters[key] !== undefined && parameters[key] !== null) {
          url.searchParams.append(key, parameters[key]);
        }
      });
      
      // สร้าง script หลังจากสร้าง callback แล้ว
      script = document.createElement('script');
      script.src = url.toString();
      script.onerror = function() {
        delete window[callbackName];
        clearTimeout(timeoutId);
        reject(new Error('Script loading failed'));
      };
      
      document.head.appendChild(script);
      
      // Timeout - เพิ่มเวลารอเป็น 30 วินาที
      timeoutId = setTimeout(() => {
        if (window[callbackName]) {
          delete window[callbackName];
          if (script && script.parentNode) {
            document.head.removeChild(script);
          }
          reject(new Error('Request timeout'));
        }
      }, 30000);
    } catch (error) {
      delete window[callbackName];
      reject(new Error('Failed to construct URL: ' + error.message));
    }
  });
}

