import React, { useState } from 'react';
import { triggerSiren } from '../utils/siren';

const EMERGENCY_PHONE = process.env.REACT_APP_EMERGENCY_PHONE || '0632316901';
const GAS_URL = process.env.REACT_APP_GAS_WEB_APP_URL;
const GAS_EMERGENCY_CALL_URL = process.env.REACT_APP_GAS_EMERGENCY_CALL_URL;
const BOT_TOKEN = process.env.REACT_APP_TELEGRAM_BOT_TOKEN;
const CHAT_ID = process.env.REACT_APP_TELEGRAM_CHAT_ID;

const callGASJSONP = (url, params) => {
  return new Promise((resolve, reject) => {
    const cbName = 'gasCallback_' + Date.now();
    const script = document.createElement('script');
    const timer = setTimeout(() => {
      delete window[cbName];
      if (script.parentNode) document.head.removeChild(script);
      reject(new Error('timeout'));
    }, 15000);
    window[cbName] = (data) => {
      clearTimeout(timer);
      delete window[cbName];
      if (script.parentNode) document.head.removeChild(script);
      resolve(data);
    };
    const u = new URL(url);
    u.searchParams.append('callback', cbName);
    Object.keys(params).forEach(k => u.searchParams.append(k, params[k]));
    script.src = u.toString();
    script.onerror = () => { clearTimeout(timer); delete window[cbName]; reject(new Error('script error')); };
    document.head.appendChild(script);
  });
};

const BottomNav = ({ currentView, onChangeView, onShowEmergencyMenu, onHome, emergencyMenuTrigger }) => {
  const [showConfirm, setShowConfirm] = useState(false);
  const [sending, setSending] = useState(false);
  const [preloadedLocation, setPreloadedLocation] = useState(null);
  const [locationLoading, setLocationLoading] = useState(false);
  const [emergencyMenuOpen, setEmergencyMenuOpen] = useState(false);

  // sync กับ trigger จาก App.js — ถ้า reset เป็น 0 = modal ปิดแล้ว
  React.useEffect(() => {
    if (emergencyMenuTrigger === 0) setEmergencyMenuOpen(false);
    else if (emergencyMenuTrigger > 0) setEmergencyMenuOpen(true);
  }, [emergencyMenuTrigger]);

  const leftItems = [
    { id: 'info', icon: 'fa-house', label: 'หน้าหลัก' },
    { id: 'emergency-call', icon: 'fa-phone', label: 'เบอร์ฉุกเฉิน' },
  ];
  const rightItems = [
    { id: 'status', icon: 'fa-list', label: 'สถานะแจ้งเหตุ' },
    { id: 'more', icon: 'fa-ellipsis', label: 'อื่นๆ' },
  ];

  const handleClick = (id) => {
    if (id === 'emergency-call') {
      setEmergencyMenuOpen(true);
      onShowEmergencyMenu();
    } else if (id === 'more') {
      setEmergencyMenuOpen(false);
      onChangeView('more');
    } else if (id === 'info') {
      setEmergencyMenuOpen(false);
      if (onHome) onHome();
      else onChangeView('info');
    } else {
      setEmergencyMenuOpen(false);
      onChangeView(id);
    }
  };

  const isActive = (id) => {
    if (id === 'emergency-call') return emergencyMenuOpen;
    if (id === 'info') return currentView === 'info' && !emergencyMenuOpen;
    return currentView === id;
  };

  // ขอ GPS ล่วงหน้าทันทีที่กดปุ่มโทรด่วน
  const handleEmergencyButtonClick = () => {
    setPreloadedLocation(null);
    setShowConfirm(true);

    if (!navigator.geolocation) return;

    setLocationLoading(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setPreloadedLocation({
          lat: pos.coords.latitude.toFixed(6),
          lng: pos.coords.longitude.toFixed(6),
        });
        setLocationLoading(false);
      },
      () => {
        // ปฏิเสธหรือ error → ยังแสดง confirm ได้ แต่ไม่มีพิกัด
        setLocationLoading(false);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const handleConfirmed = async () => {
    setSending(true);

    // โทรออกทันที
    window.location.href = `tel:${EMERGENCY_PHONE}`;
    triggerSiren(); // เปิดไซเรน

    const userName = localStorage.getItem('userName') || '';
    const userPhone = localStorage.getItem('userPhone') || '';
    const userVillage = localStorage.getItem('userVillage') || '';
    const userAddress = localStorage.getItem('userAddress') || '';
    const timeStr = new Date().toLocaleString('th-TH');

    // ส่ง Telegram + GPS + บันทึก GAS
    const sendAll = async (lat, lng, mapsLink) => {
      if (BOT_TOKEN && CHAT_ID) {
        const msg = `🚨 ขอความช่วยเหลือฉุกเฉิน (ปุ่มโทรด่วน)\n\n` +
          `👤 ผู้แจ้ง: ${userName || '-'}\n` +
          `📞 เบอร์: ${userPhone || '-'}\n` +
          `🏠 บ้านเลขที่: ${userAddress || '-'} หมู่ ${userVillage || '-'}\n` +
          (lat ? `📍 พิกัด: ${lat}, ${lng}\n🗺️ ${mapsLink}\n` : `📍 พิกัด: ไม่สามารถระบุได้\n`) +
          `⏰ เวลา: ${timeStr}`;
        fetch(`https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: CHAT_ID, text: msg }),
        }).catch(() => {});
      }
      if (GAS_EMERGENCY_CALL_URL) {
        callGASJSONP(GAS_EMERGENCY_CALL_URL, {
          action: 'saveEmergencyCall',
          phone: userPhone, name: userName,
          village: userVillage, address: userAddress,
          lat: lat || '', lng: lng || '', googleMapsLink: mapsLink || '',
        }).catch(() => {});
      }
      if (GAS_URL) {
        const p = new URLSearchParams({
          action: 'saveEmergencyAlert',
          phone: userPhone, name: userName,
          village: userVillage, address: userAddress,
          lat: lat || '', lng: lng || '', googleMapsLink: mapsLink || '',
          source: 'ปุ่มโทรด่วน', time: timeStr,
        });
        fetch(`${GAS_URL}?${p}`).catch(() => {});
      }
    };

    // ใช้พิกัดที่โหลดล่วงหน้าไว้แล้ว (ถ้ามี)
    if (preloadedLocation) {
      const { lat, lng } = preloadedLocation;
      const mapsLink = `https://www.google.com/maps?q=${lat},${lng}`;
      await sendAll(lat, lng, mapsLink);
    } else if (locationLoading && navigator.geolocation) {
      // GPS ยังโหลดอยู่ → รอต่ออีกนิด (max 5 วิ)
      await new Promise((resolve) => {
        const timeout = setTimeout(() => resolve(), 5000);
        navigator.geolocation.getCurrentPosition(
          async (pos) => {
            clearTimeout(timeout);
            const lat = pos.coords.latitude.toFixed(6);
            const lng = pos.coords.longitude.toFixed(6);
            const mapsLink = `https://www.google.com/maps?q=${lat},${lng}`;
            await sendAll(lat, lng, mapsLink);
            resolve();
          },
          async () => {
            clearTimeout(timeout);
            await sendAll('', '', '');
            resolve();
          },
          { timeout: 5000 }
        );
      });
    } else {
      // ไม่มีพิกัด → ส่งโดยไม่มีพิกัด
      await sendAll('', '', '');
    }

    setSending(false);
    setShowConfirm(false);
  };

  const navBtn = (item) => (
    <button key={item.id} onClick={() => handleClick(item.id)}
      style={{
        display: 'flex', flexDirection: 'column', alignItems: 'center',
        gap: '0.2rem', background: 'none', border: 'none',
        cursor: 'pointer', padding: '0.25rem 0',
        color: isActive(item.id) ? '#2563eb' : '#6b7280',
        flex: 1,
      }}>
      <i className={`fas ${item.icon}`} style={{ fontSize: '1.3rem' }}></i>
      <span style={{ fontSize: '0.7rem', fontWeight: isActive(item.id) ? '700' : '400' }}>
        {item.label}
      </span>
    </button>
  );

  return (
    <>
      {/* Confirm Modal */}
      {showConfirm && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-sm w-full p-6 text-center">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4"
              style={{ animation: 'sos-pulse 1.5s infinite' }}>
              <i className="fas fa-phone-volume text-3xl text-red-600"></i>
            </div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">ยืนยันการโทรด่วน</h3>
            <p className="text-gray-600 text-sm mb-1">ระบบจะโทรหาเจ้าหน้าที่ทันที</p>
            <p className="text-gray-500 text-xs mb-2">พร้อมส่งตำแหน่งและแจ้ง Telegram</p>
            {/* สถานะ GPS */}
            <div className={`text-xs px-3 py-1.5 rounded-full mb-3 inline-flex items-center gap-1.5 ${
              preloadedLocation ? 'bg-green-100 text-green-700'
              : locationLoading ? 'bg-yellow-100 text-yellow-700'
              : 'bg-gray-100 text-gray-500'
            }`}>
              {preloadedLocation ? (
                <><i className="fas fa-map-marker-alt"></i> ได้พิกัดแล้ว ✅</>
              ) : locationLoading ? (
                <><i className="fas fa-spinner fa-spin"></i> กำลังหาพิกัด...</>
              ) : (
                <><i className="fas fa-map-marker-alt"></i> ไม่สามารถระบุพิกัดได้</>
              )}
            </div>
            <p className="font-mono font-bold text-red-600 text-lg mb-6">{EMERGENCY_PHONE}</p>
            <div className="flex gap-3">
              <button onClick={() => setShowConfirm(false)}
                className="flex-1 px-4 py-3 bg-gray-200 text-gray-700 rounded-lg font-medium">
                ยกเลิก
              </button>
              <button onClick={handleConfirmed} disabled={sending}
                className="flex-1 px-4 py-3 text-white rounded-lg font-bold"
                style={{ background: '#dc2626' }}>
                {sending ? <i className="fas fa-spinner fa-spin"></i> : <><i className="fas fa-phone mr-2"></i>โทรเลย</>}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Pulse button */}
      <div style={{
        position: 'fixed',
        bottom: 'calc(20px + env(safe-area-inset-bottom))',
        left: '50%', transform: 'translateX(-50%)',
        display: 'flex', flexDirection: 'column', alignItems: 'center',
        zIndex: 60, gap: '0.2rem',
      }}>
        <button onClick={handleEmergencyButtonClick} style={{
          width: '60px', height: '60px', borderRadius: '50%',
          background: '#dc2626', border: '4px solid white',
          boxShadow: '0 4px 16px rgba(220,38,38,0.5)',
          cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
          animation: 'sos-pulse 1.5s infinite',
        }}>
          <i className="fas fa-phone" style={{ color: 'white', fontSize: '1.4rem' }}></i>
        </button>
        <span style={{ fontSize: '0.8rem', fontWeight: '700', color: '#dc2626', whiteSpace: 'nowrap' }}>โทรด่วน</span>
      </div>

      <style>{`
        @keyframes sos-pulse {
          0%   { box-shadow: 0 0 0 0 rgba(220,38,38,0.6), 0 4px 16px rgba(220,38,38,0.4); }
          70%  { box-shadow: 0 0 0 14px rgba(220,38,38,0), 0 4px 16px rgba(220,38,38,0.4); }
          100% { box-shadow: 0 0 0 0 rgba(220,38,38,0), 0 4px 16px rgba(220,38,38,0.4); }
        }
      `}</style>

      <nav style={{
        position: 'fixed', bottom: 0, left: 0, right: 0,
        background: 'white', borderTop: '2px solid #2563eb',
        boxShadow: '0 -2px 10px rgba(37,99,235,0.1)', zIndex: 50,
        display: 'flex', alignItems: 'flex-end',
        padding: '0.5rem 0 calc(0.5rem + env(safe-area-inset-bottom))',
      }}>
        {leftItems.map(navBtn)}
        <div style={{ flex: 1 }} />
        {rightItems.map(navBtn)}
      </nav>
    </>
  );
};

export default BottomNav;
