import React, { useState, useEffect } from 'react';
import gasService from '../services/gasServiceSimple';
import AddExtinguisherView from './AddExtinguisherView';
import QRScannerView from './QRScannerView';
import ExtinguisherDetailView from './ExtinguisherDetailView';
import CheckStatusView from './CheckStatusView';
import CheckHistoryView from './CheckHistoryView';
import GoogleMapView from './GoogleMapView';
import { triggerSiren, stopSiren } from '../utils/siren';

const GAS_URL = process.env.REACT_APP_GAS_EXTINGUISHER_URL;

const callGASJSONP = (url, params) => {
  return new Promise((resolve, reject) => {
    const cbName = 'gasCallback_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
    const script = document.createElement('script');
    const timer = setTimeout(() => {
      delete window[cbName];
      if (script.parentNode) document.head.removeChild(script);
      reject(new Error('timeout'));
    }, 30000);
    window[cbName] = (data) => {
      clearTimeout(timer);
      delete window[cbName];
      if (script.parentNode) document.head.removeChild(script);
      resolve(data);
    };
    const u = new URL(url);
    u.searchParams.append('callback', cbName);
    Object.keys(params).forEach(k => u.searchParams.append(k, params[k]));
    script.src = u.toString();
    script.onerror = () => { clearTimeout(timer); delete window[cbName]; reject(new Error('script error')); };
    document.head.appendChild(script);
  });
};

const AdminView = ({ user, onLogout, onChangeView, allExtinguishers, onRefreshData }) => {
  const [stats, setStats] = useState({ total: 0, ready: 0, check: 0, expired: 0 });
  const [activeTab, setActiveTab] = useState('list');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedVillage, setSelectedVillage] = useState('');
  const [selectedMapVillage, setSelectedMapVillage] = useState('ทั้งหมด');
  const [isLoading, setIsLoading] = useState(false);
  const [mapCenter, setMapCenter] = useState({ lat: 14.570741, lng: 100.145119 }); // Default center
  const [showAddForm, setShowAddForm] = useState(false);
  const [showQRScanner, setShowQRScanner] = useState(false);
  const [selectedExtinguisher, setSelectedExtinguisher] = useState(null);
  const [checkingExtinguisher, setCheckingExtinguisher] = useState(null);
  const [historyExtinguisher, setHistoryExtinguisher] = useState(null);
  const [sirenOn, setSirenOn] = useState(false);
  const [showSirenModal, setShowSirenModal] = useState(false);
  const [sirenSending, setSirenSending] = useState(false);

  // Calculate stats from real data
  useEffect(() => {
    if (allExtinguishers && allExtinguishers.length > 0) {
      const newStats = {
        total: allExtinguishers.length,
        ready: allExtinguishers.filter(e => e.status === 'ready' || e.status === 'normal' || e.status === 'ปกติ').length,
        expired: allExtinguishers.filter(e => e.status === 'expired' || e.status === 'หมดอายุ').length,
        check: allExtinguishers.filter(e => e.status === 'check' || e.status === 'abnormal' || e.status === 'ผิดปกติ' || e.status === 'needs_check').length
      };
      setStats(newStats);
      console.log('Updated stats from real data:', newStats);
      console.log('All extinguishers:', allExtinguishers);
      console.log('Sample extinguisher data:', allExtinguishers[0]);
    } else {
      // ถ้าไม่มีข้อมูล ให้แสดง 0
      setStats({ total: 0, ready: 0, check: 0, expired: 0 });
      console.log('No extinguisher data available');
    }
  }, [allExtinguishers]);

  // Calculate overall status
  const getOverallStatus = () => {
    if (stats.expired > 0) {
      return { status: 'ต้องดำเนินการ', color: 'text-red-600', bgColor: 'bg-red-50', borderColor: 'border-red-200', icon: '⚠️' };
    } else if (stats.check > 0) {
      return { status: 'ควรตรวจสอบ', color: 'text-yellow-600', bgColor: 'bg-yellow-50', borderColor: 'border-yellow-200', icon: '⚡' };
    } else {
      return { status: 'ปกติ', color: 'text-green-600', bgColor: 'bg-green-50', borderColor: 'border-green-200', icon: '✅' };
    }
  };

  // Handle save new extinguisher
  const handleSaveExtinguisher = async (formData) => {
    setIsLoading(true);
    try {
      const GAS_URL = process.env.REACT_APP_GAS_EXTINGUISHER_URL;

      // Step 1: บันทึกข้อมูลถังผ่าน JSONP GET (ไม่มีรูป)
      const saveResult = await gasService.addExtinguisher(formData);
      console.log('saveResult:', JSON.stringify(saveResult));
      if (!saveResult || !saveResult.success) {
        throw new Error(saveResult?.message || 'ไม่สามารถบันทึกข้อมูลได้');
      }

      const extinguisherId = saveResult.extinguisherId;
      const folderId = saveResult.folderId;

      // Step 2: Upload photos if any
      if (formData.photos && formData.photos.length > 0) {
        const uploadResult = await gasService.uploadPhotos(
          extinguisherId,
          `${formData.ownerName} ${formData.ownerSurname || ''}`.trim(),
          formData.photos,
          folderId,        // ส่ง folderId ไปด้วย
          saveResult.rowIndex  // ส่ง rowIndex ไปด้วย
        );
        console.log('Upload result:', uploadResult);
      }

      alert('✅ บันทึกข้อมูลถังดับเพลิงสำเร็จ');
      setShowAddForm(false);
      if (onRefreshData) await onRefreshData();
    } catch (error) {
      console.error('Error saving extinguisher:', error);
      alert(`❌ เกิดข้อผิดพลาด: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };
  // Handle save check status
  const handleSaveCheckStatus = async (checkData) => {
    try {
      console.log('💾 Saving check status:', checkData);
      
      // Call GAS to save check status to ChecklistHistory sheet
      const result = await gasService.saveCheckStatus(checkData);
      
      if (!result || !result.success) {
        throw new Error(result?.message || 'ไม่สามารถบันทึกการตรวจสอบได้');
      }
      
      console.log('✅ Check status saved successfully:', result);
      
      // Refresh data
      if (onRefreshData) {
        await onRefreshData();
      }
      
      return { success: true };
    } catch (error) {
      console.error('❌ Error saving check status:', error);
      throw error;
    }
  };

  // If showing check status form, render it instead
  if (checkingExtinguisher) {
    return (
      <CheckStatusView
        extinguisher={checkingExtinguisher}
        user={user}
        onBack={() => setCheckingExtinguisher(null)}
        onSave={handleSaveCheckStatus}
      />
    );
  }

  // If showing history, render it instead
  if (historyExtinguisher) {
    return (
      <CheckHistoryView
        extinguisher={historyExtinguisher}
        onBack={() => setHistoryExtinguisher(null)}
      />
    );
  }

  // If showing extinguisher detail, render it instead
  if (selectedExtinguisher) {
    return (
      <ExtinguisherDetailView
        extinguisher={selectedExtinguisher}
        onBack={() => setSelectedExtinguisher(null)}
      />
    );
  }

  // If showing QR scanner, render it instead
  if (showQRScanner) {
    return (
      <QRScannerView
        onBack={() => setShowQRScanner(false)}
        allExtinguishers={allExtinguishers}
        onCheckStatus={(extinguisher) => {
          setShowQRScanner(false);
          setCheckingExtinguisher(extinguisher);
        }}
      />
    );
  }

  // If showing add form, render it instead
  if (showAddForm) {
    return (
      <AddExtinguisherView
        user={user}
        onBack={() => setShowAddForm(false)}
        onSave={handleSaveExtinguisher}
        isLoading={isLoading}
      />
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-blue-50">
      {/* Siren Modal */}
      {showSirenModal && (
        <div className="fixed inset-0 bg-black bg-opacity-60 z-[200] flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-xs w-full p-6 text-center shadow-2xl">
            {/* Icon */}
            <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${sirenOn ? 'bg-red-100' : 'bg-gray-100'}`}>
              <i className={`fas fa-bell text-3xl ${sirenOn ? 'text-red-600 animate-bounce' : 'text-gray-500'}`}></i>
            </div>

            <h3 className="text-lg font-bold text-gray-800 mb-1">ควบคุมไซเรน</h3>
            <p className="text-sm text-gray-500 mb-1">
              สถานะปัจจุบัน:{' '}
              <span className={`font-semibold ${sirenOn ? 'text-red-600' : 'text-gray-600'}`}>
                {sirenOn ? '🔔 เปิดอยู่' : '🔕 ปิดอยู่'}
              </span>
            </p>
            <p className="text-xs text-gray-400 mb-5">เลือกคำสั่งที่ต้องการส่งไปยังอุปกรณ์</p>

            {/* Action Buttons */}
            <div className="flex gap-3 mb-3">
              <button
                onClick={async () => {
                  setSirenSending(true);
                  try {
                    await triggerSiren();
                    setSirenOn(true);
                    setShowSirenModal(false);
                  } catch (e) {
                    alert('ไม่สามารถส่งคำสั่งได้');
                  } finally {
                    setSirenSending(false);
                  }
                }}
                disabled={sirenSending}
                className="flex-1 py-3 bg-red-600 hover:bg-red-700 text-white rounded-xl font-bold flex items-center justify-center gap-2 disabled:opacity-60 transition-colors"
              >
                {sirenSending ? (
                  <i className="fas fa-spinner fa-spin"></i>
                ) : (
                  <><i className="fas fa-bell"></i> เปิดไซเรน</>
                )}
              </button>
              <button
                onClick={async () => {
                  setSirenSending(true);
                  try {
                    await stopSiren();
                    setSirenOn(false);
                    setShowSirenModal(false);
                  } catch (e) {
                    alert('ไม่สามารถส่งคำสั่งได้');
                  } finally {
                    setSirenSending(false);
                  }
                }}
                disabled={sirenSending}
                className="flex-1 py-3 bg-gray-200 hover:bg-gray-300 text-gray-700 rounded-xl font-bold flex items-center justify-center gap-2 disabled:opacity-60 transition-colors"
              >
                {sirenSending ? (
                  <i className="fas fa-spinner fa-spin"></i>
                ) : (
                  <><i className="fas fa-bell-slash"></i> ปิดไซเรน</>
                )}
              </button>
            </div>

            {/* Cancel */}
            <button
              onClick={() => setShowSirenModal(false)}
              disabled={sirenSending}
              className="w-full py-2 text-gray-400 text-sm hover:text-gray-600 transition-colors"
            >
              ยกเลิก
            </button>
          </div>
        </div>
      )}

      {/* Loading Overlay */}
      {isLoading && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center">
          <div className="bg-white rounded-lg p-8 max-w-sm mx-4 text-center">
            <div className="mb-4">
              <div className="inline-block animate-spin rounded-full h-16 w-16 border-4 border-blue-500 border-t-transparent"></div>
            </div>
            <h3 className="text-lg font-semibold text-gray-800 mb-2">กำลังบันทึกข้อมูล...</h3>
            <p className="text-sm text-gray-600">กรุณารอสักครู่</p>
          </div>
        </div>
      )}

      {/* Admin Header */}
      <div className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div>
            {/* Top section with colored background */}
            <div className="bg-gradient-to-r from-blue-500 to-indigo-600 rounded-lg p-4 mb-3">
              {/* Icon and Title on same line */}
              <div className="flex items-center mb-1">
                <div className="w-8 h-8 bg-white bg-opacity-20 rounded-full flex items-center justify-center mr-3">
                  <i className="fas fa-user-shield text-white text-sm"></i>
                </div>
                <h1 className="text-xl font-bold text-white">ระบบจัดการเจ้าหน้าที่</h1>
              </div>
              
              {/* Welcome message on next line */}
              <p className="text-sm text-white text-opacity-90 ml-11">ยินดีต้อนรับ {user.name}</p>
            </div>
            
            {/* Buttons on third line */}
            <div className="flex items-center justify-between">
              <button
                onClick={() => onChangeView('info')}
                className="p-2 text-gray-600 hover:text-gray-800 transition-colors flex flex-col items-center"
                title="หน้าหลัก"
              >
                <i className="fas fa-home text-lg mb-1"></i>
                <span className="text-xs">หน้าหลัก</span>
              </button>
              
              <button
                onClick={async () => {
                  setIsLoading(true);
                  try {
                    await onRefreshData();
                    alert('รีเฟรชข้อมูลเสร็จแล้ว! ✅');
                  } catch (error) {
                    alert('เกิดข้อผิดพลาด: ' + error.message);
                  } finally {
                    setIsLoading(false);
                  }
                }}
                className="p-2 text-purple-600 hover:text-purple-800 transition-colors flex flex-col items-center"
                title="รีเฟรชข้อมูล"
                disabled={isLoading}
              >
                {isLoading ? (
                  <div className="animate-spin text-lg mb-1">⟳</div>
                ) : (
                  <i className="fas fa-sync text-lg mb-1"></i>
                )}
                <span className="text-xs">รีเฟรช</span>
              </button>
              
              <button
                onClick={() => setShowSirenModal(true)}
                className={`p-2 transition-colors flex flex-col items-center ${sirenOn ? 'text-red-600 hover:text-red-800' : 'text-gray-500 hover:text-gray-700'}`}
                title={sirenOn ? 'ปิดไซเรน' : 'เปิดไซเรน'}
              >
                <i className={`fas fa-bell text-lg mb-1 ${sirenOn ? 'animate-bounce' : ''}`}></i>
                <span className="text-xs">{sirenOn ? 'ปิดไซเรน' : 'ไซเรน'}</span>
              </button>
              
              <button
                onClick={() => setShowQRScanner(true)}
                className="p-2 text-blue-600 hover:text-blue-800 transition-colors flex flex-col items-center"
                title="สแกน QR Code"
              >
                <i className="fas fa-qrcode text-lg mb-1"></i>
                <span className="text-xs">สแกน</span>
              </button>
              
              <button
                onClick={() => setShowAddForm(true)}
                className="p-2 text-green-600 hover:text-green-800 transition-colors flex flex-col items-center"
                title="เพิ่มถังดับเพลิง"
              >
                <i className="fas fa-plus text-lg mb-1"></i>
                <span className="text-xs">เพิ่มถัง</span>
              </button>
              
              <button
                onClick={onLogout}
                className="p-2 text-red-600 hover:text-red-800 transition-colors flex flex-col items-center"
                title="ออกจากระบบ"
              >
                <i className="fas fa-sign-out-alt text-lg mb-1"></i>
                <span className="text-xs">ออก</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto px-4 py-4">
        <div className="space-y-4">
          {/* Summary Header - With background color */}
          <div className="bg-gray-100 rounded-md px-3 py-2 border-l-4 border-blue-500">
            <h2 className="text-base font-medium text-gray-700 flex items-center">
              <i className="fas fa-chart-bar text-blue-500 mr-2 text-sm"></i>
              สรุปภาพรวม
            </h2>
          </div>

          {/* Stats Cards - Smaller size */}
          <div className="grid grid-cols-4 gap-2">
            <div className="bg-blue-100 rounded-lg shadow-sm p-3 border border-blue-200">
              <div className="flex flex-col items-center text-center">
                <div className="w-6 h-6 bg-blue-200 rounded-lg flex items-center justify-center mb-1">
                  <i className="fas fa-fire-extinguisher text-blue-600 text-xs"></i>
                </div>
                <p className="text-lg font-bold text-blue-600">{stats.total}</p>
                <p className="text-xs font-medium text-blue-600">ทั้งหมด</p>
              </div>
            </div>

            <div className="bg-green-100 rounded-lg shadow-sm p-3 border border-green-200">
              <div className="flex flex-col items-center text-center">
                <div className="w-6 h-6 bg-green-200 rounded-lg flex items-center justify-center mb-1">
                  <i className="fas fa-check-circle text-green-600 text-xs"></i>
                </div>
                <p className="text-lg font-bold text-green-600">{stats.ready}</p>
                <p className="text-xs font-medium text-green-600">ปกติ</p>
              </div>
            </div>

            <div className="bg-red-100 rounded-lg shadow-sm p-3 border border-red-200">
              <div className="flex flex-col items-center text-center">
                <div className="w-6 h-6 bg-red-200 rounded-lg flex items-center justify-center mb-1">
                  <i className="fas fa-times-circle text-red-600 text-xs"></i>
                </div>
                <p className="text-lg font-bold text-red-600">{stats.check}</p>
                <p className="text-xs font-medium text-red-600">ผิดปกติ</p>
              </div>
            </div>

            <div className="bg-yellow-100 rounded-lg shadow-sm p-3 border border-yellow-200">
              <div className="flex flex-col items-center text-center">
                <div className="w-6 h-6 bg-yellow-200 rounded-lg flex items-center justify-center mb-1">
                  <i className="fas fa-clock text-yellow-600 text-xs"></i>
                </div>
                <p className="text-lg font-bold text-yellow-600">{stats.expired}</p>
                <p className="text-xs font-medium text-yellow-600">หมดอายุ</p>
              </div>
            </div>
          </div>

          {/* Overall Status Alert - Smaller */}
          {(() => {
            const overall = getOverallStatus();
            return (
              <div className={`${overall.bgColor} ${overall.borderColor} border rounded-md p-2`}>
                <div className="flex items-center justify-center">
                  <span className="text-sm mr-2">{overall.icon}</span>
                  <span className={`${overall.color} font-medium text-sm`}>
                    สถานะรวม: {overall.status}
                  </span>
                </div>
              </div>
            );
          })()}

          {/* Tab Navigation */}
          <div className="bg-white border-b border-gray-200 rounded-t-lg">
            <nav className="flex">
              <button
                onClick={() => setActiveTab('list')}
                className={`flex-1 py-3 px-4 text-center font-medium text-sm transition-colors ${
                  activeTab === 'list'
                    ? 'border-b-2 border-red-500 text-red-600 bg-red-50'
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <i className="fas fa-fire-extinguisher mr-2"></i>รายการถัง
              </button>
              <button
                onClick={() => setActiveTab('map')}
                className={`flex-1 py-3 px-4 text-center font-medium text-sm transition-colors ${
                  activeTab === 'map'
                    ? 'border-b-2 border-red-500 text-red-600 bg-red-50'
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <i className="fas fa-map mr-2"></i>แผนที่
              </button>
            </nav>
          </div>

          {/* Tab Content */}
          <div className="bg-white rounded-b-lg border border-gray-200 border-t-0 min-h-96">
            {activeTab === 'list' && (
              <div className="p-4">
                {/* Search and Filter Section */}
                <div className="mb-4">
                  <div className="flex gap-3 items-center">
                    {/* Search Input */}
                    <div className="flex-1 relative">
                      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none z-10">
                        <span className="text-gray-500 text-lg">🔍</span>
                      </div>
                      <input
                        type="text"
                        placeholder="ค้นหา"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-12 pr-3 py-3 bg-gray-100 border-0 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm italic"
                        style={{ fontStyle: 'italic' }}
                      />
                    </div>
                    
                    {/* Village Select */}
                    <div className="w-32">
                      <select
                        value={selectedVillage}
                        onChange={(e) => setSelectedVillage(e.target.value)}
                        className="w-full px-3 py-3 bg-gray-100 border-0 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm appearance-none"
                        style={{
                          backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%236b7280' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='m6 8 4 4 4-4'/%3e%3c/svg%3e")`,
                          backgroundPosition: 'right 0.5rem center',
                          backgroundRepeat: 'no-repeat',
                          backgroundSize: '1.5em 1.5em'
                        }}
                      >
                        <option value="">ทุกหมู่</option>
                        {[1,2,3,4,5,6,7,8,9].map(n => <option key={n} value={String(n)}>หมู่ {n}</option>)}
                      </select>
                    </div>
                  </div>
                </div>

                {/* List Header */}
                <div className="mb-4">
                  {(() => {
                    // Calculate filtered count
                    const filteredExtinguishers = allExtinguishers ? allExtinguishers.filter(extinguisher => {
                      // Filter by search query
                      const matchesSearch = !searchQuery || 
                        extinguisher.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                        extinguisher.id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                        extinguisher.qrCode?.toLowerCase().includes(searchQuery.toLowerCase());
                      
                      // Filter by village - village is a number, so compare directly
                      const matchesVillage = !selectedVillage || 
                        extinguisher.group?.includes(selectedVillage) ||
                        String(extinguisher.village) === selectedVillage ||
                        extinguisher.village === parseInt(selectedVillage);
                      
                      return matchesSearch && matchesVillage;
                    }) : [];

                    return (
                      <h3 className="text-lg font-semibold text-gray-800">
                        รายการถังดับเพลิง ({filteredExtinguishers.length})
                        {selectedVillage && (
                          <span className="text-sm font-normal text-gray-600 ml-2">
                            - หมู่ {selectedVillage}
                          </span>
                        )}
                        {searchQuery && (
                          <span className="text-sm font-normal text-gray-600 ml-2">
                            - ค้นหา: "{searchQuery}"
                          </span>
                        )}
                      </h3>
                    );
                  })()}
                </div>
                
                {/* Extinguisher List - Real Data */}
                <div className="space-y-3">
                  {allExtinguishers && allExtinguishers.length > 0 ? (
                    allExtinguishers
                      .filter(extinguisher => {
                        // Filter by search query
                        const matchesSearch = !searchQuery || 
                          extinguisher.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          extinguisher.id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                          extinguisher.qrCode?.toLowerCase().includes(searchQuery.toLowerCase());
                        
                        // Filter by village - village is a number, so compare directly
                        const matchesVillage = !selectedVillage || 
                          extinguisher.group?.includes(selectedVillage) ||
                          String(extinguisher.village) === selectedVillage ||
                          extinguisher.village === parseInt(selectedVillage);
                        
                        return matchesSearch && matchesVillage;
                      })
                      .map((extinguisher, index) => (
                        <div key={extinguisher.id || index} className="bg-white rounded-lg border border-gray-200 p-4 shadow-sm">
                          <div className="flex items-start">
                            {/* Fire Extinguisher Icon */}
                            <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center mr-4 flex-shrink-0">
                              <i className="fas fa-fire-extinguisher text-red-600 text-lg"></i>
                            </div>
                            
                            {/* Content */}
                            <div className="flex-1">
                              <h4 className="font-semibold text-gray-800 mb-1">
                                {extinguisher.name || 'ไม่ระบุชื่อ'}
                              </h4>
                              <div className="text-sm text-gray-600 space-y-1">
                                <p>รหัส: {extinguisher.id || 'ไม่ระบุ'}</p>
                                <p>บ้านเลขที่: {extinguisher.houseNo || 'ไม่ระบุ'}</p>
                                <p>หมู่บ้าน: {extinguisher.group || extinguisher.village || 'ไม่ระบุ'}</p>
                                <p>ขนาด: {extinguisher.size || 'ไม่ระบุ'}</p>
                                {extinguisher.lastCheck && (
                                  <p>ตรวจสอบล่าสุด: {extinguisher.lastCheck}</p>
                                )}
                              </div>
                              
                              {/* Status Badge */}
                              <div className="mt-2">
                                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                                  extinguisher.status === 'ready' || extinguisher.status === 'normal' || extinguisher.status === 'ปกติ'
                                    ? 'bg-green-100 text-green-800'
                                    : extinguisher.status === 'check' || extinguisher.status === 'abnormal' || extinguisher.status === 'ผิดปกติ' || extinguisher.status === 'needs_check'
                                    ? 'bg-red-100 text-red-800'
                                    : extinguisher.status === 'expired' || extinguisher.status === 'หมดอายุ'
                                    ? 'bg-yellow-100 text-yellow-800'
                                    : 'bg-gray-100 text-gray-800'
                                }`}>
                                  {extinguisher.status === 'ready' || extinguisher.status === 'normal' ? 'ปกติ' :
                                   extinguisher.status === 'check' || extinguisher.status === 'abnormal' || extinguisher.status === 'needs_check' ? 'ผิดปกติ' :
                                   extinguisher.status === 'expired' ? 'หมดอายุ' :
                                   extinguisher.status || 'ไม่ระบุ'}
                                </span>
                              </div>
                            </div>
                          </div>
                          
                          {/* Action Buttons */}
                          <div className="mt-4 flex gap-2 flex-wrap">
                            <button 
                              onClick={() => setCheckingExtinguisher(extinguisher)}
                              className="flex items-center px-3 py-2 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700 transition-colors"
                            >
                              <i className="fas fa-check mr-1"></i>
                              เช็คสถานะ
                            </button>
                            <button 
                              onClick={() => setHistoryExtinguisher(extinguisher)}
                              className="flex items-center px-3 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 transition-colors"
                            >
                              <i className="fas fa-history mr-1"></i>
                              ประวัติ
                            </button>
                            <button 
                              onClick={() => setSelectedExtinguisher(extinguisher)}
                              className="flex items-center px-3 py-2 bg-gray-600 text-white rounded-lg text-sm hover:bg-gray-700 transition-colors"
                            >
                              <i className="fas fa-info-circle mr-1"></i>
                              ข้อมูล
                            </button>
                          </div>
                        </div>
                      ))
                  ) : (
                    /* No Data Message */
                    <div className="text-center py-8 text-gray-500">
                      <i className="fas fa-fire-extinguisher text-4xl mb-4 opacity-50"></i>
                      <p>ไม่มีข้อมูลถังดับเพลิง</p>
                      <p className="text-sm mt-2">กดปุ่มรีเฟรชเพื่อโหลดข้อมูลใหม่</p>
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === 'map' && (
              <div className="p-4">
                <div className="bg-white rounded-lg shadow-md overflow-hidden">
                  {/* Map Header */}
                  <div className="bg-gradient-to-r from-red-500 to-orange-600 text-white p-4">
                    <h3 className="text-lg font-bold flex items-center">
                      <i className="fas fa-map-marked-alt mr-2"></i>
                      แผนที่ตำแหน่งถังดับเพลิง
                    </h3>
                    <p className="text-sm text-red-100 mt-1">
                      พบ {(allExtinguishers || []).filter(e => 
                        selectedMapVillage === 'ทั้งหมด' || 
                        String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                      ).length} ตำแหน่ง
                    </p>
                  </div>

                  {/* Village Filter */}
                  <div className="p-4 bg-gray-50 border-b">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      <i className="fas fa-filter mr-2"></i>กรองตามหมู่
                    </label>
                    <select
                      value={selectedMapVillage}
                      onChange={(e) => setSelectedMapVillage(e.target.value)}
                      className="w-full px-4 py-2 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 focus:outline-none"
                    >
                      <option value="ทั้งหมด">ทั้งหมด ({(allExtinguishers || []).length} รายการ)</option>
                      <option value="ทั้งหมด">ทั้งหมด</option>
                      {[1,2,3,4,5,6,7,8,9].map(n => (
                        <option key={n} value={`หมู่ ${n}`}>หมู่ {n} ({(allExtinguishers || []).filter(e => String(e.village) === String(n)).length} รายการ)</option>
                      ))}
                    </select>
                  </div>

                  {/* Google Map with Markers */}
                  <div className="relative">
                    <GoogleMapView 
                      extinguishers={(allExtinguishers || []).filter(e => 
                        selectedMapVillage === 'ทั้งหมด' || 
                        String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                      )} 
                      selectedGroup={selectedMapVillage}
                    />
                  </div>

                  {/* Extinguisher List */}
                  <div className="p-4 bg-gray-50 border-t">
                    <h4 className="text-sm font-semibold text-gray-800 mb-3 flex items-center">
                      <i className="fas fa-list mr-2 text-blue-600"></i>
                      รายการตำแหน่งถังดับเพลิง
                      {selectedMapVillage !== 'ทั้งหมด' && (
                        <span className="ml-2 text-xs text-blue-600 bg-blue-50 px-2 py-1 rounded-full">
                          {selectedMapVillage}
                        </span>
                      )}
                    </h4>
                    <div className="space-y-2 max-h-64 overflow-y-auto">
                      {allExtinguishers && allExtinguishers
                        .filter(e => 
                          selectedMapVillage === 'ทั้งหมด' || 
                          String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                        )
                        .length > 0 ? (
                        allExtinguishers
                          .filter(e => 
                            selectedMapVillage === 'ทั้งหมด' || 
                            String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                          )
                          .map((ext, idx) => (
                          <div key={idx} className="bg-white rounded-lg p-3 shadow-sm border border-gray-200 hover:shadow-md transition-shadow">
                            <div className="flex items-center justify-between">
                              <div className="flex items-center flex-1">
                                <div className={`w-3 h-3 rounded-full mr-3 flex-shrink-0 ${
                                  ext.status === 'ready' || ext.status === 'normal' || ext.status === 'ปกติ' ? 'bg-green-500' :
                                  ext.status === 'check' || ext.status === 'abnormal' || ext.status === 'ผิดปกติ' ? 'bg-red-500' :
                                  'bg-yellow-500'
                                }`}></div>
                                <div className="flex-1 min-w-0">
                                  <p className="font-semibold text-gray-800 text-sm">{ext.id}</p>
                                  <p className="text-xs text-gray-600 truncate">{ext.name} - หมู่ {ext.village}</p>
                                  {ext.lat && ext.lng && (
                                    <p className="text-xs text-gray-500 mt-1">
                                      <i className="fas fa-map-pin mr-1"></i>
                                      {ext.lat?.toFixed(6)}, {ext.lng?.toFixed(6)}
                                    </p>
                                  )}
                                </div>
                              </div>
                              {ext.lat && ext.lng && (
                                <button
                                  onClick={() => window.open(`https://www.google.com/maps?q=${ext.lat},${ext.lng}`, '_blank')}
                                  className="ml-3 px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-xs font-medium transition-colors flex-shrink-0"
                                >
                                  <i className="fas fa-external-link-alt mr-1"></i>
                                  เปิด
                                </button>
                              )}
                            </div>
                          </div>
                        ))
                      ) : (
                        <div className="text-center py-8 text-gray-500 text-sm">
                          <i className="fas fa-info-circle mr-1"></i>
                          {selectedMapVillage === 'ทั้งหมด' 
                            ? 'ไม่มีข้อมูลถังดับเพลิง'
                            : `ไม่มีถังดับเพลิงใน${selectedMapVillage}`
                          }
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Legend */}
                  <div className="p-4 bg-white border-t">
                    <h4 className="text-sm font-semibold text-gray-800 mb-2">สถานะ</h4>
                    <div className="flex flex-wrap gap-4 text-xs">
                      <div className="flex items-center">
                        <div className="w-3 h-3 bg-green-500 rounded-full mr-2"></div>
                        <span className="text-gray-700">ปกติ ({
                          (allExtinguishers || [])
                            .filter(e => 
                              selectedMapVillage === 'ทั้งหมด' || 
                              String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                            )
                            .filter(e => e.status === 'ready' || e.status === 'normal' || e.status === 'ปกติ').length
                        })</span>
                      </div>
                      <div className="flex items-center">
                        <div className="w-3 h-3 bg-red-500 rounded-full mr-2"></div>
                        <span className="text-gray-700">ผิดปกติ ({
                          (allExtinguishers || [])
                            .filter(e => 
                              selectedMapVillage === 'ทั้งหมด' || 
                              String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                            )
                            .filter(e => e.status === 'check' || e.status === 'abnormal' || e.status === 'ผิดปกติ').length
                        })</span>
                      </div>
                      <div className="flex items-center">
                        <div className="w-3 h-3 bg-yellow-500 rounded-full mr-2"></div>
                        <span className="text-gray-700">หมดอายุ ({
                          (allExtinguishers || [])
                            .filter(e => 
                              selectedMapVillage === 'ทั้งหมด' || 
                              String(e.village) === selectedMapVillage.replace('หมู่ ', '')
                            )
                            .filter(e => e.status === 'expired' || e.status === 'หมดอายุ').length
                        })</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminView;