import React, { useState } from 'react';

const InfoView = ({ currentExtinguisher, onSearch, onShowHistory, onChangeView, allExtinguishers, triggerEmergencyMenu }) => {
  const [searchInput, setSearchInput] = useState('');
  const [checkHistory, setCheckHistory] = useState([]);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [selectedRecord, setSelectedRecord] = useState(null);
  const [showEmergencyMenu, setShowEmergencyMenu] = useState(false);
  const [showPhoneSetup, setShowPhoneSetup] = useState(false);
  const [showEmergencyConfirm, setShowEmergencyConfirm] = useState(false);
  const [userPhone, setUserPhone] = useState('');
  const [userName, setUserName] = useState('');
  const [userVillage, setUserVillage] = useState('');
  const [tempPhone, setTempPhone] = useState('');
  const [tempName, setTempName] = useState('');
  const [tempVillage, setTempVillage] = useState('');

  React.useEffect(() => {
    if (triggerEmergencyMenu === 0) {
      setShowEmergencyMenu(false);
    } else if (triggerEmergencyMenu > 0) {
      setShowEmergencyMenu(true);
    }
  }, [triggerEmergencyMenu]);

  // Load user phone from localStorage
  React.useEffect(() => {
    const savedPhone = localStorage.getItem('userPhone');
    if (savedPhone) setUserPhone(savedPhone);
    const savedName = localStorage.getItem('userName');
    if (savedName) setUserName(savedName);
    const savedVillage = localStorage.getItem('userVillage');
    if (savedVillage) setUserVillage(savedVillage);
  }, []);

  // Load check history when extinguisher changes
  React.useEffect(() => {
    if (currentExtinguisher && currentExtinguisher.id) {
      loadCheckHistory(currentExtinguisher.id);
    } else {
      setCheckHistory([]);
    }
  }, [currentExtinguisher]);

  // Initialize QR Scanner when modal opens
  React.useEffect(() => {
    if (showScanner) {
      // Dynamically import html5-qrcode
      import('html5-qrcode').then(({ Html5Qrcode }) => {
        const html5QrCode = new Html5Qrcode("qr-reader");
        
        html5QrCode.start(
          { facingMode: "environment" },
          {
            fps: 10,
            qrbox: { width: 250, height: 250 }
          },
          (decodedText) => {
            html5QrCode.stop().then(() => {
              handleScanSuccess(decodedText);
            });
          },
          (errorMessage) => {
            // Ignore scan errors
          }
        ).catch((err) => {
          console.error('Error starting QR scanner:', err);
          alert('ไม่สามารถเปิดกล้องได้\nกรุณาอนุญาตการเข้าถึงกล้อง');
          setShowScanner(false);
        });

        // Cleanup
        return () => {
          html5QrCode.stop().catch(() => {});
        };
      });
    }
  }, [showScanner]);

  const loadCheckHistory = async (extinguisherId) => {
    setLoadingHistory(true);
    try {
      // Import gasService dynamically
      const gasService = (await import('../services/gasServiceSimple')).default;
      const result = await gasService.getCheckHistory(extinguisherId);
      if (result && result.success) {
        setCheckHistory(result.history || []);
      } else {
        setCheckHistory([]);
      }
    } catch (error) {
      console.error('Error loading check history:', error);
      setCheckHistory([]);
    } finally {
      setLoadingHistory(false);
    }
  };

  const handleSearch = () => {
    onSearch(searchInput);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  const handleScanSuccess = (decodedText) => {
    setSearchInput(decodedText);
    setShowScanner(false);
    onSearch(decodedText);
  };

  const handleEmergencyCall = async () => {
    const emergencyPhone = '035-582923';
    
    // ถ้ายังไม่มีเบอร์ ให้กรอกก่อน
    if (!userPhone) {
      setShowPhoneSetup(true);
      return;
    }

    // แสดง confirm dialog ก่อน
    setShowEmergencyConfirm(true);
  };

  const handleEmergencyConfirmed = async () => {
    setShowEmergencyConfirm(false);
    const emergencyPhone = '035-582923';
    
    // โทรออกทันที ไม่รอยืนยัน
    window.location.href = `tel:${emergencyPhone}`;

    // บันทึก GAS ทันที (ไม่รอ GPS)
    const gasUrl = process.env.REACT_APP_GAS_WEB_APP_URL;
    console.log('🚨 Emergency GAS URL:', gasUrl);
    if (gasUrl) {
      const p = new URLSearchParams({
        action: 'saveEmergencyAlert',
        phone: userPhone,
        name: userName || '',
        village: userVillage || '',
        lat: '',
        lng: '',
        googleMapsLink: ''
      });
      console.log('🚨 Sending to GAS:', gasUrl + '?' + p.toString());
      fetch(`${gasUrl}?${p}`)
        .then(r => r.text())
        .then(t => console.log('🚨 GAS response:', t))
        .catch(e => console.error('🚨 GAS error:', e));
    }

    // ส่ง Telegram + GPS เบื้องหลัง
    try {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
          async (position) => {
            const lat = position.coords.latitude;
            const lng = position.coords.longitude;
            const googleMapsLink = `https://www.google.com/maps?q=${lat},${lng}`;
            
            try {
              const message = `🚨 แจ้งเหตุฉุกเฉิน - จาก Application\n\n` +
                `👤 ผู้แจ้ง: ${userName || userPhone}\n` +
                `📞 เบอร์โทร: ${userPhone}\n` +
                `🏘️ หมู่: ${userVillage ? 'หมู่ ' + userVillage : 'ไม่ระบุ'}\n` +
                `📍 พิกัด: ${lat.toFixed(6)}, ${lng.toFixed(6)}\n` +
                `🗺️ Google Maps: ${googleMapsLink}\n` +
                `⏰ เวลา: ${new Date().toLocaleString('th-TH')}`;
              
              await sendTelegramMessage(message);

              // อัพเดท GAS ด้วยพิกัด
              if (gasUrl) {
                const p2 = new URLSearchParams({
                  action: 'saveEmergencyAlert',
                  phone: userPhone,
                  name: userName || '',
                  village: userVillage || '',
                  lat: lat.toFixed(6),
                  lng: lng.toFixed(6),
                  googleMapsLink
                });
                fetch(`${gasUrl}?${p2}`).catch(() => {});
              }

              setTimeout(() => {
                alert('✅ ส่งข้อมูลตำแหน่งไปยัง Telegram สำเร็จ');
              }, 1000);
            } catch (error) {
              console.error('Error sending to Telegram:', error);
            }
          },
          (error) => {
            console.error('Error getting location:', error);
            // ไม่แจ้งเตือน error เพื่อไม่รบกวนการโทร
          }
        );
      }
    } catch (error) {
      console.error('Emergency call error:', error);
      // ไม่แจ้งเตือน error เพื่อไม่รบกวนการโทร
    }
  };

  const handleSavePhone = () => {
    if (!tempPhone || tempPhone.length < 9) {
      alert('กรุณากรอกเบอร์โทรศัพท์ให้ถูกต้อง');
      return;
    }
    if (!tempName.trim()) {
      alert('กรุณากรอกชื่อ-นามสกุล');
      return;
    }
    if (!tempVillage) {
      alert('กรุณาเลือกหมู่ที่');
      return;
    }
    localStorage.setItem('userPhone', tempPhone);
    localStorage.setItem('userName', tempName.trim());
    localStorage.setItem('userVillage', tempVillage);
    setUserPhone(tempPhone);
    setUserName(tempName.trim());
    setUserVillage(tempVillage);
    setShowPhoneSetup(false);
    setTempPhone('');
    setTempName('');
    setTempVillage('');
    alert('✅ บันทึกข้อมูลเรียบร้อย');
  };

  const handlePhoneCall = (phoneNumber) => {
    // โทรออกเลย ไม่มี popup
    window.location.href = `tel:${phoneNumber}`;
  };

  const sendTelegramMessage = async (message) => {
    const botToken = process.env.REACT_APP_TELEGRAM_BOT_TOKEN;
    const chatId = process.env.REACT_APP_TELEGRAM_CHAT_ID;
    
    if (!botToken || !chatId || botToken === 'YOUR_BOT_TOKEN_HERE') {
      throw new Error('Telegram not configured');
    }
    
    const url = `https://api.telegram.org/bot${botToken}/sendMessage`;
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        chat_id: chatId,
        text: message,
        parse_mode: 'HTML'
      })
    });
    
    if (!response.ok) {
      throw new Error('Failed to send Telegram message');
    }
    
    return response.json();
  };

  const getTypeText = (type) => {
    const types = {
      'water': 'น้ำ',
      'foam': 'โฟม',
      'powder': 'ผงเคมีแห้ง',
      'co2': 'คาร์บอนไดออกไซด์'
    };
    return types[type] || 'ผงเคมีแห้ง';
  };

  const getStatusText = (status) => {
    const statuses = {
      'ready': 'พร้อมใช้',
      'check': 'ต้องตรวจสอบ',
      'expired': 'หมดอายุ',
      'maintenance': 'ซ่อมบำรุง'
    };
    return statuses[status] || 'พร้อมใช้';
  };

  const getStatusColor = (status) => {
    const colors = {
      'ready': 'bg-green-100 text-green-800',
      'check': 'bg-yellow-100 text-yellow-800',
      'expired': 'bg-red-100 text-red-800',
      'maintenance': 'bg-blue-100 text-blue-800'
    };
    return colors[status] || 'bg-green-100 text-green-800';
  };

  return (
    <div className="bg-gradient-to-b from-red-50 to-orange-50 pb-4">
      {/* Emergency Confirm Modal */}
      {showEmergencyConfirm && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-sm w-full p-6 text-center">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <i className="fas fa-phone-volume text-3xl text-red-600"></i>
            </div>
            <h3 className="text-xl font-bold text-gray-800 mb-2">ยืนยันการโทรฉุกเฉิน</h3>
            <p className="text-gray-600 text-sm mb-6">ระบบจะโทรหาฝ่ายป้องกันและส่งตำแหน่งของคุณทันที</p>
            <div className="flex gap-3">
              <button
                onClick={() => setShowEmergencyConfirm(false)}
                className="flex-1 px-4 py-3 bg-gray-200 hover:bg-gray-300 text-gray-700 rounded-lg font-medium transition-colors"
              >
                ยกเลิก
              </button>
              <button
                onClick={handleEmergencyConfirmed}
                className="flex-1 px-4 py-3 bg-red-600 hover:bg-red-700 text-white rounded-lg font-bold transition-colors"
              >
                <i className="fas fa-phone mr-2"></i>ยืนยัน
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Phone Setup Modal */}
      {showPhoneSetup && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <i className="fas fa-user text-3xl text-blue-600"></i>
              </div>
              <h3 className="text-xl font-bold text-gray-800 mb-2">กรอกข้อมูลผู้แจ้ง</h3>
              <p className="text-sm text-gray-600">เพื่อให้เจ้าหน้าที่สามารถติดต่อกลับได้</p>
            </div>

            <div className="space-y-4 mb-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">ชื่อ-นามสกุล <span className="text-red-500">*</span></label>
                <input
                  type="text"
                  value={tempName}
                  onChange={(e) => setTempName(e.target.value)}
                  placeholder="ชื่อ นามสกุล"
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">หมู่ที่</label>
                <select
                  value={tempVillage}
                  onChange={(e) => setTempVillage(e.target.value)}
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 focus:outline-none"
                >
                  <option value="">เลือกหมู่</option>
                  {[1,2,3,4,5,6,7,8,9].map(n => <option key={n} value={n}>หมู่ {n}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">เบอร์โทรศัพท์ <span className="text-red-500">*</span></label>
                <input
                  type="tel"
                  value={tempPhone}
                  onChange={(e) => setTempPhone(e.target.value.replace(/[^0-9]/g, ''))}
                  placeholder="08XXXXXXXX"
                  maxLength="10"
                  className="w-full px-4 py-3 border-2 border-gray-200 rounded-lg focus:border-blue-500 focus:ring-2 focus:ring-blue-200 focus:outline-none text-center text-lg font-mono"
                />
                <p className="text-xs text-gray-500 mt-1 text-center">
                  <i className="fas fa-lock mr-1"></i>เก็บไว้ในเครื่องของคุณเท่านั้น
                </p>
              </div>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => { setShowPhoneSetup(false); setTempPhone(''); setTempName(''); setTempVillage(''); }}
                className="flex-1 px-4 py-3 bg-gray-200 hover:bg-gray-300 text-gray-700 rounded-lg font-medium transition-colors"
              >
                ยกเลิก
              </button>
              <button
                onClick={handleSavePhone}
                className="flex-1 px-4 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-medium transition-colors"
              >
                <i className="fas fa-save mr-2"></i>บันทึก
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Emergency Menu Modal */}
      {showEmergencyMenu && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4" style={{ paddingTop: '80px', paddingBottom: '90px' }}>
          <div className="bg-white rounded-2xl max-w-md w-full max-h-full flex flex-col overflow-hidden">
            {/* Header */}
            <div className="bg-gradient-to-r from-red-600 to-red-700 rounded-t-2xl p-6 text-white">
              <div className="flex items-center justify-between">
                <div className="flex items-center">
                  <div className="w-12 h-12 bg-white bg-opacity-20 rounded-full flex items-center justify-center mr-3">
                    <i className="fas fa-phone-volume text-xl"></i>
                  </div>
                  <div>
                    <h3 className="text-xl font-bold">เบอร์โทรฉุกเฉิน</h3>
                    <p className="text-red-100 text-sm">เลือกหน่วยงานที่ต้องการติดต่อ</p>
                  </div>
                </div>
                <button
                  onClick={() => setShowEmergencyMenu(false)}
                  className="w-10 h-10 bg-white bg-opacity-20 hover:bg-opacity-30 rounded-full flex items-center justify-center transition-colors"
                >
                  <i className="fas fa-times text-lg"></i>
                </button>
              </div>
            </div>

            {/* Emergency Numbers List */}
            <div className="p-4 space-y-3 overflow-y-auto flex-1">
              {/* งานป้องกัน (เทศบาล) */}
              <button
                onClick={() => handlePhoneCall('035440568')}
                className="w-full bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 text-white rounded-xl p-4 transition-all duration-200 shadow-md hover:shadow-lg transform hover:scale-105"
              >
                <div className="flex items-center">
                  <div className="w-14 h-14 bg-white bg-opacity-20 rounded-full flex items-center justify-center mr-4 flex-shrink-0">
                    <i className="fas fa-building text-2xl"></i>
                  </div>
                  <div className="text-left flex-1">
                    <h4 className="text-lg font-bold mb-1">งานป้องกัน (อบต.สระกระโจม)</h4>
                    <p className="text-blue-50 text-sm font-mono">📞 0-3544-0568</p>
                  </div>
                  <i className="fas fa-chevron-right text-xl opacity-50"></i>
                </div>
              </button>

              {/* เหตุเพลิงไหม้ */}
              <button
                onClick={() => handlePhoneCall('199')}
                className="w-full bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white rounded-xl p-4 transition-all duration-200 shadow-md hover:shadow-lg transform hover:scale-105"
              >
                <div className="flex items-center">
                  <div className="w-14 h-14 bg-white bg-opacity-20 rounded-full flex items-center justify-center mr-4 flex-shrink-0">
                    <i className="fas fa-fire-extinguisher text-2xl"></i>
                  </div>
                  <div className="text-left flex-1">
                    <h4 className="text-lg font-bold mb-1">เหตุเพลิงไหม้</h4>
                    <p className="text-orange-100 text-sm font-mono">📞 199</p>
                  </div>
                  <i className="fas fa-chevron-right text-xl opacity-50"></i>
                </div>
              </button>

              {/* ตำรวจ */}
              <button
                onClick={() => handlePhoneCall('191')}
                className="w-full bg-gradient-to-r from-indigo-600 to-indigo-700 hover:from-indigo-700 hover:to-indigo-800 text-white rounded-xl p-4 transition-all duration-200 shadow-md hover:shadow-lg transform hover:scale-105"
              >
                <div className="flex items-center">
                  <div className="w-14 h-14 bg-white bg-opacity-20 rounded-full flex items-center justify-center mr-4 flex-shrink-0">
                    <i className="fas fa-shield-alt text-2xl"></i>
                  </div>
                  <div className="text-left flex-1">
                    <h4 className="text-lg font-bold mb-1">ตำรวจ</h4>
                    <p className="text-indigo-50 text-sm font-mono">📞 191</p>
                  </div>
                  <i className="fas fa-chevron-right text-xl opacity-50"></i>
                </div>
              </button>

              {/* รถกู้ชีพ */}
              <button
                onClick={() => handlePhoneCall('1669')}
                className="w-full bg-gradient-to-r from-green-600 to-green-700 hover:from-green-700 hover:to-green-800 text-white rounded-xl p-4 transition-all duration-200 shadow-md hover:shadow-lg transform hover:scale-105"
              >
                <div className="flex items-center">
                  <div className="w-14 h-14 bg-white bg-opacity-20 rounded-full flex items-center justify-center mr-4 flex-shrink-0">
                    <i className="fas fa-ambulance text-2xl"></i>
                  </div>
                  <div className="text-left flex-1">
                    <h4 className="text-lg font-bold mb-1">รถกู้ชีพ</h4>
                    <p className="text-green-50 text-sm font-mono">📞 1669</p>
                  </div>
                  <i className="fas fa-chevron-right text-xl opacity-50"></i>
                </div>
              </button>
            </div>

            {/* Footer */}
            <div className="p-4 bg-gray-50 rounded-b-2xl border-t">
              <p className="text-center text-xs text-gray-600">
                <i className="fas fa-info-circle mr-1"></i>
                กดเลือกหน่วยงานเพื่อโทรออกทันที
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Check Detail Modal */}
      {selectedRecord && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-2xl max-w-2xl w-full my-8">
            {/* Header */}
            <div className="sticky top-0 bg-white border-b rounded-t-2xl p-4 flex items-center justify-between z-10">
              <div>
                <h3 className="text-lg font-bold text-gray-800">รายละเอียดการตรวจสอบ</h3>
                <p className="text-sm text-gray-600">{selectedRecord.timestamp}</p>
              </div>
              <button
                onClick={() => setSelectedRecord(null)}
                className="w-10 h-10 bg-gray-100 hover:bg-gray-200 rounded-full flex items-center justify-center transition-colors"
              >
                <i className="fas fa-times text-gray-600"></i>
              </button>
            </div>

            {/* Content */}
            <div className="p-4 space-y-4">
              {/* Summary */}
              <div className={`rounded-lg p-4 ${
                (selectedRecord.overallStatus === 'normal' || selectedRecord.overallStatus === 'ปกติ')
                  ? 'bg-green-50 border border-green-200' 
                  : 'bg-red-50 border border-red-200'
              }`}>
                <div className="flex items-center justify-between mb-3">
                  <div>
                    <h4 className="font-semibold text-gray-800">สรุปผลการตรวจสอบ</h4>
                    <p className="text-sm text-gray-600">ผู้ตรวจสอบ: {selectedRecord.checkerName}</p>
                  </div>
                  <div className="text-right">
                    {(selectedRecord.overallStatus === 'normal' || selectedRecord.overallStatus === 'ปกติ') ? (
                      <span className="text-2xl text-green-600">
                        <i className="fas fa-check-circle"></i>
                      </span>
                    ) : (
                      <span className="text-2xl text-red-600">
                        <i className="fas fa-exclamation-triangle"></i>
                      </span>
                    )}
                  </div>
                </div>
                <div className="grid grid-cols-3 gap-4 text-center">
                  <div>
                    <p className="text-2xl font-bold text-gray-800">{selectedRecord.totalItems}</p>
                    <p className="text-xs text-gray-600">รายการทั้งหมด</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-green-600">{selectedRecord.passedItems}</p>
                    <p className="text-xs text-gray-600">ปกติ</p>
                  </div>
                  <div>
                    <p className="text-2xl font-bold text-red-600">{selectedRecord.failedItems}</p>
                    <p className="text-xs text-gray-600">ผิดปกติ</p>
                  </div>
                </div>
              </div>

              {/* Check Items */}
              <div className="space-y-3">
                {[
                  { key: 'pressure', label: 'ความดันในถัง' },
                  { key: 'pin', label: 'สลักนิรภัย' },
                  { key: 'hose', label: 'สายและหัวฉีด' },
                  { key: 'body', label: 'ตัวถังและฉลาก' },
                  { key: 'location', label: 'ตำแหน่งการเข้าถึง' },
                  { key: 'mount', label: 'ขาตั้งการยึด' }
                ].map(({ key, label }) => {
                  const status = selectedRecord[`${key}Status`];
                  const note = selectedRecord[`${key}Note`];
                  
                  return (
                    <div key={key} className="bg-gray-50 rounded-lg p-3">
                      <div className="flex items-center justify-between mb-2">
                        <h5 className="font-semibold text-gray-800 text-sm">{label}</h5>
                        {status === 'normal' ? (
                          <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                            <i className="fas fa-check-circle mr-1"></i>
                            ปกติ
                          </span>
                        ) : (
                          <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-red-100 text-red-800">
                            <i className="fas fa-times-circle mr-1"></i>
                            ผิดปกติ
                          </span>
                        )}
                      </div>
                      {note && (
                        <div className="mt-2 p-2 bg-white rounded border border-gray-200">
                          <p className="text-xs text-gray-700">
                            <i className="fas fa-comment-alt text-gray-400 mr-1"></i>
                            {note}
                          </p>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* QR Scanner Modal */}
      {showScanner && (
        <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-gray-800">สแกน QR Code</h3>
              <button
                onClick={() => setShowScanner(false)}
                className="w-10 h-10 bg-gray-100 hover:bg-gray-200 rounded-full flex items-center justify-center transition-colors"
              >
                <i className="fas fa-times text-gray-600"></i>
              </button>
            </div>
            
            {/* QR Scanner Component */}
            <div className="bg-gray-900 rounded-lg overflow-hidden mb-4">
              <div id="qr-reader" style={{ width: '100%' }}></div>
            </div>
            
            <p className="text-sm text-gray-600 text-center">
              <i className="fas fa-info-circle mr-1"></i>
              วางกล้องให้ตรงกับ QR Code
            </p>
          </div>
        </div>
      )}

      {/* Emergency Grid Cards */}
      <div className="px-4 pb-4">
        <div className="grid grid-cols-1 gap-4">

          {/* รถดับเพลิง/เจ้าหน้าที่ */}
          <button onClick={() => onChangeView('fire-report')}
            className="emergency-card"
            style={{ background: 'linear-gradient(135deg, #f97316 0%, #ea580c 100%)', minHeight: '160px', flexDirection: 'row', justifyContent: 'flex-start', padding: '1.5rem 2rem', gap: '1.5rem' }}>
            {/* ไอคอน */}
            <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center', minWidth: '72px', height: '72px', background: 'rgba(255,255,255,0.18)', borderRadius: '50%' }}>
              <i className="fas fa-helmet-safety" style={{ position: 'absolute', top: '4px', left: '50%', transform: 'translateX(-50%)', fontSize: '1rem', color: '#fde68a' }}></i>
              <i className="fas fa-truck" style={{ fontSize: '2.2rem', color: 'white' }}></i>
              <i className="fas fa-fire" style={{ position: 'absolute', top: '2px', right: '4px', fontSize: '0.9rem', color: '#fde68a', filter: 'drop-shadow(0 0 4px #f97316)' }}></i>
            </div>
            {/* ข้อความ */}
            <div style={{ textAlign: 'left' }}>
              <div style={{ fontSize: '1.35rem', fontWeight: '800', color: 'white', lineHeight: 1.2 }}>รถดับเพลิง/เจ้าหน้าที่</div>
              <div style={{ fontSize: '0.9rem', color: 'rgba(255,255,255,0.8)', marginTop: '0.3rem' }}>Fire Truck / Officer</div>
              <div style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.65)', marginTop: '0.4rem' }}>กดเพื่อแจ้งเหตุเพลิงไหม้</div>
            </div>
            <i className="fas fa-chevron-right" style={{ marginLeft: 'auto', fontSize: '1.2rem', color: 'rgba(255,255,255,0.5)' }}></i>
          </button>

          {/* ลมพายุ */}
          <button onClick={() => onChangeView('storm-report')}
            className="emergency-card"
            style={{ background: 'linear-gradient(135deg, #0ea5e9 0%, #0369a1 100%)', minHeight: '160px', flexDirection: 'row', justifyContent: 'flex-start', padding: '1.5rem 2rem', gap: '1.5rem' }}>
            {/* ไอคอน */}
            <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center', minWidth: '72px', height: '72px', background: 'rgba(255,255,255,0.18)', borderRadius: '50%' }}>
              <i className="fas fa-tree" style={{ fontSize: '2.2rem', color: 'white', transform: 'rotate(-15deg)' }}></i>
              <i className="fas fa-wind" style={{ position: 'absolute', top: '4px', right: '2px', fontSize: '0.95rem', color: '#bae6fd', opacity: 0.95 }}></i>
            </div>
            {/* ข้อความ */}
            <div style={{ textAlign: 'left' }}>
              <div style={{ fontSize: '1.35rem', fontWeight: '800', color: 'white', lineHeight: 1.2 }}>แจ้งเหตุลมพายุ</div>
              <div style={{ fontSize: '0.9rem', color: 'rgba(255,255,255,0.8)', marginTop: '0.3rem' }}>Storm Report</div>
              <div style={{ fontSize: '0.8rem', color: 'rgba(255,255,255,0.65)', marginTop: '0.4rem' }}>กดเพื่อแจ้งเหตุพายุฤดูร้อน</div>
            </div>
            <i className="fas fa-chevron-right" style={{ marginLeft: 'auto', fontSize: '1.2rem', color: 'rgba(255,255,255,0.5)' }}></i>
          </button>

        </div>
      </div>

      {/* Test Button - Removed for production */}
    </div>
  );
};

export default InfoView;